import{_ as o,o as t,c as s,a5 as n}from"./chunks/framework.CslsFoWx.js";const g=JSON.parse('{"title":"18 — Assistant IA (serveur MCP)","description":"","frontmatter":{},"headers":[],"relativePath":"specs/18-mcp.md","filePath":"generated/specs/18-mcp.md","lastUpdated":null}'),r={name:"specs/18-mcp.md"};function a(i,e,c,d,u,l){return t(),s("div",null,[...e[0]||(e[0]=[n('<div><h1 id="_18-—-assistant-ia-serveur-mcp" tabindex="-1">18 — Assistant IA (serveur MCP) <a class="header-anchor" href="#_18-—-assistant-ia-serveur-mcp" aria-label="Permalink to &quot;18 — Assistant IA (serveur MCP)&quot;">​</a></h1><blockquote><p>Phase : 3 bis · Modules concernés : cœur (aucun module magasin ; droit de formule <code>MCP_ACCESS</code>) · Applications concernées : serveur, nouveau service <code>mcp/</code>, back-office web ; depuis le lot VEN-34 (propositions), apps caisse iOS et Android (écran « Propositions » sous PIN manager).</p></blockquote><blockquote><p>Cette spec fixe les <strong>règles</strong> des lots livrés (M0, M1, M3, M2) et du lot <strong>VEN-34</strong> (M4 + GaaS A2, écriture encadrée par propositions, fiche <a href="./../lots/VEN-34">lots/VEN-34.md</a>, RG-MCP-83 → 104). Le besoin, l&#39;expérience visée, le catalogue d&#39;outils, le plan des lots suivants (U2 → U6, M4) et les sources sont dans <a href="/VendoraSystem-docs/architecture/mcp-vendora">MCP-VENDORA.md</a> ; le mode d&#39;emploi commerçant dans <a href="/VendoraSystem-docs/architecture/mcp-guide">MCP-GUIDE-UTILISATEUR.md</a> ; les routes, champs et codes dans <a href="/VendoraSystem-docs/architecture/api-publique">API-PUBLIQUE.md</a> ; l&#39;exploitation du service dans <a href="./../../mcp/README"><code>mcp/README.md</code></a>. Décisions d&#39;Ahmed du 11/11/2026 : Kotlin, OAuth avant la page du back-office, pas de données clients en v1, droit <code>MCP_ACCESS</code> par formule. Décisions d&#39;Ahmed du 15/11/2026 (projet Linear P-VEN-7) : <strong>parité d&#39;écriture avec le back-office, toujours par proposition validée</strong> ; liste fermée d&#39;exclusions (VEN-43, option A) ; données clients rouvertes en deux temps (VEN-44, option A). Cadrage VEN-42, <strong>validé par Ahmed le 16/11/2026</strong> (recommandations Q1 → Q24 de la fiche du socle retenues telles quelles) : RG-MCP-84 réécrite, RG-MCP-105 → 132, matrice <a href="./../lots/MCP-ECRITURE-MATRICE">lots/MCP-ECRITURE-MATRICE.md</a>, fiche du socle <a href="./../lots/MCP-ECRITURE-SOCLE">lots/MCP-ECRITURE-SOCLE.md</a>. Revue de sécurité VEN-58 vague 1, <strong>validée par Ahmed le 18/11/2026</strong> : RG-MCP-138, 139, renvois dans RG-MCP-107, 110 et 123 ; rapport <a href="./../securite/MCP-ECRITURE-VAGUE-1">securite/MCP-ECRITURE-VAGUE-1.md</a>. Création d&#39;un produit (VEN-49, lot 3), <strong>validée par Ahmed le 19/11/2026</strong>, livrée éteinte : RG-MCP-140, 141, renvois dans RG-MCP-117, 119, 123, 125 et 138 ; fiche <a href="./../lots/MCP-ECRITURE-PRODUIT-CREER">lots/MCP-ECRITURE-PRODUIT-CREER.md</a>, rapport de revue complète <a href="./../securite/MCP-ECRITURE-PRODUIT-CREER">securite/MCP-ECRITURE-PRODUIT-CREER.md</a>. Accès limité et renommage (VEN-49, lot 4a), <strong>validé par Ahmed le 19/11/2026</strong>, livré le 19/11/2026 (<code>c6099fff</code>) : RG-MCP-143, 144, renvois dans RG-MCP-01, 03, 135 et 140 ; fiche <a href="./../lots/MCP-LECTURE-ACCES-LIMITE">lots/MCP-LECTURE-ACCES-LIMITE.md</a>. Lectures de l&#39;assistant (VEN-49, lot 4b), <strong>validé par Ahmed le 19/11/2026</strong>, livré le 19/11/2026 (<code>a9d51e76</code>) : RG-MCP-142, renvois dans RG-MCP-13, 14 et 16 ; fiche <a href="./../lots/MCP-ECRITURE-PRODUIT-LIRE">lots/MCP-ECRITURE-PRODUIT-LIRE.md</a>. Étendre un produit (VEN-49, lot 5), <strong>validé par Ahmed le 19/11/2026</strong>, livré <strong>éteint</strong> le 20/11/2026 (<code>93a23d61</code>) : RG-MCP-145, renvois dans RG-MCP-91 et 138 ; spec 14 RG-MSTORE-19 ; fiche <a href="./../lots/MCP-ECRITURE-PRODUIT-ETENDRE">lots/MCP-ECRITURE-PRODUIT-ETENDRE.md</a>. Prix groupé (VEN-51), <strong>validé par délégation d&#39;Ahmed le 19/11/2026</strong>, livré <strong>éteint</strong> le 20/11/2026 (<code>8c45a025</code>, jeton de forme <code>PRICE_CHANGE_GROUP</code>) : RG-MCP-146, 147, renvois dans RG-MCP-93, 110, 116 et 119 ; fiche <a href="./../lots/MCP-ECRITURE-PRIX-GROUPE">lots/MCP-ECRITURE-PRIX-GROUPE.md</a>. Catégories (VEN-50, lot 1), <strong>validé par délégation d&#39;Ahmed le 19/11/2026</strong>, livré <strong>éteint</strong> le 20/11/2026 (<code>95c3d89f</code>) : RG-MCP-148 (créer, règles communes), 149 (modifier), 150 (outil) ; spec 02 RG-CAT-93 (ordre unique), RG-CAT-94 (verrou d&#39;arbre) ; fiche <a href="./../lots/MCP-ECRITURE-CATEGORIES">lots/MCP-ECRITURE-CATEGORIES.md</a>.</p></blockquote><h2 id="_1-objectif-perimetre" tabindex="-1">1. Objectif &amp; périmètre <a class="header-anchor" href="#_1-objectif-perimetre" aria-label="Permalink to &quot;1. Objectif &amp; périmètre&quot;">​</a></h2><p>Un commerçant pose ses questions de gestion (« combien ai-je vendu hier ? », « que dois-je commander ? ») à l&#39;assistant IA qu&#39;il utilise déjà — Claude, ChatGPT, tout client du protocole MCP — et l&#39;assistant lit les réponses dans Vendora, en <strong>lecture seule</strong>, sur les magasins et les familles de données que le commerçant a choisis. Depuis le lot VEN-34, l&#39;assistant peut aussi <strong>préparer des propositions</strong>, sans effet tant qu&#39;un responsable ne les a pas validées ; le projet P-VEN-7 étend ces propositions à ce qu&#39;un gérant fait au back-office (RG-MCP-105 → 132).</p><h3 id="ce-que-ca-couvre" tabindex="-1">Ce que ça couvre <a class="header-anchor" href="#ce-que-ca-couvre" aria-label="Permalink to &quot;Ce que ça couvre&quot;">​</a></h3><ul><li><p>Les prérequis d&#39;accès du serveur (M0) : portées fines, restriction par magasin, clé « Assistant IA », journal des assistants, droit de formule, arrêts d&#39;urgence.</p></li><li><p>Le service <code>mcp/</code> (M1) : serveur MCP distant, sans état, client de l&#39;API publique.</p></li><li><p>La connexion « en un clic » (M3) : Vendora serveur d&#39;autorisation OAuth 2.1, écran de consentement au back-office, jetons, « Assistants connectés ».</p></li><li><p>L&#39;écriture encadrée par propositions : socle du lot VEN-34 (RG-MCP-83 → 104), puis registre de types, familles, écran de décision générique et réglages par famille (RG-MCP-105 → 132, jalon 1 du projet P-VEN-7) ; les types de chaque domaine sont livrés par les jalons 2 à 6 selon la matrice.</p></li></ul><h3 id="ce-que-ca-ne-couvre-pas" tabindex="-1">Ce que ça ne couvre PAS <a class="header-anchor" href="#ce-que-ca-ne-couvre-pas" aria-label="Permalink to &quot;Ce que ça ne couvre PAS&quot;">​</a></h3><ul><li>Toute <strong>écriture directe</strong> par un assistant : depuis le lot VEN-34, un assistant ne fait que <strong>proposer</strong> ; un humain valide (RG-MCP-83 → 132). Hors périmètre : l&#39;exécution automatique sous plafond (<code>EXECUTE_UNDER_CAP</code>) et les agents planifiés de Vendora (GaaS A1, A3 → A6).</li><li>Ce qui reste <strong>hors d&#39;atteinte même validé</strong> (RG-MCP-107) : fiscal, argent, sécurité et accès, abonnement, envois vers l&#39;extérieur, suppressions définitives, taux de TVA.</li><li>Les <strong>données nominatives des clients</strong> du commerce : ni portée proposée d&#39;office, ni outil, ni type, tant qu&#39;un avis juridique RGPD / INPDP n&#39;existe pas (RG-MCP-124). Les chiffres sans nom et le programme de fidélité relèvent du jalon 5.</li><li>La page « Assistant IA » du back-office et le tutoriel (M2), les cartes visuelles (U2), l&#39;annuaire des connecteurs (U6).</li><li>Les agents internes de Vendora (GaaS), qui ont leur propre plan.</li></ul><h2 id="_2-user-stories" tabindex="-1">2. User stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User stories&quot;">​</a></h2><ul><li>En tant que <strong>propriétaire</strong>, je veux connecter mon assistant à Vendora depuis mon téléphone sans copier de clé, afin d&#39;avoir mes chiffres en posant une question.</li><li>En tant que <strong>propriétaire</strong>, je veux choisir les magasins et les familles de données que l&#39;assistant peut lire, afin de ne partager que ce que je décide.</li><li>En tant que <strong>propriétaire</strong>, je veux voir les assistants connectés et retirer un accès d&#39;un geste, afin de garder la main si un téléphone est perdu.</li><li>En tant qu&#39;<strong>administrateur</strong>, je veux que l&#39;accès d&#39;un collègue désactivé tombe tout seul, afin de ne rien avoir à nettoyer.</li><li>En tant qu&#39;<strong>intégrateur</strong>, je veux une clé « Assistant IA » à mettre dans un en-tête, afin de brancher un script ou Claude Code sans navigateur.</li><li>En tant qu&#39;<strong>équipe Vendora</strong>, je veux couper l&#39;accès des assistants pour tous les commerces en cas d&#39;incident, sans toucher aux ventes ni aux autres intégrations.</li><li>En tant que <strong>propriétaire</strong>, je veux que mon assistant <strong>prépare</strong> ma commande fournisseur, un changement de prix ou le traitement d&#39;une alerte, afin de n&#39;avoir plus qu&#39;à valider (lot VEN-34).</li><li>En tant que <strong>gérant</strong>, je veux valider ou refuser une proposition sur la caisse avec mon PIN, en voyant pourquoi elle est faite et sur quels chiffres, afin de garder la décision sans aller au back-office.</li><li>En tant que <strong>propriétaire</strong>, je veux choisir, domaine par domaine, ce que mon assistant a le droit de préparer (catalogue, stock, achats…), afin d&#39;ouvrir l&#39;écriture à mon rythme (projet P-VEN-7).</li><li>En tant que <strong>gérant</strong>, je veux voir chaque proposition sous la même forme « avant → après », quel que soit son type, afin de décider vite sans apprendre un écran par action.</li><li>En tant qu&#39;<strong>équipe Vendora</strong>, je veux livrer un type de proposition éteint et ne l&#39;allumer qu&#39;après sa revue de sécurité, afin qu&#39;une fusion n&#39;ouvre jamais une écriture par surprise.</li></ul><h2 id="_3-regles-metier" tabindex="-1">3. Règles métier <a class="header-anchor" href="#_3-regles-metier" aria-label="Permalink to &quot;3. Règles métier&quot;">​</a></h2><h3 id="acces-des-assistants-m0" tabindex="-1">Accès des assistants (M0) <a class="header-anchor" href="#acces-des-assistants-m0" aria-label="Permalink to &quot;Accès des assistants (M0)&quot;">​</a></h3><ul><li><strong>RG-MCP-01</strong> — Un assistant est en <strong>lecture seule</strong>, toujours : toute écriture est refusée (403 <code>API_KEY_READ_ONLY</code>), quel que soit le moyen d&#39;authentification. <em>(Lot VEN-34 : seule exception, la création d&#39;une proposition avec la portée <code>proposals:write</code>, qui n&#39;écrit rien d&#39;autre — RG-MCP-83.)</em> <em>(Lot 4a de VEN-49, 19/11/2026 : une <strong>lecture</strong> d&#39;un assistant n&#39;écrit jamais non plus — <code>GET /catalog/tax-rates</code> sous une clé d&#39;API ou une connexion OAuth rend le référentiel tel quel, vide si le commerce n&#39;a aucun taux, sans l&#39;ensemencer ; spec 02 RG-CAT-92.)</em></li><li><strong>RG-MCP-02</strong> — L&#39;accès se règle par <strong>portées fines de lecture</strong> (<code>&lt;famille&gt;:read</code>). Le classement route → portée est <strong>fermé par défaut</strong> : une route non classée n&#39;est ouverte à aucune portée fine, et un test échoue si une route publique de lecture n&#39;est pas classée.</li><li><strong>RG-MCP-03</strong> — Un accès peut être <strong>restreint à des magasins</strong>. Double barrière : contrôle de la route et politique PostgreSQL <code>store_scope</code>. Autre magasin : 404 <code>STORE_NOT_ALLOWED</code> ; lecture du commerce entier : 403 <code>API_KEY_STORE_RESTRICTED</code>. <em>(Lot 4a de VEN-49, 19/11/2026 : la portée s&#39;étend aux <strong>produits propres à un magasin</strong> et aux tables qui suivent un produit — RG-MCP-143. Du 11/11 au 19/11, la politique ne visait que les tables à colonne <code>store_id</code> et un accès limité lisait les produits propres aux autres magasins.)</em></li><li><strong>RG-MCP-04</strong> — La clé « Assistant IA » (<code>kind = AGENT</code>) est préréglée sur <code>stores</code>, <code>catalog</code>, <code>sales</code>, <code>reports</code>, <code>inventory</code>, <code>purchases</code>, <code>devices</code> — <strong>jamais <code>customers:read</code> d&#39;office</strong> —, limitée à 120 requêtes par minute, et expire toujours (90 jours par défaut, 365 au plus). <em>(Lot VEN-34 : <code>proposals:write</code> n&#39;est jamais dans ce préréglage — RG-MCP-95.)</em></li><li><strong>RG-MCP-05</strong> — Le droit de formule <strong><code>MCP_ACCESS</code></strong> conditionne tout accès d&#39;assistant : sans lui, 402 <code>AGENT_ACCESS_NOT_IN_PLAN</code>, à la création comme à chaque requête.</li><li><strong>RG-MCP-06</strong> — <strong>Arrêt d&#39;urgence</strong> par commerce (propriétaire, back-office) et global (console Vendora, motif obligatoire) : effet dès la requête suivante, sans cache (401 <code>AGENT_ACCESS_DISABLED</code> / <code>AGENT_ACCESS_SUSPENDED</code>). Rien n&#39;est supprimé ; les clés « Logiciel tiers », la vente, la synchronisation et les Z ne sont jamais touchés.</li><li><strong>RG-MCP-07</strong> — Chaque lecture <strong>autorisée</strong> d&#39;un assistant est inscrite au <strong>journal des assistants</strong> (<code>agent_activity</code>, acteur <code>AGENT</code>), regroupée par accès, jour, lecture, magasin et période, avec un compteur. Jamais de secret, jamais le contenu lu. Le journal d&#39;audit reste celui des décisions humaines. <em>(Lot VEN-34 : la création d&#39;une proposition n&#39;est pas une lecture ; elle va au journal d&#39;audit, acteur <code>AGENT</code> — RG-MCP-98.)</em></li><li><strong>RG-MCP-08</strong> — Aucun secret (clé, jeton, code) n&#39;est stocké en clair, écrit dans un journal, ni accepté dans une adresse. Les secrets sont stockés <strong>hachés</strong> (SHA-256) et montrés une seule fois.</li><li><strong>RG-MCP-09</strong> — Un refus porte un <code>code</code> stable et un message en français <strong>relayable tel quel</strong> : il dit ce qui manque et où le régler.</li></ul><h3 id="serveur-mcp-m1" tabindex="-1">Serveur MCP (M1) <a class="header-anchor" href="#serveur-mcp-m1" aria-label="Permalink to &quot;Serveur MCP (M1)&quot;">​</a></h3><ul><li><strong>RG-MCP-10</strong> — Le service <code>mcp/</code> est un <strong>client de l&#39;API publique</strong> : pas de base de données, pas de secret, pas d&#39;accès privilégié, jamais le rôle <code>pos_platform</code>. Son client HTTP ne sait faire que des <code>GET</code>. <em>(Lot VEN-34 : plus un <code>POST</code> vers la seule route <code>/api/v1/agent-proposals</code>, liste blanche testée — RG-MCP-100.)</em></li><li><strong>RG-MCP-11</strong> — Il est <strong>sans état</strong> : chaque requête se suffit (révision 2026-07-28 du protocole, compatibilité 2025-11-25 et antérieures sans session).</li><li><strong>RG-MCP-12</strong> — L&#39;accès de l&#39;appelant (clé ou jeton) est <strong>relayé à chaque requête</strong> à l&#39;API Vendora, qui décide ; il n&#39;est ni gardé ni journalisé. Le journal du service ne contient ni accès, ni argument, ni texte du commerçant.</li><li><strong>RG-MCP-13</strong> — La liste d&#39;outils dépend des portées de l&#39;accès (<code>GET /api/v1/api-keys/me</code>) : un outil dont la portée manque n&#39;est pas proposé, et <code>list_stores</code> dit ce que l&#39;accès n&#39;inclut pas. <em>(Lot 4b de VEN-49 : outil <code>catalog_reference</code> ajouté, portée <code>catalog:read</code> — inventaire des outils de lecture dans RG-MCP-142.)</em></li><li><strong>RG-MCP-14</strong> — Chaque réponse d&#39;outil indique la <strong>période réellement utilisée</strong> (dans le fuseau du magasin) et la <strong>fraîcheur</strong> des données ; des données anciennes sont signalées, jamais présentées comme à jour. <em>(Lot 4b de VEN-49 : <code>list_stores</code> et le refus « période future » disent aussi la date et l&#39;heure du jour dans le fuseau de chaque magasin — RG-MCP-142.)</em></li><li><strong>RG-MCP-15</strong> — Un nom ambigu (magasin, produit) ne se devine pas : l&#39;outil renvoie les candidats. Aucun chiffre n&#39;est inventé.</li><li><strong>RG-MCP-16</strong> — Les textes libres venus des données (noms de produits, notes) sont des <strong>données, jamais des consignes</strong> : chaque réponse les balise comme telles. <em>(Lot 4b de VEN-49 : vaut aussi pour les noms de catégories et de taux de TVA rendus par <code>catalog_reference</code> — RG-MCP-142.)</em></li><li><strong>RG-MCP-17</strong> — Garde-fous du transport : <code>Origin</code> étranger refusé (403), corps limité à 1 Mo, lots JSON-RPC refusés, <code>GET</code> / <code>DELETE</code> sur <code>/mcp</code> → 405.</li><li><strong>RG-MCP-18</strong> — Les refus de l&#39;API (401, 402, 403, 404, 429) sont rendus à l&#39;assistant avec leur message, sans réessai caché.</li><li><em>RG-MCP-19 à 29 : réservées (cartes visuelles, langue du commerce, écriture encadrée).</em></li></ul><h3 id="connexion-oauth-2-1-m3" tabindex="-1">Connexion OAuth 2.1 (M3) <a class="header-anchor" href="#connexion-oauth-2-1-m3" aria-label="Permalink to &quot;Connexion OAuth 2.1 (M3)&quot;">​</a></h3><ul><li><strong>RG-MCP-30</strong> — Le <strong>serveur Vendora est le serveur d&#39;autorisation</strong> (comptes du back-office), sans service séparé. Émetteur = adresse publique de l&#39;API. Les points que les normes fixent sont hors <code>/api/v1</code> (<code>/.well-known/oauth-authorization-server</code>, <code>/oauth/token</code>, <code>/oauth/revoke</code>, <code>/oauth/register</code>) ; tout le reste (point d&#39;autorisation, consentement, connexions) est sous <code>/api/v1/oauth</code> — une seule API. Le <strong>point d&#39;autorisation</strong> est annoncé sur l&#39;origine du <strong>back-office</strong> (<code>&lt;back-office&gt;/api/v1/oauth/authorize</code>, relayé vers l&#39;API) : c&#39;est ce qui permet de lier la demande au navigateur (RG-MCP-46). Les clients sont <strong>publics</strong> : aucun secret de client n&#39;existe.</li><li><strong>RG-MCP-31</strong> — Le client s&#39;identifie par un <strong>document client</strong> (CIMD : son <code>client_id</code> est une adresse <code>https</code> que le serveur lit) ou, en repli, par <strong>enregistrement dynamique</strong> (DCR). La lecture du document est protégée contre les requêtes vers l&#39;intérieur (SSRF) : <code>https</code> et port 443 seulement, adresse <strong>publique</strong> vérifiée après résolution DNS (<strong>toutes</strong> les adresses rendues doivent être publiques) et connexion faite à l&#39;adresse vérifiée, aucune redirection suivie, <strong>5 secondes pour toute l&#39;opération</strong> (résolution DNS, connexion, poignée de main TLS et lecture comprises : à l&#39;échéance la connexion est fermée), 64 Ko au plus, <strong>8 lectures en parallèle</strong> pour tout le serveur (refus immédiat au-delà, sans file d&#39;attente) ; le document doit se désigner lui-même ; cache de 5 minutes à 24 heures, écrit seulement <strong>une fois la demande entièrement validée</strong>.</li><li><strong>RG-MCP-32</strong> — Une adresse de redirection n&#39;est acceptée que si elle est <strong>exactement</strong> l&#39;une de celles que le client a déclarées ; seule tolérance : le port d&#39;une adresse en boucle locale (<code>localhost</code>, <code>127.0.0.1</code>). Client ou redirection non reconnus : écran d&#39;erreur de Vendora, <strong>jamais de redirection</strong> vers l&#39;adresse présentée. Pour un client <strong>non vérifié</strong> (RG-MCP-36), <strong>aucune erreur</strong> ne repart vers sa redirection, même validée : toute demande incorrecte (type de réponse, PKCE, ressource, portée) finit sur l&#39;écran d&#39;erreur de Vendora (pas de redirection ouverte, RFC 9700 § 4.11.2). Seul un client vérifié reçoit l&#39;erreur à sa redirection. Un paramètre présent deux fois est refusé.</li><li><strong>RG-MCP-33</strong> — Flux : code d&#39;autorisation avec <strong>PKCE S256 obligatoire</strong> (<code>plain</code> et méthode absente refusés), paramètre <code>resource</code> égal à l&#39;adresse d&#39;un serveur MCP connu, <code>state</code> renvoyé à l&#39;identique, <code>iss</code> dans la réponse. Le code vit <strong>60 secondes</strong>, sert <strong>une fois</strong>, et n&#39;est valable que pour le client, la redirection et la ressource de la demande.</li><li><strong>RG-MCP-34</strong> — Le consentement se donne <strong>dans le back-office</strong> (<code>/connecter-assistant?demande=…</code>), après la connexion habituelle. L&#39;adresse ne porte qu&#39;un <strong>identifiant opaque</strong> de la demande (stocké haché, 10 minutes) : jamais un code ni un jeton.</li><li><strong>RG-MCP-35</strong> — Peuvent autoriser : les rôles qui peuvent créer une clé « Assistant IA » (<strong>propriétaire, administrateur</strong>). Les magasins proposés sont ceux que l&#39;utilisateur administre ; tout autre choix est refusé. Une session de <strong>mise en service déléguée</strong> à l&#39;équipe Vendora (spec 17 RG-PLAT-34) ne peut ni voir une demande, ni autoriser, ni lister, ni retirer une connexion : <code>/api/v1/oauth/**</code> y est toujours interdit, comme les clés d&#39;API.</li><li><strong>RG-MCP-36</strong> — L&#39;écran dit <strong>qui demande</strong> (nom et domaine tirés du document client), <strong>où l&#39;on sera renvoyé</strong>, que l&#39;accès est en <strong>lecture seule</strong>, et que <strong>les données choisies sont envoyées à l&#39;assistant choisi</strong>. Un client n&#39;est « Vérifié » que si son <strong>identifiant exact</strong> (l&#39;adresse de son document client) figure dans la liste de confiance du serveur ; tout autre client — et tout client enregistré lui-même — est « Non vérifié ». Le nom affiché est nettoyé et borné à 60 caractères ; un client non vérifié qui se présente sous le nom d&#39;un assistant connu ou de Vendora (Claude, ChatGPT, OpenAI, Anthropic, Vendora… sans tenir compte de la casse, des accents ni des caractères ressemblants) est affiché sous le <strong>domaine de sa redirection</strong> à la place. <em>(Lot VEN-34 : si la famille « Propositions » est demandée, l&#39;écran dit aussi que l&#39;assistant pourra préparer des propositions, sans effet avant validation — RG-MCP-95.)</em></li><li><strong>RG-MCP-37</strong> — L&#39;utilisateur choisit les <strong>magasins</strong> (tous, ou une liste) et les <strong>familles</strong> : ventes et rapports, stock, achats, appareils ; anti-fraude seulement si son rôle y a droit, <strong>jamais cochée d&#39;office</strong>. Les données clients ne sont pas proposées. Au moins un magasin et une famille. <em>(Lot VEN-34 : famille « Propositions » — <code>proposals:write</code> — en bloc distinct, jamais cochée d&#39;office, et qui ne compte pas comme la famille de lecture exigée — RG-MCP-95.)</em> <em>(Cadrage VEN-42 : famille de lecture « Réglages » ajoutée (décision du 16/11/2026), et chiffres de clients sans nom au jalon 5 — RG-MCP-112, 124 ; les données <strong>nominatives</strong> des clients ne sont toujours pas proposées. Les familles de propositions sont distinctes de ces familles de lecture — RG-MCP-109.)</em></li><li><strong>RG-MCP-38</strong> — <strong>Autoriser</strong> ou <strong>Refuser</strong> : la demande ne reçoit qu&#39;une réponse (ensuite 410) ; un refus renvoie <code>access_denied</code> au client (pour un client non vérifié, seulement parce que l&#39;utilisateur connecté l&#39;a décidé lui-même sur l&#39;écran). Arrêt d&#39;urgence actif ou formule sans <code>MCP_ACCESS</code> : l&#39;autorisation est impossible et l&#39;écran dit pourquoi. Écran en français, anglais et arabe (droite à gauche), clair et sombre, téléphone et bureau.</li><li><strong>RG-MCP-39</strong> — Les jetons sont <strong>opaques</strong>, stockés hachés, à préfixe reconnaissable : accès <code>vd_oat_…</code> (1 heure), renouvellement <code>vd_ort_…</code> (90 jours), code <code>vd_oac_…</code>. Une connexion dure 365 jours au plus.</li><li><strong>RG-MCP-40</strong> — Le jeton de renouvellement est <strong>tournant</strong> : chaque usage en émet un nouveau. Un jeton de renouvellement <strong>rejoué</strong>, ou un code présenté deux fois, <strong>révoque toute la connexion</strong>. L&#39;échange du code est <strong>atomique</strong> : la connexion et ses jetons naissent dans la même transaction que le marquage du code, si bien qu&#39;un second échange, même simultané, trouve la connexion et la révoque. Code et jetons ne voyagent que dans le <strong>corps</strong> des requêtes : tout paramètre dans l&#39;adresse du point de jeton ou de révocation est refusé. Seule exception au rejeu : la fenêtre de grâce de 30 secondes (RG-MCP-77).</li><li><strong>RG-MCP-41</strong> — Un jeton d&#39;accès suit <strong>le chemin de code de la clé « Assistant IA »</strong> : RG-MCP-01 à 09 s&#39;appliquent telles quelles (lecture seule, portées, magasins, journal, arrêts d&#39;urgence, <code>MCP_ACCESS</code>, 120 requêtes par minute). <code>GET /api/v1/api-keys/me</code> répond avec <code>kind: &quot;OAUTH&quot;</code>.</li><li><strong>RG-MCP-42</strong> — L&#39;accès est <strong>recalculé à chaque requête</strong> : utilisateur actif, toujours propriétaire ou administrateur, magasins accordés ∩ magasins qu&#39;il administre encore. Sinon 401 dès la requête suivante, et le renouvellement est refusé (<code>invalid_grant</code>) tant qu&#39;il n&#39;administre plus aucun des magasins accordés.</li><li><strong>RG-MCP-43</strong> — <strong>Retirer l&#39;accès</strong> (back-office, « Assistants connectés » : assistant, par qui, magasins, familles, connecté le, dernière utilisation) ou révocation par le client (RFC 7009) : jetons d&#39;accès et de renouvellement refusés dès la requête suivante. Sont inscrits au journal d&#39;audit (<code>OAUTH_CONNECTION</code>) : l&#39;autorisation (<code>AUTHORIZED</code>), le <strong>refus</strong> du consentement (<code>DENIED</code>) et <strong>tout</strong> retrait (<code>REVOKED</code>, avec son motif : <code>USER</code> au back-office, <code>CLIENT</code> par l&#39;assistant, <code>REPLAY</code> après un rejeu).</li><li><strong>RG-MCP-44</strong> — Le serveur MCP annonce la connexion : sans accès, <strong>401 sur toute méthode</strong> avec <code>WWW-Authenticate: Bearer resource_metadata=&quot;…&quot;</code> ; document de ressource protégée (RFC 9728) à la racine et sous le chemin de la ressource, dont <code>resource</code> est l&#39;adresse publique <strong>exacte</strong> du serveur MCP. Jeton expiré ou retiré : 401 <code>invalid_token</code> (le client renouvelle). Arrêt d&#39;urgence : 403, pour ne pas relancer une connexion en boucle.</li><li><strong>RG-MCP-45</strong> — Les points OAuth répondent en moins de 10 secondes (aucun appel long ; lecture du document client bornée) et sont limités <strong>par adresse appelante et globalement</strong>, par minute : autorisation 120 / 600, jeton et révocation 300 / 3 000, enregistrement 30 / 60. Leurs réponses ne sont jamais mises en cache. Métadonnées, jeton, révocation et enregistrement acceptent les appels d&#39;une autre origine (CORS, sans identifiants) ; le point d&#39;autorisation et le consentement, non. Autorisation et enregistrement sont en plus limités <strong>par réseau</strong> (RG-MCP-74), qui remplace pour eux la limite par adresse.</li><li><strong>RG-MCP-46</strong> — <strong>Liaison au navigateur</strong> : le point d&#39;autorisation pose un cookie (<code>HttpOnly</code>, <code>SameSite=Lax</code>, <code>Secure</code> en https, 10 minutes, limité à <code>/api/v1/oauth</code>) dont seule l&#39;empreinte est gardée avec la demande. Lire la demande, l&#39;autoriser ou la refuser exige ce cookie : un lien de consentement ouvert dans un <strong>autre navigateur</strong> est refusé (403 <code>OAUTH_REQUEST_OTHER_BROWSER</code>) et l&#39;écran invite à relancer la connexion depuis l&#39;assistant.</li><li><strong>RG-MCP-47</strong> — <strong>Stockage borné</strong> : ce que des appelants anonymes font enregistrer est plafonné — 2 000 demandes en attente, 3 000 clients enregistrés, 2 000 documents en cache ; enregistrement de 4 Ko, 5 redirections (10 dans un document client) de 500 caractères, <code>state</code> de 500 caractères. Au-delà : refus, rien n&#39;est écrit. Ménage continu : demandes sans accord 10 minutes après leur fin, clients enregistrés jamais utilisés après une heure (un jour s&#39;ils ont servi sans jamais aboutir à une connexion), documents en cache un jour après leur échéance. Depuis le lot « Plafonds OAuth », un plafond global atteint <strong>évince</strong> d&#39;abord (RG-MCP-75) au lieu de refuser.</li><li><strong>RG-MCP-48</strong> — <strong>Interrupteur</strong> <code>pos.oauth.enabled</code> (<code>POS_OAUTH_ENABLED</code>), <strong>faux par défaut</strong> : éteint, tous les points OAuth (<code>/oauth/**</code>, <code>/.well-known/oauth-authorization-server</code>, <code>/api/v1/oauth/**</code>) répondent 404 et seules les clés servent. Allumé, le serveur <strong>refuse de démarrer</strong> hors développement et test si l&#39;émetteur ou les ressources ne sont pas posés explicitement, en https.</li><li><strong>RG-MCP-49</strong> — La page <strong>Réglages › Assistant IA</strong> (<code>/assistant-ia</code>) est réservée au <strong>propriétaire et aux administrateurs</strong> : un responsable de magasin ne la voit pas dans le menu et l&#39;adresse directe lui est refusée. Sous délégation Vendora elle s&#39;affiche en lecture seule (aucune connexion, aucun test, aucun arrêt).</li><li><strong>RG-MCP-50</strong> — L&#39;adresse du connecteur affichée vient <strong>du serveur</strong> (première ressource de <code>POS_OAUTH_RESOURCES</code>), jamais d&#39;une constante du back-office ni d&#39;une adresse de repli : sans configuration, aucune adresse n&#39;est montrée. OAuth éteint, les blocs « Connecter Claude / ChatGPT » sont remplacés par un message et seules les clés pour intégrateurs restent. « Connecter ChatGPT » est marqué <strong>Bêta</strong> tant qu&#39;un essai réel n&#39;a pas été fait.</li><li><strong>RG-MCP-51</strong> — <strong>Tester la connexion</strong> répond par <strong>un seul message en clair</strong> : tout va bien · la formule n&#39;inclut pas l&#39;assistant · assistants arrêtés (arrêt d&#39;urgence, ou suspension Vendora qui prime) · le service ne répond pas. Le test est fait par le serveur Vendora (OAuth allumé : le service MCP doit annoncer l&#39;adresse du connecteur dans son document de ressource protégée ; éteint : sa santé suffit), en 8 secondes au plus, sans suivre de redirection, sans aucune donnée ni identifiant du commerce, corps lu jusqu&#39;à 64 Ko. Un test toutes les 10 secondes par commerce (429 <code>ASSISTANT_TEST_TOO_SOON</code> avec <code>Retry-After</code>). La mention d&#39;une mise en veille n&#39;apparaît que sur un environnement d&#39;essai (<code>POS_ASSISTANT_TRIAL_ENVIRONMENT</code>).</li><li><strong>RG-MCP-52</strong> — L&#39;<strong>activité</strong> montre les 50 dernières lectures en phrases (« a lu les ventes du 10/11 de Le Petit Bistrot »), avec l&#39;assistant ou la clé d&#39;origine, filtrable par assistant (par identifiant, les homonymes sont distingués) ; jamais de nom de route ni d&#39;identifiant technique ; dates dans la langue de l&#39;utilisateur.</li><li><strong>RG-MCP-53</strong> — Les <strong>clés pour intégrateurs</strong> sont repliées par défaut ; la famille Clients (<code>customers:read</code>) est décochée ; le secret n&#39;est affiché qu&#39;une fois, avec la commande <code>claude mcp add</code> complète quand l&#39;adresse du service est connue.</li><li><strong>RG-MCP-54</strong> — <strong>Retirer l&#39;accès</strong> d&#39;un assistant et l&#39;<strong>arrêt d&#39;urgence</strong> (propriétaire seul) demandent une confirmation, sont tracés dans l&#39;audit, et la page se met à jour sans rechargement.</li></ul><h3 id="demonstration-publique-demo-mcp-lot-u5" tabindex="-1">Démonstration publique <code>/demo/mcp</code> (lot U5) <a class="header-anchor" href="#demonstration-publique-demo-mcp-lot-u5" aria-label="Permalink to &quot;Démonstration publique `/demo/mcp` (lot U5)&quot;">​</a></h3><ul><li><strong>RG-MCP-55</strong> — Le chemin <code>/demo/mcp</code> est <strong>sans authentification</strong> et ne sert qu&#39;un commerce fictif dédié (« Le Petit Bistrot (démo) ») : le serveur MCP appelle l&#39;API avec une clé « Assistant IA » lue dans <code>VENDORA_DEMO_API_KEY</code> ; la clé ou le jeton fourni par l&#39;appelant est ignoré, jamais relayé. Sans cette variable, ou avec <code>VENDORA_MCP_DEMO_ENABLED=false</code>, le chemin répond 404 et <code>/mcp</code> est inchangé. La démo n&#39;annonce ni ressource protégée ni connexion OAuth.</li><li><strong>RG-MCP-56</strong> — Mêmes outils et mêmes réponses que <code>/mcp</code>, en lecture seule, avec la mention « données de démonstration » dans chaque résultat et dans les consignes ; <code>fraud_alerts</code> n&#39;est ni listé ni appelable ; aucun lien vers le back-office ; aucun texte ne renvoie le prospect vers le propriétaire, les réglages ou un écran de connexion. <em>(Lot VEN-34 : aucun outil de proposition, aucun bouton « Préparer le bon de commande » — RG-MCP-100, 102.)</em></li><li><strong>RG-MCP-57</strong> — <strong>Débit borné en mémoire</strong> : 30 requêtes par minute par réseau (IPv4 par /24, IPv6 par /48), plafond global de 240 par minute, 429 avec <code>Retry-After</code>. L&#39;adresse du visiteur est l&#39;entrée de <code>X-Forwarded-For</code> située <code>VENDORA_MCP_DEMO_TRUSTED_PROXIES</code> rangs avant la fin (jamais la première, forgeable), lue par un parseur strict sans résolution de nom ; à défaut, l&#39;adresse de la connexion.</li><li><strong>RG-MCP-58</strong> — La clé de démonstration n&#39;apparaît dans <strong>aucun</strong> journal ni <strong>aucune</strong> réponse (corps, en-têtes, erreurs de l&#39;API relayées) ; un refus de l&#39;API devient « momentanément indisponible » (503) et le journal n&#39;en garde que le statut et le code.</li></ul><h3 id="bibliotheque-de-questions-par-metier-lot-u3" tabindex="-1">Bibliothèque de questions par métier (lot U3) <a class="header-anchor" href="#bibliotheque-de-questions-par-metier-lot-u3" aria-label="Permalink to &quot;Bibliothèque de questions par métier (lot U3)&quot;">​</a></h3><ul><li><strong>RG-MCP-59</strong> — Les questions proposées au commerçant ont <strong>une seule source</strong> : <code>mcp/src/main/resources/questions/library.json</code> (identifiant, métiers, moment — matin, fin de service, fin de semaine, fin de mois —, texte FR / EN / AR, outil attendu). Le jeu de référence, le fichier du back-office et les pages d&#39;aide « Que demander à votre assistant ? » en sont <strong>générés</strong> par <code>mcp/tools/export-questions.py</code> ; la suite <code>mcp</code> échoue si un fichier généré a dérivé ou est orphelin. Aucun de ces fichiers ne se modifie à la main.</li><li><strong>RG-MCP-60</strong> — Toute question de la bibliothèque est <strong>vérifiée</strong> par le jeu de référence sur des données déterministes (bon outil, bons chiffres, mentions interdites) avant d&#39;être proposée ; une question qui ne passe pas est corrigée ou retirée, jamais publiée telle quelle.</li><li><strong>RG-MCP-61</strong> — Les cinq prompts gardent leur nom ; titre, description et texte suivent la langue du commerce (FR / EN / AR, français à défaut). Paramètres facultatifs <code>store</code> (nettoyé, 60 caractères) et <code>period</code> (liste fermée de périodes en mots) ; une valeur hors liste est ignorée, jamais recopiée dans le texte. La langue est mise en cache par accès (5 minutes) ; <code>/demo/mcp</code> n&#39;appelle jamais l&#39;API pour cela.</li><li><strong>RG-MCP-62</strong> — Le bloc « Pour bien commencer » de Réglages › Assistant IA montre les questions du <strong>métier du magasin choisi</strong> (tous les métiers du commerce pour « Tous les magasins », section « Plusieurs magasins » dès deux magasins), classées par moment, copiables d&#39;un geste ; un profil sans liste ou un fichier illisible affiche une liste générale avec un bandeau qui le dit.</li></ul><h3 id="cartes-visuelles-dans-la-conversation-lot-u2-extension-mcp-apps" tabindex="-1">Cartes visuelles dans la conversation (lot U2, extension MCP Apps) <a class="header-anchor" href="#cartes-visuelles-dans-la-conversation-lot-u2-extension-mcp-apps" aria-label="Permalink to &quot;Cartes visuelles dans la conversation (lot U2, extension MCP Apps)&quot;">​</a></h3><ul><li><strong>RG-MCP-63</strong> — Trois outils désignent une carte : <code>sales_summary</code>, <code>reorder_suggestions</code> et <code>compare_stores</code> portent <code>_meta.ui.resourceUri</code> (et la clé plate dépréciée) vers <code>ui://vendora/&lt;carte&gt;.html</code>. Un assistant qui n&#39;affiche pas les cartes reçoit exactement la même réponse qu&#39;avant.</li><li><strong>RG-MCP-64</strong> — <code>resources/list</code> et <code>resources/read</code> ne demandent aucune clé et ne portent <strong>aucune donnée d&#39;un commerce</strong> ; seule exception, depuis le 12/11 : avec une clé ou un jeton, les <strong>titres et descriptions</strong> de <code>resources/list</code> sont dans la langue du commerce (RG-MCP-69, lecture de <code>GET /stores</code> mise en cache par accès ; sans clé et sur <code>/demo/mcp</code> : français, aucun appel à l&#39;API ; réponse jamais mise en cache publique dans ce cas) (avec OAuth actif, une requête sans en-tête reste refusée 401) ; type <code>text/html;profile=mcp-app</code> ; adresse inconnue : -32602. La lecture est servie depuis la mémoire, compressée si le client l&#39;accepte, mise en cache publique, et limitée <strong>par réseau</strong> (3 000 par minute par défaut, sans plafond global : les assistants lisent les cartes depuis quelques plages d&#39;adresses pour tous leurs utilisateurs).</li><li><strong>RG-MCP-65</strong> — Chaque carte est un fichier HTML <strong>autonome</strong> (aucun chargement externe, aucun appel réseau), versionné dans le dépôt. Trois gardes : contrôle des adresses et des API réseau sur le JavaScript livré, banc de rendu sous la politique de sécurité par défaut de MCP Apps (toute violation est un échec), fichier témoin SHA-256 qui fait échouer la suite si un HTML ne correspond plus à ses sources.</li><li><strong>RG-MCP-66</strong> — Le texte et le contenu structuré restent <strong>la référence</strong> et ne changent pas (instantanés comparés octet pour octet). La carte reçoit ses textes déjà formatés dans <code>_meta[&quot;vendora/card&quot;]</code>, que le modèle ne lit pas ; elle ne recalcule aucun chiffre.</li><li><strong>RG-MCP-67</strong> — Une carte n&#39;a <strong>aucun bouton qui modifie</strong> quoi que ce soit ; le seul bouton est « Ouvrir dans Vendora » (lien <code>https</code> fourni par le serveur, absent en démonstration). Un texte venu du commerce n&#39;est jamais inséré comme HTML. <em>(Lot VEN-34 : la carte « Quoi commander » ajoute « Préparer le bon de commande », qui ne crée qu&#39;une proposition — RG-MCP-102.)</em></li><li><strong>RG-MCP-68</strong> — État vide et avertissements : la phrase du serveur, telle quelle. Thème (clair / sombre) et langue (FR / EN / AR, sens droite-gauche) suivent l&#39;assistant. Sur <code>/demo/mcp</code>, la carte affiche un bandeau « Données de démonstration » (RG-MCP-56).</li></ul><h3 id="langue-du-commerce-et-conformite-aux-annuaires-lot-u6a" tabindex="-1">Langue du commerce et conformité aux annuaires (lot U6a) <a class="header-anchor" href="#langue-du-commerce-et-conformite-aux-annuaires-lot-u6a" aria-label="Permalink to &quot;Langue du commerce et conformité aux annuaires (lot U6a)&quot;">​</a></h3><ul><li><strong>RG-MCP-69</strong> — <code>GET /api/v1/stores</code> (et <code>/stores/{id}</code>) expose <code>locale</code> (<code>fr</code>, <code>en</code>, <code>ar</code>) pour chaque magasin ; le champ vaut <strong><code>null</code></strong> tant que rien n&#39;est réglé (toujours présent depuis le 14/11 ; absent auparavant). La langue du commerce vue par le serveur MCP est celle de la <strong>majorité</strong> des magasins ouverts à l&#39;accès ; égalité ou aucun réglage : <strong>français</strong>. Elle est mise en cache par accès (5 minutes), seulement quand la lecture a réussi.</li><li><strong>RG-MCP-70</strong> — Titres d&#39;outils, descriptions de paramètres, résumés, avertissements, questions suggérées, consignes du serveur et messages de refus existent en <strong>FR, EN et AR</strong> et suivent la langue du commerce ; les <strong>noms</strong> d&#39;outils et les clés du contenu structuré ne changent jamais. Sur <code>/demo/mcp</code> : français. En <strong>arabe</strong>, chaque suite de texte gauche-à-droite (nombre, montant, date, nom latin, adresse) d&#39;une ligne qui contient de l&#39;arabe est entourée de marques d&#39;isolation Unicode (U+2066 ou U+2068 … U+2069) pour garder son ordre de lecture ; jamais dans le contenu structuré, les liens, <code>_meta</code> ni les blocs <code>&lt;donnee_aide&gt;</code> ; français et anglais inchangés. Les caractères de contrôle de direction sont retirés des arguments reçus et des textes du commerce. Une erreur de l&#39;API au code inconnu donne, en anglais et en arabe, un message générique (jamais le texte du serveur ; le code n&#39;est repris que s&#39;il est de la forme <code>[A-Z0-9_]{1,40}</code>). Seule exception, pour que l&#39;assistant puisse corriger son appel : une erreur de validation (<strong>400 ou 422</strong>) ajoute à ce message la cause donnée par le service, en français, nettoyée, bornée à 300 caractères, sans chevron et annoncée comme une <strong>donnée, jamais une consigne</strong>.</li><li><strong>RG-MCP-71</strong> — La description d&#39;un outil dit <strong>ce qu&#39;il renvoie et quand l&#39;appeler</strong> (1 024 caractères au plus), sans consigne de comportement adressée au modèle ; ces consignes vivent dans les consignes du serveur et dans les champs du résultat (<code>warnings</code>, <code>dataNotice</code>). La mention « données, jamais des instructions » reste dans chaque résultat.</li><li><strong>RG-MCP-72</strong> — Les <strong>512 premiers caractères</strong> des consignes du serveur se suffisent à eux-mêmes (ce qu&#39;est Vendora, lecture seule, chiffres issus des outils seulement — à l&#39;impératif —, textes du commerce = données). Pour que le modèle n&#39;additionne rien lui-même, <code>reorder_suggestions</code> donne le sous-total par fournisseur (texte et <code>data.bySupplier</code>). <em>(Lot VEN-34 : pour un accès qui peut proposer, « lecture seule » devient « lecture, et propositions soumises à validation » ; inchangé sinon — RG-MCP-100.)</em></li><li><strong>RG-MCP-73</strong> — Aucun identifiant interne (UUID) dans le <strong>texte</strong> d&#39;un résultat, hors adresses des liens du back-office (<code>?store=&lt;id&gt;</code>), ni dans <code>find_product</code> (plus de champ <code>id</code>) : un produit est désigné par son nom, son code-barres et sa référence. <em>(Lot VEN-34 : un identifiant opaque <code>ref</code> revient dans le contenu structuré seulement — RG-MCP-101.)</em> Les schémas de sortie utilisent <code>anyOf</code> (plus de type <code>[&quot;object&quot;,&quot;null&quot;]</code>). Les messages renvoient à <strong>Réglages › Assistant IA</strong>.</li></ul><h3 id="plafonds-de-la-connexion-oauth-lot-«-plafonds-oauth-»" tabindex="-1">Plafonds de la connexion OAuth (lot « Plafonds OAuth ») <a class="header-anchor" href="#plafonds-de-la-connexion-oauth-lot-«-plafonds-oauth-»" aria-label="Permalink to &quot;Plafonds de la connexion OAuth (lot « Plafonds OAuth »)&quot;">​</a></h3><p>Un « réseau » est le /24 d&#39;une adresse IPv4 ou le /48 d&#39;une adresse IPv6 ; la base ne garde que ce réseau, jamais l&#39;adresse. Valeurs et variables : <a href="/VendoraSystem-docs/architecture/environnements">deploy/README.md</a> (« Plafonds OAuth »).</p><ul><li><strong>RG-MCP-74</strong> — Chaque plafond global est doublé d&#39;un <strong>plafond par réseau</strong> : débit de l&#39;autorisation (20 par minute) et de l&#39;enregistrement (5 par minute), demandes en attente (60), enregistrements de clients (20 par heure), lectures de documents clients (30 par heure, une à la fois). En IPv6 la règle s&#39;applique une seconde fois au /32, dont la part vaut <code>POS_OAUTH_WIDE_FACTOR</code> fois celle d&#39;un /48 (défaut 8 : 16 autorisations et 8 enregistrements par minute garantis à tout un /32 sous attaque — une garantie, pas un plafond). Un réseau qui atteint son plafond est refusé <strong>seul</strong> (<code>temporarily_unavailable</code>, <code>Retry-After</code>) ; le plafond global n&#39;est plus qu&#39;un dernier filet, et ne refuse que les réseaux déjà actifs dans la minute. Un commerce garde au plus <strong>20 assistants connectés</strong> (409 <code>OAUTH_TOO_MANY_CONNECTIONS</code> à l&#39;accord ; les connexions existantes ne sont jamais coupées). L&#39;adresse de l&#39;appelant n&#39;est lue dans <code>X-Forwarded-For</code> que derrière des relais de confiance déclarés.</li><li><strong>RG-MCP-75</strong> — Plafond global atteint : la plus ancienne entrée <strong>non confirmée</strong> est évincée avant tout refus. Une demande est confirmée quand un utilisateur connecté <strong>qui pourrait l&#39;accorder</strong> l&#39;a affichée (3 par commerce au plus, la moitié du plafond global en tout ; au-delà les confirmations des commerces non payants au sens de RG-MCP-78 tombent d&#39;abord). Clients enregistrés : même règle, un client protégé par une connexion vivante n&#39;est évincé qu&#39;au-delà de la moitié du plafond, et ses connexions continuent de fonctionner. Au-delà de cette moitié, c&#39;est le client <strong>le plus récent dont aucune connexion vivante n&#39;est d&#39;un commerce payant</strong> (RG-MCP-78) qui part ; le client d&#39;un commerce payant n&#39;est jamais évincé et ne compte pas dans le plafond (RG-MCP-79). Une demande accordée ne protège son client que tant que son code n&#39;est ni échangé ni échu (60 secondes). Les clients de la liste de confiance sont hors quota ; si leur document est injoignable (panne, 408, 429), la copie du cache est servie 7 jours au plus ; un refus de l&#39;éditeur la supprime.</li><li><strong>RG-MCP-76</strong> — Un jeton d&#39;accès n&#39;est accepté que pour la <strong>ressource</strong> de son émission : le serveur MCP envoie <code>X-Vendora-Resource</code> (son adresse publique) avec tout jeton <code>vd_oat_</code> ; valeur différente : 401. En-tête absent : toléré tant que <code>POS_OAUTH_REQUIRE_RESOURCE_HEADER</code> est faux (défaut, le temps que le serveur MCP soit déployé partout), refusé ensuite.</li><li><strong>RG-MCP-77</strong> — <strong>Fenêtre de grâce</strong> : un jeton de renouvellement déjà échangé, rejoué par le <strong>même client</strong> dans les 30 secondes, rend la <strong>même paire</strong> tant qu&#39;elle n&#39;a pas servi (réponse perdue en route) ; au-delà, ou si la paire a servi : connexion révoquée et tracée (<code>REPLAY</code>), comme RG-MCP-40.</li><li><strong>RG-MCP-78</strong> — Pour l&#39;éviction, un commerce est <strong>« payant »</strong> s&#39;il a <strong>aujourd&#39;hui</strong> le droit Assistant IA (formule, option active ou dérogation) et n&#39;est pas en essai ; un essai descendu en Gratuit puis souscrit est payant. Les arrêts d&#39;urgence (commerce ou Vendora) n&#39;y changent rien. Un commerce suspendu ou résilié garde son état (la suspension ne coupe rien). Cette définition remplace « commerce en essai » dans les deux classements de RG-MCP-75 (confirmations, clients protégés).</li><li><strong>RG-MCP-79</strong> — Un client enregistré dont une connexion vivante appartient à un commerce payant est <strong>hors du plafond</strong> des clients enregistrés : il ne compte pas et n&#39;est jamais évincé (borne naturelle : 20 connexions par commerce). Le plafond, la moitié protégée et l&#39;éviction ne portent que sur les autres ; un client évincé garde ses connexions, qui continuent de se renouveler.</li><li><strong>RG-MCP-80</strong> — Quand la table d&#39;un compteur anonyme est pleine, un appelant nouveau n&#39;a pas de compteur à lui : il est compté, <strong>avant tout travail</strong>, dans une enveloppe globale du point d&#39;entrée, jamais dans la case d&#39;un autre réseau — autorisation 600 par minute, enregistrement 60, révocation 3 000, jeton 3 000 (« débordement »).</li><li><strong>RG-MCP-81</strong> — Point de jeton : trois bornes comptées <strong>avant toute lecture en base</strong>, dans cet ordre — la limite par adresse (300 par minute, réussites comprises), l&#39;enveloppe « débordement » pour une adresse sans compteur (RG-MCP-80), puis l&#39;enveloppe de <strong>travail</strong> (<code>POS_OAUTH_TOKEN_WORK_PER_MINUTE</code>, 30 000 par minute, tous appels confondus). Après la vérification, le filet global ne compte plus que les <strong>échecs</strong> (3 000 par minute) : un renouvellement ou un échange valides ne sont jamais refusés par lui. <strong>Limite connue</strong> : l&#39;enveloppe de travail pleine refuse tous les appels, valides compris, jusqu&#39;à la minute suivante (une centaine d&#39;adresses IPv4 à plein débit y suffisent) — le coût d&#39;une attaque est multiplié par dix par rapport à avant, pas supprimé.</li><li><strong>RG-MCP-82</strong> — L&#39;état « payant » d&#39;un commerce est tenu à jour : à chaque diffusion des droits (un échec est journalisé et n&#39;interrompt jamais la diffusion aux caisses), à l&#39;affichage de l&#39;écran de consentement et à l&#39;accord, et par une tâche propre au démarrage puis chaque heure pour les commerces à connexion vivante (<code>pos.platform.agent-access-paid-refresh-enabled</code>). Un droit retiré à échéance peut donc rester protégé jusqu&#39;à une heure.</li></ul><h3 id="ecriture-encadree-par-propositions-lot-ven-34-m4-gaas-a2" tabindex="-1">Écriture encadrée par propositions (lot VEN-34 : M4 + GaaS A2) <a class="header-anchor" href="#ecriture-encadree-par-propositions-lot-ven-34-m4-gaas-a2" aria-label="Permalink to &quot;Écriture encadrée par propositions (lot VEN-34 : M4 + GaaS A2)&quot;">​</a></h3><p>Une <strong>proposition</strong> (<code>AgentProposal</code>) est une action préparée par un assistant, sans aucun effet tant qu&#39;un responsable ne l&#39;a pas validée. Fiche de lot : <a href="./../lots/VEN-34">lots/VEN-34.md</a> (vagues A, B, C).</p><ul><li><strong>RG-MCP-83</strong> — La <strong>seule</strong> écriture permise à un assistant est la <strong>création d&#39;une proposition</strong> (<code>POST /api/v1/agent-proposals</code>), avec la portée <code>proposals:write</code>. Elle n&#39;écrit rien d&#39;autre que la proposition et son historique. Toute autre écriture reste refusée (RG-MCP-01). <strong>Aucune clé ni aucun jeton</strong> — assistant, OAuth ou clé <code>WRITE</code> — ne peut valider ni refuser une proposition : les routes de décision sont fermées à toute clé (403).</li><li><strong>RG-MCP-84</strong> — <em>(Réécrite au cadrage VEN-42 du 16/11/2026 ; la version du lot VEN-34 fixait une liste fermée de trois types.)</em> Les types de proposition forment un <strong>registre fermé mais extensible</strong> (RG-MCP-106) : un type n&#39;existe que s&#39;il y est inscrit, avec sa ligne dans la matrice <a href="./../lots/MCP-ECRITURE-MATRICE">lots/MCP-ECRITURE-MATRICE.md</a>. Types du lot VEN-34, inchangés : <code>PURCHASE_ORDER</code> (bon de commande brouillon), <code>PRICE_CHANGE</code> (prix de vente TTC d&#39;un produit, pour l&#39;entreprise ou un magasin), <code>FRAUD_ALERT_HANDLING</code> (acquitter ou rejeter une alerte anti-fraude ; cible : la table <code>fraud_alerts</code> <strong>seulement</strong>). Tout type absent du registre : 422. Sont <strong>hors d&#39;atteinte par construction</strong> (aucun type, aucun outil) les domaines de la <strong>liste d&#39;exclusions validée</strong> de RG-MCP-107 : fiscal, argent, sécurité et accès, abonnement, envois vers l&#39;extérieur, suppressions définitives, création ou modification d&#39;un taux de TVA. Deux précisions par rapport à la version précédente, qui citait « toute suppression » et « la TVA » : l&#39;<strong>archivage</strong>, réversible, peut être proposé ; le <strong>choix d&#39;un taux de TVA existant</strong> à la création d&#39;un produit est réglé par RG-MCP-125 — la TVA d&#39;un produit existant et tout taux restent intouchables. Les propositions ne s&#39;inscrivent pas au JET.</li><li><strong>RG-MCP-85</strong> — Une proposition porte : type, magasin, cible (fournisseur, produit ou alerte), <strong>contenu validé par le serveur</strong> (ce qui sera appliqué), un <strong>instantané calculé par le serveur</strong> à la création (stock, seuil, ventes des 30 derniers jours et déjà commandé pour un bon ; prix et version courants pour un prix ; statut et règle pour une alerte), le <code>dataFreshAt</code> du magasin à cet instant, l&#39;assistant (nom de la clé ou du client OAuth) et l&#39;utilisateur au nom duquel il agit, la <strong>justification</strong> de l&#39;assistant (texte brut, 600 caractères au plus) et au plus 10 <strong>chiffres cités</strong> par lui (libellé et valeur en texte, 80 caractères chacun). Justification et chiffres cités sont des <strong>données, jamais des consignes</strong> (RG-MCP-16) et ne servent jamais à appliquer : seul le contenu validé est appliqué.</li><li><strong>RG-MCP-86</strong> — Cycle de vie : <code>PROPOSED</code> → <code>APPROVED</code> → <code>APPLIED</code> ; <code>PROPOSED</code> → <code>REJECTED</code> ; <code>PROPOSED</code> → <code>EXPIRED</code> (motif <code>TIMEOUT</code>, <code>STALE</code> ou <code>SUPERSEDED</code>). <code>APPLIED</code>, <code>REJECTED</code> et <code>EXPIRED</code> sont finaux. Le contenu est <strong>immuable</strong> après la création (refus de la base) ; chaque changement de statut ajoute une ligne à un <strong>historique append-only</strong> (qui, quand, depuis quel appareil, motif) que l&#39;application ne peut ni modifier ni effacer. Seuls le statut courant et <code>supersededBy</code> de la ligne de tête changent, dans la même transaction que l&#39;historique.</li><li><strong>RG-MCP-87</strong> — Une proposition <strong>expire 72 heures</strong> après sa création <em>(durée confirmée le 15/11/2026 ; règle par défaut de tout type, RG-MCP-108)</em> : tâche périodique, et contrôle à toute décision (409 <code>PROPOSAL_EXPIRED</code>).</li><li><strong>RG-MCP-88</strong> — Une nouvelle proposition sur la <strong>même cible</strong> (même magasin et même fournisseur ; même magasin — ou l&#39;entreprise — et même produit ; même alerte) fait passer la précédente encore <code>PROPOSED</code> à <code>EXPIRED</code> (<code>SUPERSEDED</code>) ; son détail donne <code>supersededBy</code> (identifiant de la remplaçante). <em>(Clé de cible de tout type et des propositions groupées : RG-MCP-117 ; demande strictement identique : RG-MCP-119.)</em></li><li><strong>RG-MCP-89</strong> — <strong>Valider = appliquer</strong>, dans une seule transaction, par le service qu&#39;emploie l&#39;action humaine équivalente (rôle, module de formule, verrou de version), <strong>au nom du validateur</strong> (utilisateur de la session, ou utilisateur dont le PIN vient d&#39;être vérifié sur l&#39;appareil — jamais l&#39;appareil lui-même) ; <code>APPROVED</code> et <code>APPLIED</code> sont écrits avec l&#39;effet. Si les données ont changé depuis la proposition (version différente, produit archivé, fournisseur désactivé, alerte déjà traitée), <strong>rien n&#39;est appliqué</strong> : 409 <code>PROPOSAL_STALE</code> et la proposition passe <code>EXPIRED</code> (<code>STALE</code>). Tout autre refus (rôle, module absent) n&#39;écrit rien et laisse la proposition <code>PROPOSED</code>. Deux décisions simultanées : une seule aboutit, l&#39;autre reçoit 409 <code>PROPOSAL_ALREADY_DECIDED</code>.</li><li><strong>RG-MCP-90</strong> — <strong>Refuser</strong> demande un motif : un <strong>choix obligatoire</strong> dans une liste courte (« pas utile », « chiffres faux », « je le fais moi-même », « autre ») et un texte de 300 caractères au plus, <strong>obligatoire pour « autre »</strong>, facultatif sinon <em>(question 9 de la fiche)</em> ; rien n&#39;est appliqué.</li><li><strong>RG-MCP-91</strong> — <strong>Qui décide</strong> : bon de commande, alerte, surcharge d&#39;un magasin, produit propre à un magasin → MANAGER, OWNER ou ADMIN <strong>de ce magasin</strong> ; prix de l&#39;entreprise → MANAGER, OWNER ou ADMIN (règle de la spec 02, inchangée) <em>(à confirmer, question 2)</em>. <strong>Back-office</strong> : la session suffit. <strong>Appareil</strong> : caisse (<code>REGISTER</code>, téléphone et tablette) ou téléphone de salle (<code>WAITER_TERMINAL</code>) du magasin de la proposition — écran cuisine et borne : 403 ; proposition d&#39;un autre magasin : 404 ; l&#39;utilisateur connecté, responsable du magasin, saisit <strong>son PIN</strong> pour valider, <strong>OWNER et ADMIN compris</strong>, vérifié par le serveur (verrou d&#39;échecs existant) ; refuser ne demande pas de PIN mais reste réservé au responsable connecté <em>(question 3)</em> ; <strong>réseau obligatoire</strong> (aucune décision hors ligne). Toutes les routes <code>/api/v1/agent-proposals/**</code> sont <strong>toujours interdites</strong> à une session de mise en service déléguée à l&#39;équipe Vendora (403 <code>DELEGATION_SCOPE</code>, spec 17 RG-PLAT-34). <em>(Lieu de décision déclaré par chaque type : RG-MCP-113 ; saisie du validateur : RG-MCP-114.)</em> <em>(Dérogation, lot 5 de VEN-49 : <code>PRODUCT_PROMOTE</code> ne se valide que par le <strong>propriétaire ou un administrateur</strong> — règle du service humain ; un gérant voit la proposition mais reçoit 403, RG-MCP-145.)</em></li><li><strong>RG-MCP-92</strong> — <strong>Bon de commande</strong> : l&#39;application crée <strong>toujours un nouveau brouillon</strong> <code>DRAFT</code>, jamais <code>SENT</code>, sans e-mail, <strong>non</strong> marqué <code>suggested</code> (la suggestion automatique RG-SUP-07 ne l&#39;écrase donc pas), rattaché à la proposition (« préparé par l&#39;assistant · validé par … ») ; il se modifie et s&#39;envoie ensuite comme tout brouillon (RG-SUP-05, RG-SUP-08). Lignes : produits actifs suivis en stock, quantité &gt; 0 (<code>quantityOrderedMilli</code>), coût d&#39;achat = prix fournisseur courant s&#39;il n&#39;est pas donné, 100 lignes au plus ; fournisseur actif. Le module « Fournisseurs » est exigé à la création de la proposition et à son application.</li><li><strong>RG-MCP-93</strong> — <strong>Prix</strong> : nouveau prix de vente TTC, entier &gt; 0 dans la plus petite unité de la devise, d&#39;un produit <strong>sans variantes</strong> ; magasin donné → surcharge du magasin (<code>StoreProductOverride</code>, spec 02 / 14), sinon prix de l&#39;entreprise. La version (du produit, ou de la surcharge — son absence comprise) est relevée à la création et comparée sous verrou à l&#39;application. L&#39;application ne modifie <strong>que le prix</strong> : pour le produit, la requête ne porte que <code>salePriceMinor</code> et <code>version</code> (jamais <code>vatRatePermille</code>) ; pour une surcharge, une écriture dédiée relit la ligne sous verrou et <strong>recopie TVA et disponibilité</strong> (jamais l&#39;écriture complète de la surcharge, qui remplace toute la ligne). Un écart de plus de <strong>30 %</strong> est signalé à l&#39;écran de décision. La <strong>TVA n&#39;est jamais modifiable</strong> par une proposition. Les ventes déjà faites, scellées avec leur prix, ne changent pas ; la suivante est scellée au nouveau prix et au taux de TVA inchangé. <em>(Lot VEN-51 : forme groupée, 1 à 100 produits, prix relatifs calculés par le serveur, case imposée dès 2 lignes — RG-MCP-146 ; l&#39;écriture « prix seul » d&#39;une surcharge relit désormais le produit sous verrou : produit retiré ou devenu à variantes → périmée.)</em></li><li><strong>RG-MCP-94</strong> — <strong>Alerte anti-fraude</strong> : alerte <code>OPEN</code> du magasin, statut proposé <code>ACKNOWLEDGED</code> ou <code>DISMISSED</code> et motif proposé. À la validation, le motif enregistré est <strong>celui du validateur</strong> (pré-rempli par la proposition, modifiable, obligatoire : CA-RPT-09), et c&#39;est lui que porte <code>FraudAlertResolved</code> diffusé aux caisses. Une proposition ne contient aucune sanction et aucun champ structuré qui désigne un salarié. Les alertes de stock n&#39;ont pas de traitement et ne sont pas proposables.</li><li><strong>RG-MCP-95</strong> — <strong>Portée et consentement</strong> : <code>proposals:write</code> n&#39;est jamais dans le préréglage de la clé « Assistant IA » (RG-MCP-04) ni cochée d&#39;office. À l&#39;écran de consentement (RG-MCP-37), la famille <code>PROPOSALS</code> forme un <strong>bloc distinct</strong> des familles de lecture, qui dit que chaque proposition est validée par un responsable et que l&#39;assistant n&#39;envoie, ne paie ni ne publie rien ; elle n&#39;est proposée que si le client la demande. Les connexions existantes ne changent pas : l&#39;ajouter demande une nouvelle connexion. Créer une proposition exige aussi la portée de <strong>lecture</strong> du type (<code>purchases:read</code>, <code>catalog:read</code>, <code>fraud:read</code>) et le magasin dans l&#39;accès (RG-MCP-03).</li><li><strong>RG-MCP-96</strong> — La création passe par <strong>les mêmes barrières que la lecture</strong> : <code>MCP_ACCESS</code> (402), arrêts d&#39;urgence (401), accès recalculé à chaque requête (RG-MCP-42), 120 requêtes par minute. Arrêt d&#39;urgence ou option retirée : plus aucune création ; les propositions existantes restent <strong>visibles et décidables</strong> par un humain.</li><li><strong>RG-MCP-97</strong> — <strong>Quotas</strong> : 20 propositions <strong>en attente</strong> par magasin au plus (409 <code>LIMIT_REACHED</code>, <code>kind: AGENT_PROPOSALS_PENDING</code>) ; un nombre de créations <strong>par mois et par magasin</strong> selon la formule <em>(valeurs : question 5 de la fiche)</em> (409 <code>LIMIT_REACHED</code>, <code>kind: AGENT_PROPOSALS</code>, avec <code>limit</code> et <code>used</code>), levable par une dérogation de la console de type nouveau <strong><code>EXTRA_AGENT_PROPOSALS</code></strong> (spec 17). Un quota ne touche jamais une proposition existante (RG-PLAT-15). <em>(Valeurs retenues le 15/11/2026 : 300 par mois ; décompte des propositions groupées et des demandes répétées : RG-MCP-118, 119.)</em></li><li><strong>RG-MCP-98</strong> — <strong>Audit</strong> : la création est inscrite au journal d&#39;audit avec l&#39;acteur <strong><code>AGENT</code></strong> (assistant, accès, utilisateur au nom duquel il agit) ; la décision (<code>APPROVED</code>, <code>REJECTED</code>) et les écritures faites par l&#39;application (bon, prix, alerte) portent le <code>user_id</code> du <strong>validateur</strong> — utilisateur de la session ou dont le PIN a été vérifié, <strong>jamais</strong> l&#39;appareil ni l&#39;utilisateur pour qui l&#39;assistant agit — et l&#39;identifiant de la proposition (« proposé par &lt;assistant&gt;, validé par &lt;nom&gt; ») ; une décision prise sur un appareil inscrit l&#39;appareil dans la colonne <code>audit_log.device_id</code>. L&#39;expiration n&#39;est écrite que dans l&#39;historique de la proposition.</li><li><strong>RG-MCP-99</strong> — <strong>Notifications</strong> : création, puis décision ou expiration, sont diffusées aux appareils du magasin par le canal des alertes des responsables (<code>AgentProposalRaised</code>, <code>AgentProposalDecided</code> ; notification locale à un responsable connecté, push de réveil). Le payload ne contient <strong>aucun texte de l&#39;assistant</strong> : type, résumé construit par le serveur, montant, expiration. Pas d&#39;e-mail <em>(question 7)</em>.</li><li><strong>RG-MCP-100</strong> — <strong>Outils MCP</strong> <code>propose_purchase_order</code>, <code>propose_price_change</code>, <code>propose_alert_handling</code> : listés seulement si l&#39;accès a <code>proposals:write</code> et la lecture du type ; annotations <code>readOnlyHint: false</code>, <code>destructiveHint: false</code>, <code>idempotentHint: false</code>, <code>openWorldHint: false</code>. Leur réponse dit « Proposition créée, en attente de votre validation », avec le résumé, l&#39;expiration et le lien <code>/propositions/&lt;id&gt;</code> du back-office ; jamais « commande passée » ni « prix modifié ». Absents de <code>/demo/mcp</code>. Pour un accès qui peut proposer, les consignes du serveur disent « lecture, et propositions soumises à votre validation » au lieu de « aucun outil n&#39;écrit » ; pour tout autre accès, elles ne changent pas. Classement par méthode : la création est classée <code>proposals:write</code> ; une clé <code>READ</code> / <code>WRITE</code> y reçoit 403 <code>API_KEY_SCOPE</code>, comme toute clé sur les routes de décision. <em>(Outils des types suivants : fabrique RG-MCP-128 ; suivi : <code>list_proposals</code>, RG-MCP-127.)</em></li><li><strong>RG-MCP-101</strong> — <strong>Identifiant opaque</strong> : <code>find_product</code>, <code>reorder_suggestions</code> (produits et fournisseurs) et <code>fraud_alerts</code> rendent un <code>ref</code> (<code>prd_…</code>, <code>sup_…</code>, <code>alr_…</code>) dans le <strong>contenu structuré seulement</strong>, jamais dans le texte (RG-MCP-73) ; les outils de proposition acceptent un <code>ref</code>, un nom ou un code-barres (ambiguïté : candidats, RG-MCP-15). Un <code>ref</code> d&#39;un autre commerce ou d&#39;un magasin hors de l&#39;accès vaut « introuvable ».</li><li><strong>RG-MCP-102</strong> — La carte « Quoi commander » affiche <strong>« Préparer le bon de commande »</strong> par fournisseur seulement si l&#39;accès peut proposer, si l&#39;hôte sait appeler un outil depuis une carte, et hors démonstration ; le bouton appelle <code>propose_purchase_order</code> avec les lignes de la carte puis affiche la confirmation et le lien. Il ne fait rien d&#39;autre.</li><li><strong>RG-MCP-103</strong> — L&#39;<strong>écran de décision</strong> (back-office et caisse) dit <strong>qui</strong> propose (assistant, au nom de qui), <strong>quoi</strong> (lignes et total, prix avant → après et écart, statut et motif d&#39;alerte), <strong>pourquoi</strong> (justification marquée « rédigée par l&#39;assistant », affichée comme texte), <strong>sur quels chiffres et de quand</strong> (instantané ; avertissement si <code>dataFreshAt</code> précédait la création de plus de 15 minutes, RG-RPT-03 ; simple mention si l&#39;instantané a plus de 24 heures à l&#39;ouverture, sans blocage) et <strong>jusqu&#39;à quand</strong>. Mise en page et textes : fiche VEN-34, section « Maquettes ». FR, EN, AR (droite à gauche), clair et sombre, téléphone et tablette. <em>(Rendu commun à tous les types : RG-MCP-120, 121.)</em></li><li><strong>RG-MCP-104</strong> — <strong>Interrupteur</strong> <code>pos.agent-proposals.enabled</code> (<code>POS_AGENT_PROPOSALS_ENABLED</code>), <strong>faux par défaut</strong> : éteint, la création répond 404 et les outils de proposition ne sont pas listés ; les propositions existantes restent décidables. <em>(Allumage type par type et réglage par famille : RG-MCP-110, 111.)</em></li></ul><h3 id="ecriture-etendue-registre-de-types-parite-avec-le-back-office-projet-p-ven-7-cadrage-ven-42" tabindex="-1">Écriture étendue : registre de types, parité avec le back-office (projet P-VEN-7, cadrage VEN-42) <a class="header-anchor" href="#ecriture-etendue-registre-de-types-parite-avec-le-back-office-projet-p-ven-7-cadrage-ven-42" aria-label="Permalink to &quot;Écriture étendue : registre de types, parité avec le back-office (projet P-VEN-7, cadrage VEN-42)&quot;">​</a></h3><p>Décision d&#39;Ahmed du 15/11/2026 : l&#39;assistant peut <strong>préparer tout ce qu&#39;un gérant fait au back-office</strong>, toujours par proposition validée par un responsable. RG-MCP-83 reste vraie ; seule la liste des types s&#39;élargit. La table de correspondance écran → type fait foi : <a href="./../lots/MCP-ECRITURE-MATRICE">lots/MCP-ECRITURE-MATRICE.md</a>. Fiche du socle : <a href="./../lots/MCP-ECRITURE-SOCLE">lots/MCP-ECRITURE-SOCLE.md</a> (questions Q1 → Q24). Avis intégrés le 16/11/2026 : <code>expert-fiscal</code> (conforme avec réserves R1 → R10), <code>spec-coherence</code>, <code>design-ux</code>. Les règles marquées « (à confirmer — Q n) » ont été <strong>décidées par Ahmed le 16/11/2026</strong> selon la recommandation de la fiche (section « Décisions d&#39;Ahmed », Q1 → Q24) : ces mentions sont retirées, les règles ci-dessous sont en vigueur.</p><ul><li><strong>RG-MCP-105</strong> — <strong>Périmètre</strong> : toute action d&#39;écriture d&#39;un écran du back-office est soit un <strong>type de proposition</strong> inscrit au registre, soit <strong>exclue</strong> (RG-MCP-107), soit en <strong>second temps</strong> (RG-MCP-124), soit <strong>non retenue</strong> avec l&#39;une de ces raisons, écrite dans la matrice : aucun service humain équivalent ; fichier binaire ; geste physique ou de service en temps réel ; <strong>valeur trop faible ou non demandé en v1</strong>. La matrice liste chaque écran ; un test échoue si une route du back-office (<code>app.routes.ts</code>) dont l&#39;écran écrit n&#39;y figure pas. Aucune écriture directe : un assistant ne fait toujours que proposer.</li><li><strong>RG-MCP-106</strong> — <strong>Registre de types</strong> : fermé (défini dans le code, jamais par configuration ni par un commerce) mais extensible. Un type y déclare, et rien d&#39;autre ne le définit : son nom, sa <strong>famille de propositions</strong> (RG-MCP-109), la ou les <strong>portées de lecture</strong> et le ou les <strong>modules de formule</strong> exigés — <strong>y compris ceux que le back-office exige à la route</strong> (<code>ModuleRoutes</code>) et non dans le service, que le registre revérifie lui-même à la création et à l&#39;application —, la <strong>liste fermée de ses champs</strong> (RG-MCP-115), le validateur du contenu, le calcul de l&#39;<strong>instantané</strong>, la <strong>clé de cible</strong> (RG-MCP-117), le <strong>contrôle de péremption</strong>, l&#39;<strong>applicateur</strong> (RG-MCP-123), le <strong>lieu de décision</strong> (RG-MCP-113), la <strong>saisie du validateur</strong> et la <strong>confirmation renforcée</strong> (RG-MCP-114), le niveau de <strong>risque</strong> (faible, moyen, élevé), sa <strong>réversibilité</strong>, son plafond de lignes s&#39;il est groupé (RG-MCP-116), son <strong>modèle d&#39;affichage</strong> (RG-MCP-120), son texte de succès et le lien vers l&#39;objet (RG-MCP-131). Type absent du registre : 422 <code>PROPOSAL_INVALID</code> avec la violation <code>TYPE_UNKNOWN</code>, rien d&#39;écrit. Ajouter un type exige sa ligne dans la matrice, les tests génériques (RG-MCP-130) et l&#39;avis <code>expert-fiscal</code>.</li><li><strong>RG-MCP-107</strong> — <strong>Hors d&#39;atteinte par construction</strong> (décision d&#39;Ahmed du 15/11/2026, VEN-43 option A) : aucun type, aucun outil, aucun applicateur ne peut toucher (1) le <strong>fiscal</strong> — ventes scellées, Z, clôtures, archives, e-reporting, NACEF, alertes d&#39;intégrité fiscale (RG-FISC-12), événements en quarantaine, mentions fiscales du ticket (raison sociale, adresse, identifiants, mentions légales) et tout terme fiscal dans ses messages libres, réglages des exports comptables, devise et fuseau d&#39;un magasin ; (2) l&#39;<strong>argent</strong> — paiements, encaissements, remboursements, annulations de vente, intentions de paiement, fournisseurs et terminaux de paiement, <strong>le parcours de paiement des bornes</strong> (<code>paymentFlow</code>, <code>manualPaymentConfirm</code>, <code>paymentTimeoutMinutes</code>), le droit d&#39;encaisser d&#39;un téléphone de salle (<code>canCheckout</code>), la caisse principale, dettes fournisseurs, ardoises ; (3) la <strong>sécurité et les accès</strong> — utilisateurs, rôles, PIN, politiques d&#39;approbation et d&#39;authentification, seuils sous PIN, clés d&#39;API, accès et réglages de l&#39;assistant (RG-MCP-111), connexions OAuth, délégations, webhooks, jetons publics et clés du réseau local, révocation ou remplacement d&#39;un appareil (<code>replacesDeviceId</code>), la décision d&#39;une proposition ; (4) l&#39;<strong>abonnement</strong> et la formule (options, magasins et appareils comptés par la formule) ; (5) les <strong>envois vers l&#39;extérieur</strong> — envoi d&#39;un bon au fournisseur, messages, reçus et relances aux clients, destinataires d&#39;un envoi programmé, activation d&#39;un canal de commande ; (6) les <strong>suppressions définitives</strong> (l&#39;archivage, réversible, reste possible) ; (7) la <strong>création ou la modification d&#39;un taux de TVA</strong>, et la TVA d&#39;un produit existant ou d&#39;une surcharge. <strong>Exception voulue</strong> (commentaire d&#39;Ahmed sur VEN-43, confirmée le 16/11/2026) : l&#39;<strong>appairage</strong> d&#39;un appareil et le <strong>routage du matériel</strong> ne sont pas exclus, bien qu&#39;ils touchent aux accès — l&#39;appairage ne fait que préparer, le code n&#39;est montré qu&#39;à l&#39;humain (RG-MCP-126) ; les terminaux de paiement restent exclus. Un <strong>test de garde</strong> échoue si un applicateur du registre référence un service, une table <strong>ou un champ fermé</strong> de cette liste. <em>(Précisée par RG-MCP-138, lot VEN-58 vague 1 : la garde juge les <strong>appels déclarés</strong> de chaque type, vérifiés sur le code compilé, et non plus les seuls services injectés ; les exclusions y sont nommées par classe, méthode, contexte et table.)</em></li><li><strong>RG-MCP-108</strong> — <strong>Règles par défaut de tout type</strong> (acquis du lot VEN-34, sans exception possible par type) : contenu validé par le serveur et immuable (RG-MCP-85, 86) ; instantané et <code>dataFreshAt</code> à la création ; expiration <strong>72 heures</strong> (RG-MCP-87) ; remplacement par cible (RG-MCP-88) ; <strong>valider = appliquer</strong> dans une transaction par le service de l&#39;action humaine, au nom du validateur, rien d&#39;appliqué si les données ont changé (RG-MCP-89) ; motif de refus en liste courte (RG-MCP-90) ; sur la caisse, <strong>PIN du responsable toujours demandé</strong>, refus sans PIN, <strong>aucune décision hors ligne</strong>, écran cuisine et borne exclus, sessions déléguées à l&#39;équipe Vendora interdites (RG-MCP-91) ; mêmes barrières que la lecture (RG-MCP-96) ; audit d&#39;acteur <code>AGENT</code> à la création, <code>user_id</code> du validateur sur l&#39;effet (RG-MCP-98) ; notifications sans texte de l&#39;assistant, <strong>pas d&#39;e-mail</strong> (RG-MCP-99) ; justification et chiffres cités <strong>jamais appliqués</strong> (RG-MCP-85) ; aucune inscription au JET (RG-MCP-84).</li><li><strong>RG-MCP-109</strong> — <strong>Familles de propositions</strong> (<code>ProposalFamily</code>) : chaque type appartient à une seule famille — <code>CATALOG</code> (produits, prix, catégories, modificateurs, écran de vente, import), <code>STOCK</code> (mouvements, inventaire, lots, transferts), <code>PURCHASES</code> (bons, réceptions, fournisseurs), <code>RESTAURANT</code> (formules, fiches techniques, plan de salle, postes, profils de salle), <code>CUSTOMERS</code> (programme de fidélité), <code>SETTINGS</code> (magasin, ticket, apparence, rapports, canaux), <code>DEVICES</code> (appairage, réglages et disponibilité des appareils), <code>FRAUD</code> (traitement des alertes). Les trois types du lot VEN-34 y sont rangés : <code>PRICE_CHANGE</code> → <code>CATALOG</code>, <code>PURCHASE_ORDER</code> → <code>PURCHASES</code>, <code>FRAUD_ALERT_HANDLING</code> → <code>FRAUD</code>. Ce sont des familles <strong>d&#39;écriture</strong>, distinctes des familles <strong>OAuth de lecture</strong> de RG-MCP-37 (<code>SALES</code>, <code>STOCK</code>, <code>PURCHASES</code>, <code>DEVICES</code>, <code>FRAUD</code>), dont quatre portent le même nom : accorder la lecture du stock n&#39;accorde pas de proposer sur le stock, et l&#39;inverse. Dans l&#39;API et les écrans, elles sont toujours nommées <code>proposalFamily</code> / <code>proposalFamilies</code> et présentées dans le bloc « Préparer des propositions ».</li><li><strong>RG-MCP-110</strong> — <strong>Allumage par l&#39;exploitation</strong> : l&#39;interrupteur général (RG-MCP-104) reste ; s&#39;y ajoute la <strong>liste des types allumés</strong> <code>pos.agent-proposals.types</code> (<code>POS_AGENT_PROPOSALS_TYPES</code> : <strong>codes de types seulement</strong> — un nom de famille n&#39;allume rien et est signalé au démarrage, constat de la clôture du socle le 17/11/2026), dont le défaut est <strong>les trois types du lot VEN-34</strong>. Un type inscrit au registre mais non allumé se comporte comme l&#39;interrupteur éteint pour lui seul : création 404, outil non listé, propositions existantes décidables. Un type nouveau est donc toujours fusionné éteint ; il n&#39;est allumé sur le staging qu&#39;après la revue de sécurité de sa famille (VEN-58). La production reste hors sujet. <em>(Revue par famille, tranche par type ajouté, rapport et extinction en cas de défaut bloquant : RG-MCP-139.)</em> <em>(Lot VEN-51 : un type peut déclarer des <strong>jetons de forme</strong> — <code>PRICE_CHANGE_GROUP</code> — allumés comme un code de type mais seulement avec lui, rendus dans <code>proposalTypes</code> ; forme éteinte → 404 pour elle seule, RG-MCP-146.)</em></li><li><strong>RG-MCP-111</strong> — <strong>Réglage du gérant et consentement par famille</strong> : le commerce règle, par famille de propositions, « l&#39;assistant peut proposer » (page Réglages › Assistant IA, propriétaire et administrateurs, <strong>éteint par défaut</strong>) ; chaque accès (clé « Assistant IA », connexion OAuth) porte la liste des familles accordées à sa création ou au consentement, bloc distinct, <strong>jamais cochée d&#39;office</strong>. Un assistant ne peut créer une proposition que si <strong>toutes</strong> ces conditions sont vraies : type allumé (RG-MCP-110), famille autorisée par le commerce, famille accordée à l&#39;accès, portée <code>proposals:write</code>, portée de lecture et module du type. Une condition fausse : outil non listé et création refusée (403 <code>PROPOSAL_FAMILY_DISABLED</code>, ou 404 si le type est éteint). Reprise de l&#39;existant : les accès qui ont déjà <code>proposals:write</code> reçoivent <code>CATALOG</code>, <code>PURCHASES</code> et <code>FRAUD</code>, et ces trois familles sont autorisées pour leur commerce ; rien d&#39;autre ne change pour eux. Un type ajouté plus tard à une famille déjà accordée est couvert par cet accord. Retirer une famille n&#39;efface rien : plus de création, propositions existantes décidables. <strong>Lire et modifier</strong> ces réglages est réservé à la <strong>session</strong> d&#39;un propriétaire ou d&#39;un administrateur : toute clé (AGENT, <code>READ</code>, <code>WRITE</code>) et tout jeton y reçoivent 403, en lecture comme en écriture — un assistant ne peut jamais élargir ses propres droits. Sous <strong>délégation Vendora</strong> : lecture seule (la page s&#39;affiche comme le reste de Réglages › Assistant IA, RG-MCP-49), toute modification refusée (403 <code>DELEGATION_SCOPE</code>). Chaque changement est inscrit au journal d&#39;audit.</li><li><strong>RG-MCP-112</strong> — <strong>Portées</strong> : <code>proposals:write</code> reste la <strong>seule</strong> portée d&#39;écriture d&#39;un assistant ; il n&#39;existe pas de portée d&#39;écriture par famille. Créer exige en plus la ou les portées de <strong>lecture</strong> du type (matrice) et le magasin dans l&#39;accès (RG-MCP-03) ; portée manquante : 403 <code>API_KEY_SCOPE</code>, portée nommée dans le message. <strong>Portées de lecture accordables</strong> : la connexion OAuth ne sait accorder aujourd&#39;hui ni <code>settings:read</code> ni <code>customers:read</code> ; une famille OAuth de lecture <strong>« Réglages »</strong> (<code>settings:read</code>) est ajoutée, jamais cochée d&#39;office, pour que les types des familles <code>SETTINGS</code>, <code>RESTAURANT</code> et la fidélité soient utilisables par la connexion en un clic. <code>customers:read</code> et <code>team:read</code> restent <strong>hors</strong> du plafond d&#39;un assistant : un type dont la route de lecture en dépend, ou dont la route est réservée (canaux), reçoit son état courant par un <strong>instantané ou une lecture dédiée</strong> limités à ses champs ouverts, sans nom de personne ni jeton. Les chiffres de clients sans nom du jalon 5 auront leur portée et leur famille propres.</li><li><strong>RG-MCP-113</strong> — <strong>Lieu de décision par type</strong> : un type se décide <strong>au back-office seulement</strong> (défaut) ou <strong>aussi sur la caisse et le téléphone de salle</strong> du magasin, s&#39;il le déclare et si la proposition porte un magasin. Une proposition sans magasin (entreprise entière) se décide toujours au back-office seulement — c&#39;est le cas du prix de tous les magasins (décision d&#39;Ahmed). Sur un appareil, une proposition « back-office seulement » est <strong>listée et affichée en lecture</strong>, badge « Back-office », avec le renvoi « Ouvrez le back-office pour décider » et <strong>aucun</strong> bouton, Refuser compris ; une proposition sans magasin l&#39;est sur les caisses de <strong>tous</strong> les magasins du commerce. Sa décision par les routes de caisse est refusée (403 <code>PROPOSAL_BACK_OFFICE_ONLY</code>). L&#39;écran cuisine et la borne ne décident jamais, quel que soit le type.</li><li><strong>RG-MCP-114</strong> — <strong>Saisie du validateur et confirmation renforcée</strong> : un type peut exiger à la validation (a) une <strong>saisie</strong> — <strong>texte</strong> (libellé, valeur proposée pré-remplie, obligatoire ou non, longueur bornée : cas du motif d&#39;une alerte, RG-MCP-94), <strong>choix</strong> dans une liste fermée fournie par le serveur, sans présélection quand la règle du type l&#39;interdit (taux de TVA d&#39;un produit créé sans taux nommé, RG-MCP-125 ; motif « vol » d&#39;une perte de stock), ou <strong>PIN du responsable au back-office</strong> quand l&#39;action humaine équivalente l&#39;exige déjà (mouvements de stock) ; c&#39;est toujours la saisie du validateur qui est appliquée et auditée, jamais celle de l&#39;assistant ; (b) une <strong>confirmation renforcée</strong> — case à cocher dont le texte et la condition sont calculés par le serveur (seuil propre au type, ou toujours pour un type de risque élevé), qui cite ce qu&#39;elle confirme (« Je confirme un écart de 53,3 % », « marchandise effectivement reçue »). La case s&#39;affiche <strong>sur toutes les surfaces, caisse comprise, avant le PIN</strong> : le PIN prouve qui valide, pas que l&#39;écart a été lu. Pour les types inscrits après le lot VEN-34, le serveur refuse une validation sans la saisie ou la confirmation attendue : 422 <code>VALIDATOR_INPUT_REQUIRED</code> ou <code>CONFIRMATION_REQUIRED</code> (codes d&#39;erreur de la décision, à la racine de la réponse ; ce ne sont pas des violations de création), rien d&#39;appliqué, la proposition reste en attente ; le bouton de validation reste inactif tant qu&#39;elles manquent. Les trois types du lot VEN-34 gardent leurs règles <strong>côté serveur</strong> (leurs tests ne changent pas) ; à l&#39;écran, ils passent par le rendu commun et gagnent donc la case sur la caisse.</li><li><strong>RG-MCP-115</strong> — <strong>Champs fermés</strong> : chaque type n&#39;accepte que ses champs. Un champ inconnu, ou connu d&#39;un autre type, donne la violation <code>FIELD_NOT_ALLOWED</code> (champ nommé) ; un champ qui évoque la TVA là où elle n&#39;est pas modifiable, la violation <code>VAT_NOT_ALLOWED</code>. Comme <code>TYPE_UNKNOWN</code>, ce sont des <strong>violations</strong> rendues dans un 422 <code>PROPOSAL_INVALID</code> (liste <code>violations</code> à la racine de la réponse, comme aujourd&#39;hui), pas des codes d&#39;erreur. Ce contrôle est fait <strong>par le registre, pour tous les types</strong>, avant toute lecture du contenu. Un type dont le document humain porte des champs exclus (RG-MCP-107) n&#39;ouvre qu&#39;une <strong>liste de champs ouverts</strong> ; les champs fermés sont inscrits au test de garde. Les types nouveaux reçoivent leurs champs dans l&#39;objet <code>content</code> de la demande ; les trois types du lot VEN-34 gardent leurs champs actuels.</li><li><strong>RG-MCP-116</strong> — <strong>Propositions groupées</strong> : un type qui le déclare accepte plusieurs <strong>lignes du même type</strong> dans une proposition (<strong>100 lignes au plus</strong>, plafond plus bas possible par type). Tout ou rien : une ligne invalide fait refuser la création (422, numéro de la ligne) ; une ligne périmée à la validation rend <strong>toute</strong> la proposition <code>STALE</code> ; l&#39;application se fait dans <strong>une seule transaction</strong>. Si le service humain accepte, lui, un résultat partiel (stock initial : lignes valides enregistrées, lignes refusées listées), l&#39;applicateur contrôle d&#39;abord toutes les lignes et <strong>annule la transaction</strong> dès qu&#39;une seule est refusée. La saisie du validateur vaut pour toute la proposition ; la confirmation renforcée est exigée dès qu&#39;<strong>une</strong> ligne la déclenche et cite leur nombre. Une proposition groupée compte pour <strong>une</strong> dans les quotas (RG-MCP-118). <em>(Lot VEN-51 : un type peut imposer la case pour tout le groupe — prix groupé, dès 2 lignes, RG-MCP-146.)</em></li><li><strong>RG-MCP-117</strong> — <strong>Clé de cible</strong> (complète RG-MCP-88) : <code>TYPE:&lt;magasin ou *&gt;:&lt;identifiant de la cible&gt;</code> ; pour une création, l&#39;identifiant est le nom normalisé de l&#39;objet à créer ; pour un document unique par magasin (plan de salle, profil de ticket), le magasin suffit. Proposition groupée : <code>TYPE:&lt;magasin ou *&gt;:GROUP:&lt;empreinte des cibles triées&gt;</code>. Une proposition groupée <strong>remplace</strong> aussi toute proposition simple en attente du même type sur l&#39;une de ses cibles ; une proposition simple ne remplace pas une groupée, mais la validation de l&#39;une périme l&#39;autre par le contrôle de péremption (la donnée a changé). <em>(Lot VEN-49 création, RG-MCP-140 : la clé d&#39;une création est calculée par le service sur le <strong>nom normalisé</strong> que le type fournit, et <code>target_id</code> vaut alors l&#39;identifiant de la proposition — qui devient celui de l&#39;objet créé ; colonne inchangée, aucune migration.)</em></li><li><strong>RG-MCP-118</strong> — <strong>Quotas</strong> : les valeurs du lot VEN-34 sont gardées — <strong>20 en attente</strong> et <strong>300 créations par mois</strong>, par magasin (les propositions sans magasin forment un compteur à part pour le commerce), dérogation <code>EXTRA_AGENT_PROPOSALS</code>, illimité en Sur mesure. Une proposition groupée compte pour une ; une demande dédoublonnée (RG-MCP-119) ne compte pas ; un remplacement compte. Aucun quota par famille. Les valeurs sont revues au jalon 7 sur les mesures réelles (consommation, taux de refus) ; le réglage par formule reste au lot GaaS A7.</li><li><strong>RG-MCP-119</strong> — <strong>Demande répétée</strong> : si le même accès redemande une proposition dont la clé de cible <strong>et</strong> le contenu validé sont identiques à une proposition encore <code>PROPOSED</code>, le serveur <strong>renvoie l&#39;existante</strong> (200, <code>deduplicated: true</code>) : rien n&#39;est écrit, aucun quota n&#39;est consommé, aucune notification ne repart. Contenu différent sur la même cible : remplacement (RG-MCP-88). Aucune clé d&#39;idempotence n&#39;est demandée au client. <em>(Lot VEN-49 création : la comparaison porte sur <strong>tout</strong> le contenu validé — un type n&#39;y met donc jamais de valeur tirée au hasard ; l&#39;identifiant du produit créé est celui de la proposition, RG-MCP-140.)</em> <em>(Lot VEN-51 : les trois types de VEN-34, forme groupée du prix comprise, ne dédoublonnent pas — une demande identique remplace ; alignement au jalon 7, VEN-57.)</em></li><li><strong>RG-MCP-120</strong> — <strong>Modèle d&#39;affichage générique</strong> (<code>display</code>, version 1 ; maquettes et tableau complet : fiche du socle, section « Maquettes », G1) : pour chaque proposition, le <strong>serveur</strong> fournit, dans la langue demandée (FR, EN, AR), ce que l&#39;écran de décision montre. <strong>Enveloppe</strong> : version du modèle <code>v</code> ; libellés du type et de la famille, code fermé de famille et <strong>code fermé d&#39;icône</strong> ; titre ; résumé d&#39;une ligne ; <strong>valeur forte de la ligne de liste</strong> (<code>keyFigure</code>) ; portée en toutes lettres ; risque ; réversibilité ; avertissements ; bloc <strong>« Chiffres de Vendora »</strong> (l&#39;instantané : sur quels chiffres et de quand, RG-MCP-103) ; bloc de décision — lieux, <strong>droit de celui qui lit</strong> (<code>viewer</code> : peut décider ou non, avec la raison traduite : rôle, back-office seulement, module, délégation, rôle d&#39;appareil), <strong>libellés long et court du bouton</strong> (jamais « Valider » nu), saisie attendue, confirmation, dialogue récapitulatif ; texte de succès (RG-MCP-131). <strong>Zone « ce qui sera appliqué »</strong> : liste ordonnée de blocs pris dans une <strong>liste fermée de cinq</strong> — <code>CHANGES</code> (avant → après champ par champ ; sans « avant » pour une création), <code>LINES</code> (colonnes, lignes signalées, total, « total partiel » ; tout type groupé), <code>OPERATIONS</code> (ajouter, renommer, déplacer, retirer, régler : documents publiés en entier), <code>TARGET</code> (rappel en lecture de l&#39;objet visé : alerte, lot, bon, appareil, avec son lien), <code>NOTES</code> (phrases du serveur). Les chiffres sont des <strong>valeurs typées</strong> (montant, quantité, pourcentage, date…) formatées par l&#39;app, chacune avec un <strong>texte de secours</strong> déjà formaté. Le modèle est construit à partir du <strong>contenu validé, de l&#39;instantané et du référentiel</strong> (le nom d&#39;un produit vient de la base, pas de l&#39;assistant), jamais de la justification. <strong>Seule exception</strong> : le <strong>pré-remplissage d&#39;une saisie</strong> peut reprendre la valeur proposée par l&#39;assistant (motif d&#39;une alerte) ; il est alors marqué « pré-rempli par l&#39;assistant, modifiable » et n&#39;est appliqué que si le validateur le laisse. Les écrans affichent ce modèle sans rien savoir du type ; les trois rendus du lot VEN-34 passent par lui sans perte d&#39;information.</li><li><strong>RG-MCP-121</strong> — <strong>Écran de décision générique</strong> : ordre fixe des zones, quel que soit le type — en-tête, états et avertissements, <strong>ce qui sera appliqué</strong>, chiffres de Vendora, <strong>rédigé par l&#39;assistant</strong>, historique, zone de décision ; l&#39;assistant n&#39;est jamais au-dessus de ce qui sera appliqué. Tous les états existants (en attente, appliquée, refusée, expirée, périmée, remplacée, module retiré, rôle insuffisant, hors ligne) valent pour tout type ; quand celui qui lit ne peut pas décider, la barre d&#39;actions est remplacée par la raison écrite, jamais par un bouton grisé muet. <strong>App d&#39;ancienne version</strong> : une valeur typée inconnue s&#39;affiche par son texte de secours et la décision reste possible ; un <strong>bloc</strong> ou une <strong>saisie</strong> inconnus, ou une version <code>v</code> plus grande, donnent le titre, le résumé, la portée et « Ouvrez le back-office pour décider », <strong>sans aucun bouton, Refuser compris</strong> ; jamais un écran vide. Le back-office filtre par famille (puis par type) et <strong>trie</strong> : en attente, puis ce qui expire dans moins de 6 heures, puis du risque élevé au faible, puis par expiration ; la liste n&#39;affiche que la mention « Risque élevé ». <strong>Validation en lot</strong> : <strong>non livrée</strong> (décision d&#39;Ahmed du 16/11/2026) — les propositions groupées de RG-MCP-116 couvrent le besoin. Si elle est rouverte au jalon 7, ce sera au back-office seulement, 10 propositions au plus, uniquement des types de risque faible ou moyen sans saisie, sans confirmation renforcée et sans avertissement, chacune <strong>ouverte au moins une fois</strong> par ce responsable, après un récapitulatif qui les liste une à une, chacune appliquée dans sa propre transaction. Il n&#39;existe jamais de « tout valider » sans aperçu.</li><li><strong>RG-MCP-122</strong> — <strong>Verrou commun des surcharges de magasin</strong> : tout applicateur qui écrit une surcharge (<code>StoreProductOverride</code>) passe par une <strong>écriture dédiée à un seul champ</strong> de <code>StoreProductOverrideService</code> (prix seul, disponibilité seule), qui prend le verrou commun de la ligne (magasin, produit), relit la ligne, compare la version relevée (absence comprise) et <strong>recopie les autres champs, TVA comprise</strong>. Jamais l&#39;écriture complète de la ligne, jamais le retour à l&#39;héritage. Une proposition <strong>groupée</strong> prend ses verrous <strong>dans l&#39;ordre trié (magasin, produit)</strong>, dans une seule transaction, pour qu&#39;aucun interblocage ne soit possible. Un test de course par écriture dédiée (prix seul, <strong>disponibilité seule</strong>) et pour la <strong>version groupée</strong> prouve qu&#39;aucun écrivain n&#39;efface la TVA d&#39;un magasin (réserves fiscales R1 du lot VEN-34 et R8 du cadrage).</li><li><strong>RG-MCP-123</strong> — <strong>Applicateur</strong> : il appelle la <strong>méthode de service de l&#39;action humaine</strong> nommée dans la matrice, avec le validateur comme utilisateur ; il n&#39;écrit jamais lui-même dans une table métier. Parce qu&#39;il n&#39;emprunte pas la route du back-office, il <strong>revérifie ce que la route vérifie pour l&#39;humain</strong> — module de formule exigé par <code>ModuleRoutes</code>, rôle — à la création et à l&#39;application (refus : comme RG-MCP-92, la proposition reste en attente). Une règle qui vit dans un contrôleur est d&#39;abord extraite dans un service, sans changer le comportement de la route humaine. Un document publié en entier (plan de salle, profil de ticket, canaux) est modifié par un applicateur qui part de la <strong>version relevée</strong>, n&#39;y change que les <strong>champs ouverts</strong> du type et recopie le reste. Le stock n&#39;est jamais écrit directement : un type de stock ne produit que des <strong>mouvements signés</strong> par le service de la spec 05, son contenu est un <strong>écart</strong>, jamais une quantité cible, la date du mouvement est <strong>l&#39;heure du serveur à la validation</strong>, et la justification de l&#39;assistant n&#39;est jamais recopiée dans la note du mouvement. <em>(Lot VEN-58 vague 1 : règle tenue <strong>sans exception</strong> — le lien bon ↔ proposition, seule écriture directe d&#39;un applicateur jusque-là, est écrit par <code>PurchaseOrderService.create</code> ; agir au nom du validateur passe par <code>ApplyContext.asValidator</code> ; garde et tests de source : RG-MCP-138.)</em> <em>(Lot VEN-49 création : un type peut <strong>lire</strong> en SQL — produits, catégories, magasins, taux de TVA — pour résoudre, contrôler et afficher ; seules les écritures, les dépôts de données et les classes exclues lui sont refusés, RG-MCP-138, 140.)</em></li><li><strong>RG-MCP-124</strong> — <strong>Données des clients</strong> (décision d&#39;Ahmed du 15/11/2026, VEN-44 option A) : premier temps — chiffres <strong>sans nom</strong> en lecture et propositions qui ne citent personne (<code>LOYALTY_CONFIG_UPDATE</code>), derrière la famille <code>CUSTOMERS</code>, à part et jamais cochée d&#39;office ; second temps — fiches nominatives, <strong>seulement après un avis juridique</strong> RGPD / INPDP et un ticket dédié. D&#39;ici là : aucun type ne lit ni n&#39;écrit une fiche, aucun nom de client n&#39;apparaît dans un contenu, un instantané, un résumé ou une réponse d&#39;outil ; <code>customers:read</code> reste hors du plafond d&#39;un assistant (RG-MCP-112). <code>LOYALTY_CONFIG_UPDATE</code> est de fait une <strong>règle de remise future</strong> : risque élevé, confirmation renforcée, avantage affiché avant → après.</li><li><strong>RG-MCP-125</strong> — <strong>TVA à la création d&#39;un produit</strong> <em>(avis <code>expert-fiscal</code> du 16/11/2026 : conforme sous cette rédaction)</em> : <code>PRODUCT_CREATE</code> et les lignes de création de <code>CATALOG_IMPORT</code> désignent un taux <strong>déjà présent et actif</strong> dans le référentiel du commerce. Si l&#39;assistant ne nomme pas de taux, <strong>aucun n&#39;est présélectionné</strong> — jamais de repli sur le taux par défaut : le <strong>validateur le choisit</strong> parmi les taux actifs (saisie obligatoire, RG-MCP-114). Le taux est toujours affiché <strong>en clair, libellé et pourcentage</strong>, et couvert par la confirmation renforcée ; un taux désactivé entre la création et la validation périme la proposition. Une proposition ne crée ni ne modifie jamais un taux, et ne change jamais la TVA d&#39;un produit existant ni d&#39;une surcharge : champ de TVA dans <code>PRODUCT_UPDATE</code>, ou ligne de mise à jour d&#39;un import dont le taux diffère du taux actuel du produit → violation <code>VAT_NOT_ALLOWED</code> (avec le numéro de la ligne). L&#39;écran d&#39;une formule affiche le taux de chaque composante. <em>(Livrée pour <code>PRODUCT_CREATE</code> par RG-MCP-140 et 141 : taux affiché « nom du référentiel — pourcentage calculé », taux nommé non remplaçable, taux à choisir sans présélection, jamais 0 % nommé par l&#39;assistant ; les lignes de création de <code>CATALOG_IMPORT</code> suivront les mêmes règles.)</em></li><li><strong>RG-MCP-126</strong> — <strong>Secrets</strong> : aucun secret n&#39;entre dans une proposition — ni dans son contenu, son instantané, son historique, son résumé, ses notifications, ni dans la réponse d&#39;un outil. <code>DEVICE_PAIRING</code> ne prépare que le magasin, le rôle et le nom — jamais le remplacement d&#39;un appareil (<code>replacesDeviceId</code>), une pré-configuration (<code>preconfig</code>) ni l&#39;adresse du serveur du QR (<code>serverUrl</code>) ; le <strong>code d&#39;appairage</strong> est produit par le service existant <strong>après</strong> la validation et montré à l&#39;humain qui valide, à l&#39;écran seulement. La création est refusée si le magasin n&#39;est pas éligible (limite de formule, module), et la suspension d&#39;un client ne bloque que les <strong>nouveaux</strong> appairages.</li><li><strong>RG-MCP-127</strong> — <strong>Outil <code>list_proposals</code></strong> (lecture) : rend à l&#39;assistant les propositions <strong>qu&#39;il peut voir</strong> — magasins de l&#39;accès, familles accordées — avec statut, type, résumé construit par le serveur, expiration et, pour une proposition refusée, le motif de la liste courte. Il ne reçoit <strong>ni la justification, ni les chiffres cités, ni le commentaire libre du responsable, ni le nom du validateur</strong> : la liste actuelle (<code>GET /api/v1/agent-proposals</code>), qui les porte, reste réservée aux sessions et aux clés <code>READ</code> / <code>WRITE</code> ; l&#39;outil lit une <strong>vue dédiée aux accès d&#39;assistant</strong>, classée sous <code>proposals:write</code> (§ 6). Il sert à dire « 3 propositions attendent votre validation » et à ne pas reproposer ce qui vient d&#39;être refusé. Listé dès que l&#39;accès peut proposer ; absent de <code>/demo/mcp</code>.</li><li><strong>RG-MCP-128</strong> — <strong>Fabrique d&#39;outils de proposition</strong> : un outil d&#39;écriture ne déclare que sa description, ses paramètres, son ou ses types et sa portée de lecture ; la fabrique apporte le reste, à l&#39;identique pour tous — exigence de <code>proposals:write</code>, liste selon les types que l&#39;accès peut créer (<code>proposalTypes</code> de <code>GET /api/v1/api-keys/me</code>), annotations d&#39;écriture (RG-MCP-100), absence sur <code>/demo/mcp</code>, traduction des refus et candidats d&#39;ambiguïté, langue, réponse « Proposition créée, en attente de votre validation » avec résumé, expiration et lien. Aucun outil n&#39;appelle une autre route que <code>POST /api/v1/agent-proposals</code> (liste blanche inchangée et testée). <strong>Forme</strong> : <strong>un outil par objet métier</strong>, avec un paramètre <code>action</code> fermé quand l&#39;objet a plusieurs gestes (<code>propose_product</code> : créer, modifier, archiver) ; les trois outils du lot VEN-34 gardent leur nom et leurs paramètres. <strong>Montants</strong> : tout prix ou coût reçu par un outil est en unités de la devise, converti par une règle unique selon les décimales de la devise (trois pour le dinar).</li><li><strong>RG-MCP-129</strong> — <strong>Identifiants opaques étendus</strong> (complète RG-MCP-101) : tout objet qu&#39;un type peut cibler reçoit un <code>ref</code> à préfixe propre (catégorie, groupe de modificateurs, bon de commande, lot, magasin, appareil, table…), rendu par les outils de lecture dans le <strong>contenu structuré seulement</strong>. Un <code>ref</code> d&#39;un autre commerce, d&#39;un magasin hors de l&#39;accès ou d&#39;un type inattendu vaut « introuvable ».</li><li><strong>RG-MCP-130</strong> — <strong>Tests génériques du registre</strong> : pour <strong>chaque</strong> type inscrit, une même suite prouve — contenu immuable ; champ étranger refusé ; portée, module, famille et allumage exigés à la création ; péremption → <code>PROPOSAL_STALE</code> sans effet ; application au nom du validateur, audit <code>AGENT</code> puis validateur ; décision refusée à toute clé, à tout jeton et à une session déléguée ; isolation entre commerces et entre magasins ; lieu de décision respecté ; arrêt d&#39;urgence et interrupteurs respectés par le serveur <strong>et</strong> par le serveur MCP ; modules exigés à la route revérifiés. Un type sans cette suite fait échouer la construction.</li><li><strong>RG-MCP-131</strong> — <strong>Après la décision</strong> : chaque type fournit son texte de succès (« Prix appliqué », « Produit créé »), le lien <strong>interne</strong> vers l&#39;objet créé ou modifié (chemin du back-office, jamais une adresse absolue) et un <strong>texte propre aux caisses</strong>, sans lien (« Brouillon créé : à envoyer depuis le back-office »). Il déclare s&#39;il est <strong>réversible</strong> — l&#39;écran l&#39;annonce <strong>avant</strong> la validation pour un type non réversible. La réponse de validation peut porter un <strong>résultat montré une seule fois</strong> à celui qui valide (code d&#39;appairage, RG-MCP-126), jamais stocké dans la proposition ni dans son modèle d&#39;affichage : la place est réservée dans le contrat dès la version 1. L&#39;annulation elle-même est l&#39;objet du jalon 7 (VEN-57) : toujours une action inverse faite au nom de l&#39;humain qui annule, jamais un effacement.</li><li><strong>RG-MCP-132</strong> — <strong>Compatibilité</strong> : les propositions, les routes, les codes d&#39;erreur et les événements <code>AgentProposalRaised</code> / <code>AgentProposalDecided</code> du lot VEN-34 ne changent pas ; les ajouts sont des champs nouveaux. <code>GET /api/v1/api-keys/me</code> garde <code>proposalsEnabled</code> (vrai si l&#39;accès peut créer au moins un type) et ajoute <code>proposalTypes</code>. Un appareil d&#39;ancienne version tolère un type inconnu dans un événement ou une réponse (RG-MCP-121). Les tests du lot VEN-34 passent <strong>sans changer leurs attentes</strong>.</li><li><strong>RG-MCP-133</strong> — <strong>Disponibilité d&#39;un produit dans un magasin</strong> (<code>PRODUCT_AVAILABILITY</code>, famille <code>CATALOG</code>, premier type inscrit après le socle ; fiche <a href="./../lots/MCP-ECRITURE-DISPONIBILITE">lots/MCP-ECRITURE-DISPONIBILITE.md</a>, matrice ligne 7 ; avis <code>expert-fiscal</code> du 17/11/2026 : conforme avec réserves R1 → R5, reprises ici) : l&#39;assistant propose de rendre <strong>indisponible</strong> (rupture, « 86 ») ou de <strong>remettre en vente</strong> un ou plusieurs produits dans <strong>un</strong> magasin — jamais pour l&#39;entreprise entière (c&#39;est l&#39;archivage, autre type). Lecture exigée : <code>catalog:read</code> ; aucun module de formule ; risque <strong>faible</strong> ; <strong>réversible</strong> ; aucune saisie ni confirmation renforcée ; décision <strong>au back-office, sur la caisse et sur le téléphone de salle</strong> du magasin (PIN sur l&#39;appareil, RG-MCP-91, 113). <strong>Forme</strong> (RG-MCP-115 : champs du type dans <code>content</code>) : <code>storeId</code> obligatoire à la racine ; un produit : <code>content {product, available}</code> ; plusieurs : <code>content {available}</code> + <code>lines [{product}]</code> (<strong>20 lignes au plus, un seul sens pour toutes</strong>) ; <code>content.product</code> est refusé quand <code>lines</code> est présent, <code>available</code> est refusé dans une ligne. <code>product</code> est une <strong>chaîne</strong> (objet ou tableau refusé), <code>available</code> un <strong>booléen JSON strict</strong> (ni <code>&quot;false&quot;</code>, ni <code>0</code>, ni <code>null</code>). Tout autre champ est fermé (<code>FIELD_NOT_ALLOWED</code>, <code>VAT_NOT_ALLOWED</code>) : prix, TVA, retour à l&#39;héritage (<code>clear</code>), <code>scope</code>, et <strong><code>overrideVersion</code></strong> — la version attendue vient <strong>uniquement</strong> de l&#39;instantané relevé par le serveur. <strong>Refus à la création</strong> (violations) : produit introuvable ou propre à un autre magasin, ambigu, en double, <strong>archivé</strong> (<code>PRODUCT_ARCHIVED</code>), <strong>à variantes ou variante d&#39;un produit</strong> (<code>AVAILABILITY_VARIANT_NOT_SUPPORTED</code>, message propre au type : le retrait d&#39;un parent ne bloque pas le scan de ses variantes), ou <strong>déjà dans l&#39;état demandé</strong> (<code>AVAILABILITY_UNCHANGED</code>). Ce dernier refus vaut aussi quand une proposition <strong>inverse</strong> attend encore : la demande n&#39;est ni acceptée ni un remplacement, et le message dit qu&#39;une proposition inverse attend une décision et qu&#39;un responsable peut la refuser. L&#39;instantané relève, par produit, la version de la surcharge (absence comprise), sa disponibilité, son prix et sa TVA <strong>bruts</strong>. <strong>Périmée</strong> — et l&#39;écran dit laquelle de ces causes, dans cet ordre — si le magasin est archivé, si le produit est archivé, s&#39;il est devenu « à variantes », s&#39;il est déjà dans l&#39;état demandé, ou si la version de la surcharge a changé. <strong>Application</strong> : l&#39;écriture dédiée « disponibilité seule » de <code>StoreProductOverrideService</code> (RG-MCP-122), au nom du validateur. Elle prend le verrou commun, relit dans <strong>une même requête <code>FOR UPDATE</code></strong> la version, <code>sale_price_minor</code> et <code>vat_rate_permille</code> <strong>tels qu&#39;ils sont en base, <code>NULL</code> compris</strong>, compare la version à celle de l&#39;instantané et réécrit ces deux valeurs à l&#39;identique — jamais une valeur effective, une vue ni l&#39;instantané : une TVA héritée reste <code>NULL</code> et suit donc un changement de taux fait ensuite au niveau de l&#39;entreprise. Le type n&#39;appelle jamais l&#39;écriture complète, le retour à l&#39;héritage ni l&#39;écriture « prix seul ». L&#39;événement <code>StoreProductOverrideSet</code> émis et l&#39;audit de la surcharge sont <strong>ceux de l&#39;action humaine</strong> de la fiche produit (spec 14 RG-MSTORE-04) : les listes de vente des caisses, des téléphones de salle et des bornes, le scan et le menu en ligne suivent par les chemins existants. Une ligne déjà au panier d&#39;une caisse reste vendable tant que l&#39;app n&#39;est pas relancée ; à la restauration du panier elle est retirée et signalée (comportement existant, inchangé) ; un plat déjà envoyé en cuisine n&#39;est pas touché. L&#39;indisponibilité <strong>dure jusqu&#39;à ce qu&#39;un responsable remette le produit en vente</strong> : rien ne la lève à la fin du service, et l&#39;écran de décision le dit. Demande répétée : dédoublonnée (RG-MCP-119). <strong>Allumage (décision d&#39;Ahmed du 17/11/2026, question 5 de la fiche) :</strong> le type est fusionné éteint. Par exception à RG-MCP-110 (qui attend la revue de sécurité de la famille), ce seul type pourra être allumé sur le staging avant la revue de la famille Catalogue, <strong>sur accord explicite d&#39;Ahmed donné à la clôture du lot</strong> ; sans cet accord il reste éteint. Aucun allumage en production.</li><li><strong>RG-MCP-134</strong> — <em>(Remplacée par RG-MCP-137 depuis la livraison du lot MCP-ECRITURE-LIBELLES, le 18/11/2026.)</em><strong>Libellé d&#39;un type sur les écrans de réglage</strong> : les pages Réglages › Assistant IA (familles, clés) et de consentement OAuth nomment chaque type par une <strong>action en toutes lettres</strong> dans la langue de l&#39;écran (FR, EN, AR), jamais par son code. Un <strong>test du serveur</strong> — seul à connaître le registre — lit le fichier de libellés du back-office et échoue si un type inscrit n&#39;y a pas son libellé dans les trois langues. (Constat du cadrage de <code>PRODUCT_AVAILABILITY</code> : ces pages tiennent leur propre liste de libellés ; l&#39;écran de décision, lui, reçoit le sien du serveur, RG-MCP-120.)</li><li><strong>RG-MCP-135</strong> — <strong>Modifier la fiche d&#39;un produit</strong> (<code>PRODUCT_UPDATE</code>, famille <code>CATALOG</code> ; fiche <a href="./../lots/MCP-ECRITURE-PRODUIT-MODIFIER">lots/MCP-ECRITURE-PRODUIT-MODIFIER.md</a>, matrice ligne 5 ; avis <code>expert-fiscal</code> du 17/11/2026 : conforme avec réserves, reprises ici) : l&#39;assistant propose de changer, sur un produit <strong>existant, actif et sans variantes</strong>, un ou plusieurs de ces champs et <strong>eux seuls</strong> : nom, catégorie (ou « sans catégorie »), code-barres, coût d&#39;achat, suivi de stock, éligibilité titre-restaurant. Lecture exigée : <code>catalog:read</code> ; aucun module de formule ; risque <strong>moyen</strong> ; réversible ; décision <strong>au back-office seulement</strong> (RG-MCP-113) ; ni saisie ni confirmation renforcée. <strong>Forme</strong> (RG-MCP-115) : <code>content {product, name?, category?, clearCategory?, barcode?, purchasePriceMinor?, trackStock?, mealVoucherEligible?}</code>, valeurs de type strict (chaînes, entier ≥ 0, booléens JSON) ; nom de 120 caractères au plus ; coût d&#39;achat au plus le plafond des prix d&#39;une proposition. <code>storeId</code>, <code>lines</code> et <code>scope</code> ne sont pas des champs du type : le magasin de la proposition est celui d&#39;un produit propre à un magasin, sinon aucun. <strong>Accès limité à certains magasins</strong> : seuls les produits <strong>propres à un magasin de l&#39;accès</strong> sont résolus ; un produit de l&#39;entreprise lui est refusé (403 <code>API_KEY_STORE_RESTRICTED</code>), un produit propre à un autre magasin vaut « introuvable », et aucun message ne nomme un produit hors de l&#39;accès. <strong>Fermés</strong> : prix de vente (c&#39;est <code>PRICE_CHANGE</code>), tout champ de TVA (<code>VAT_NOT_ALLOWED</code>), <code>active</code> (c&#39;est <code>PRODUCT_ARCHIVE</code>), référence, poids, code balance, péremption, unité de stock, menu en ligne, allergènes, et <strong>toute version</strong> (<code>version</code>, <code>productVersion</code>) : la version attendue vient uniquement de l&#39;instantané du serveur. <strong>Coût d&#39;achat</strong> : en unités mineures de la devise <strong>du produit</strong> ; refusé (<code>COST_CURRENCY_AMBIGUOUS</code>) si cette devise n&#39;est pas l&#39;unique devise des magasins de l&#39;accès — le serveur MCP convertit selon cette même devise unique par la règle unique des montants (RG-MCP-128), jamais par une seconde règle côté serveur. <strong>Code-barres</strong> : contrôlé comme une saisie humaine, et en plus <strong>tout code entièrement numérique commençant par 20 à 29 est refusé</strong> (<code>BARCODE_RESERVED</code> : codes internes, étiquettes de balance au poids ou au prix, cartes de fidélité) — une étiquette déjà imprimée désigne toujours le même produit ; un code déjà porté par un autre produit est refusé (<code>BARCODE_TAKEN</code>). <strong>Autres refus à la création</strong> : produit introuvable, ambigu, archivé (<code>PRODUCT_ARCHIVED</code>, le message renvoie vers la remise en vente), à variantes ou variante (<code>PRODUCT_VARIANT_NOT_SUPPORTED</code>) ; catégorie introuvable ou ambiguë (candidats rendus, jamais de choix au hasard ; un identifiant d&#39;un autre commerce ou d&#39;un autre objet vaut « introuvable ») ; règle de profil violée (<code>PROFILE_RULE</code> : le suivi de péremption exige le suivi de stock) ; <strong>aucun écart</strong> avec la fiche actuelle (<code>NOTHING_TO_CHANGE</code>). Le contenu validé ne garde que les champs qui <strong>diffèrent</strong>, avec leur valeur d&#39;avant. <strong>Une seule proposition de modification en attente par produit</strong> : une seconde, même sur d&#39;autres champs, <strong>remplace</strong> la première (RG-MCP-88) — l&#39;assistant regroupe donc tous les changements d&#39;un produit en une demande. <strong>Périmée</strong> si le produit n&#39;existe plus, est archivé ou devenu « à variantes », si la catégorie visée a été supprimée, si le code-barres visé a été pris, ou si la version du produit a changé (toute modification, prix compris). <strong>Application</strong> : <code>CatalogService.patchProduct</code> au nom du validateur, avec <strong>toujours la version relevée</strong> et les seuls champs du contenu, écrits un à un — jamais le prix de vente, la TVA, <code>active</code>, ni les paramètres qui contournent le contrôle du magasin d&#39;origine ou la limite de produits ; l&#39;événement <code>ProductUpdated</code>, les magasins destinataires et les entrées d&#39;audit (<code>UPDATED</code>, et <code>PRICE_CHANGED</code> pour le coût d&#39;achat) sont ceux de l&#39;action humaine ; les surcharges des magasins ne sont pas touchées. Un validateur qui n&#39;est pas gérant du magasin d&#39;un produit propre à ce magasin ne voit pas la proposition (404), rien n&#39;est écrit et elle reste en attente (RG-MCP-89). L&#39;écran dit honnêtement ce que le changement entraîne : tickets et ventes déjà enregistrés gardent l&#39;ancien nom ; un coût d&#39;achat nouveau change les marges et la valeur du stock affichées à partir de maintenant ; un suivi de stock coupé retire le produit des alertes et du réassort ; l&#39;éligibilité titre-restaurant relève du commerçant, seuls certains produits alimentaires y ouvrant droit. <em>(Lot 4a, 19/11/2026 — RG-MCP-144 : au renommage, le nom est <strong>nettoyé avant</strong> la comparaison et l&#39;enregistrement — le nom stocké est le nom affiché — ; un caractère invisible, des guillemets ou un nom <strong>déjà pris</strong> sont refusés ; septième cause de péremption : nom pris entre-temps.)</em></li><li><strong>RG-MCP-136</strong> — <strong>Retirer un produit de la vente ou l&#39;y remettre</strong> (<code>PRODUCT_ARCHIVE</code>, famille <code>CATALOG</code> ; même fiche, matrice ligne 6) : <code>content {product, active}</code> (<code>active</code> booléen JSON strict : <code>false</code> retire le produit de la vente dans <strong>tous</strong> les magasins où il existe, <code>true</code> l&#39;y remet). Mêmes portée, lieu de décision, risque, accès limité, champs fermés et limites que RG-MCP-135 (produits sans variantes). Refus si le produit est <strong>déjà dans l&#39;état demandé</strong> (<code>ARCHIVE_UNCHANGED</code>) ; ce refus vaut aussi quand une proposition <strong>inverse</strong> attend encore, et le message dit alors qu&#39;elle attend une décision et qu&#39;un responsable peut la refuser. Réversible, jamais une suppression. <strong>Périmée</strong> si le produit n&#39;existe plus, s&#39;il est déjà dans l&#39;état demandé, ou si sa version a changé. <strong>Application</strong> : <code>CatalogService.patchProduct</code> avec <code>active</code> et la version relevée, rien d&#39;autre. Remettre en vente reprend une place dans la limite de produits de la formule : si elle est atteinte à la validation, le service refuse (409 <code>LIMIT_REACHED</code>), rien n&#39;est appliqué et la proposition <strong>reste en attente</strong> (RG-MCP-89). Un retrait ne touche aucune vente : une ligne déjà au panier reste vendable jusqu&#39;à la relance de l&#39;app (puis est retirée et signalée), une addition ouverte et une commande en ligne déjà payée qui contiennent le produit s&#39;encaissent et se scellent au taux d&#39;origine, et le retour d&#39;une vente passée reste possible. L&#39;écran dit que l&#39;effet touche tous les magasins, signale le stock qui reste, et distingue le retrait d&#39;une rupture du jour (RG-MCP-133).</li><li><strong>RG-MCP-137</strong> — <strong>Libellés des types fournis par le serveur</strong> (décision d&#39;Ahmed du 17/11/2026 ; lot préalable <a href="./../lots/MCP-ECRITURE-LIBELLES">lots/MCP-ECRITURE-LIBELLES.md</a> ; <strong>remplace RG-MCP-134</strong>) : chaque type du registre — type d&#39;essai compris — déclare son <strong>libellé d&#39;action</strong> en FR, EN et AR. Les deux réponses que le back-office lit pour lister des types — familles du commerce (<code>/api/v1/tenant/agent-proposal-families</code>) et vue de consentement OAuth — portent, à côté des codes inchangés (RG-MCP-132), ce libellé <strong>dans les trois langues à la fois</strong> : aucune de ces routes ne transporte la langue de l&#39;écran, et le back-office choisit. Le back-office n&#39;a plus de liste de libellés de types : il affiche celui du serveur (repli : français, puis le code, face à un serveur plus ancien). Un type sans libellé dans les trois langues fait échouer la construction ; ce test remplace celui de RG-MCP-134, qui lisait le fichier du back-office.</li></ul><h3 id="revue-de-securite-de-l-ecriture-ven-58-vague-1-du-18-11-2026" tabindex="-1">Revue de sécurité de l&#39;écriture (VEN-58, vague 1 du 18/11/2026) <a class="header-anchor" href="#revue-de-securite-de-l-ecriture-ven-58-vague-1-du-18-11-2026" aria-label="Permalink to &quot;Revue de sécurité de l&#39;écriture (VEN-58, vague 1 du 18/11/2026)&quot;">​</a></h3><p>Fiche <a href="./../lots/MCP-ECRITURE-SECURITE-V1">lots/MCP-ECRITURE-SECURITE-V1.md</a>, <strong>validée par Ahmed le 18/11/2026</strong> (dix recommandations retenues) ; rapport <a href="./../securite/MCP-ECRITURE-VAGUE-1">securite/MCP-ECRITURE-VAGUE-1.md</a>. Constat de départ : des <strong>manques de la garde</strong> du registre, sans effet sur les quatre types alors inscrits, fermés avant l&#39;ajout de types nouveaux.</p><ul><li><strong>RG-MCP-138</strong> — <strong>Garde par appels déclarés</strong> (précise RG-MCP-106, 107, 123) : chaque type déclare au registre les <strong>méthodes de service</strong> qu&#39;appellent sa préparation et son applicateur (<code>serviceCalls</code>). Le registre <strong>refuse au démarrage</strong> un type dont une déclaration vise la liste d&#39;exclusions ; un <strong>test lit le code compilé</strong> du type, de ses classes internes et des classes du paquet des propositions qu&#39;il appelle, et fait échouer la construction si un appel n&#39;est pas déclaré ou vise une classe, une méthode, un contexte, un dépôt de données ou une table exclus. Sont <strong>refusés à tout type</strong>, même déclarés : les contextes qui changent qui agit ou dans quel commerce (<code>ActingAs</code>, <code>TenantContext</code>, <code>StoreScopeContext</code>, <code>ApiKeyContext</code>) et le contexte de sécurité ; les <strong>dépôts de données</strong> (accès direct aux tables d&#39;un autre domaine) ; la <strong>réflexion</strong> et toute source de données ; l&#39;<strong>héritage</strong> d&#39;un autre type ou la <strong>délégation</strong> à un autre type ; la <strong>fabrication ou la copie d&#39;un utilisateur</strong> ; tout <strong>composant dont le code écrit une table exclue</strong> (jugé par classe). <strong>Aucun applicateur n&#39;écrit en SQL</strong> : toute écriture directe (quelle qu&#39;en soit la forme : minuscules, requête dans une variable ou assemblée) fait échouer la garde, et RG-MCP-123 vaut sans exception. Le <strong>seul</strong> moyen d&#39;agir au nom du validateur est <code>ApplyContext.asValidator { … }</code>, qui pose un <strong>contexte de sécurité neuf</strong> pour le seul bloc ; l&#39;argument utilisateur passé à un service est <strong>toujours <code>ctx.validator</code></strong> (test de source sur les types réels). La garde voit la méthode appelée, <strong>jamais ses arguments</strong> : tout type qui appelle <code>CatalogService.patchProduct</code> ou <code>StoreProductOverrideService.setPriceOnly</code> a <strong>obligatoirement</strong> un test de source qui prouve qu&#39;il n&#39;y passe aucun champ fermé (<code>vatRatePermille</code>…), comme celui de la disponibilité pour <code>set</code> / <code>clear</code> (réserve fiscale R4 de l&#39;avis du 18/11/2026) ; la tranche légère de RG-MCP-139 n&#39;en dispense pas. Limites écrites au rapport : un composant appelé par un composant autorisé n&#39;est pas suivi ; une table construite à l&#39;exécution n&#39;est pas lisible (seul l&#39;appel d&#39;écriture est refusé) ; une classe sans stéréotype hors du paquet des propositions n&#39;est pas contrôlée — la relecture humaine de chaque type reste due. <em>(Lot VEN-49 création : la <strong>lecture</strong> SQL dans un type est permise — la garde ne refuse que les écritures, les dépôts de données et les classes exclues ; <code>PRODUCT_CREATE</code> lit ainsi <code>tax_rates</code> sans passer par <code>TaxRateRepository</code>, exclu et dont la lecture ensemence la table. Il appelle <code>CatalogService.createProduct</code>, couvert par son test de source.)</em></li><li><strong>RG-MCP-139</strong> — <strong>Revue de sécurité par famille et par type</strong> (précise RG-MCP-110, 130 ; ne change pas RG-MCP-111) : allumer une <strong>famille</strong> sur le staging exige un <strong>rapport par vague</strong> dans <code>docs/securite/</code>, qui liste chaque attaque essayée, son vecteur, la preuve (nom du test ou de la question d&#39;évaluation) et son résultat, l&#39;avis <code>expert-fiscal</code> sur le registre et une relecture <code>revue-code</code> dédiée, <strong>sans défaut bloquant ouvert</strong>. Un type <strong>ajouté à une famille déjà revue</strong> passe une <strong>tranche légère</strong> — suite générique et garde vertes, test de source des arguments (RG-MCP-138), relecture <code>revue-code</code> et avis <code>expert-fiscal</code> de son lot, une ligne ajoutée au rapport de la famille — qui <strong>ne remplace pas</strong> la revue de famille : une famille qui n&#39;a pas eu sa vague n&#39;est pas allumée par une tranche. <strong>Exception</strong> : un type qui choisit ou écrit une TVA (<code>PRODUCT_CREATE</code>, <code>CATALOG_IMPORT</code>) garde une <strong>revue complète avec avis fiscal</strong>, même dans une famille revue. État au 18/11/2026 : la vague 1 a revu <code>CATALOG</code> (types existants : <code>PRICE_CHANGE</code>, <code>PRODUCT_AVAILABILITY</code>) et <code>FRAUD</code> (un seul type, aucun prévu) ; <code>PURCHASES</code> n&#39;est revue que pour <code>PURCHASE_ORDER</code> et garde sa revue complète en vague 2 avec les types de VEN-53, avec <code>STOCK</code> ; <code>RESTAURANT</code>, <code>SETTINGS</code>, <code>DEVICES</code>, <code>CUSTOMERS</code> ont leurs vagues 3 et 4. Un <strong>défaut bloquant</strong> trouvé sur un type déjà allumé le fait <strong>éteindre sur le staging par le chef de lot</strong> (retrait de <code>POS_AGENT_PROPOSALS_TYPES</code>), qui prévient Ahmed ; les propositions en attente restent décidables. La course du prix groupé est un critère obligatoire du lot VEN-51 (RG-MCP-122).</li></ul><h3 id="creer-un-produit-ven-49-lot-3-du-19-11-2026" tabindex="-1">Créer un produit (VEN-49, lot 3 du 19/11/2026) <a class="header-anchor" href="#creer-un-produit-ven-49-lot-3-du-19-11-2026" aria-label="Permalink to &quot;Créer un produit (VEN-49, lot 3 du 19/11/2026)&quot;">​</a></h3><p>Fiche <a href="./../lots/MCP-ECRITURE-PRODUIT-CREER">lots/MCP-ECRITURE-PRODUIT-CREER.md</a>, <strong>validée par Ahmed le 19/11/2026</strong> (quatorze recommandations retenues), livrée <strong>éteinte</strong> ; revue complète exigée par RG-MCP-139 : <a href="./../securite/MCP-ECRITURE-PRODUIT-CREER">securite/MCP-ECRITURE-PRODUIT-CREER.md</a> ; matrice ligne 4.</p><ul><li><strong>RG-MCP-140</strong> — <strong>Créer un produit</strong> (<code>PRODUCT_CREATE</code>, famille <code>CATALOG</code>) : l&#39;assistant propose un produit <strong>sans variantes</strong>, ni vendu au poids, ni suivi en péremption. Lecture exigée : <code>catalog:read</code> ; aucun module ; risque <strong>élevé</strong> ; réversible (retrait de la vente) ; décision <strong>au back-office seulement</strong> (RG-MCP-113) ; confirmation renforcée <strong>toujours</strong>. <strong>Forme</strong> (RG-MCP-115) : <code>storeId</code> facultatif à la racine (produit propre à ce magasin, sinon produit de l&#39;entreprise) ; <code>content {name, category?, salePriceMinor, vatRatePermille?, barcode?, purchasePriceMinor?, trackStock?}</code>, types stricts ; prix de vente de 1 au plafond des prix d&#39;une proposition, coût d&#39;achat de 0 au même plafond ; suivi de stock absent = oui (défaut de l&#39;action humaine). Tout autre champ est fermé, dont <code>active</code>, <code>id</code>, <code>scope</code>, <code>currencyCode</code>, l&#39;éligibilité titre-restaurant, la référence, le poids, la péremption, le menu en ligne et les allergènes ; pour ce type seul, <code>vatRatePermille</code> est ouvert dans <code>content</code> (les autres noms de TVA restent refusés). <strong>Devise</strong> : jamais reçue — celle du magasin d&#39;un produit propre, sinon l&#39;unique devise des magasins de l&#39;accès (<code>PRICE_CURRENCY_AMBIGUOUS</code> sinon) ; figée dans le contenu et toujours passée à l&#39;action humaine. <strong>Accès limité à des magasins</strong> : <code>storeId</code> obligatoire et pris dans l&#39;accès, sinon 403 <code>API_KEY_STORE_RESTRICTED</code> ; un magasin archivé ou hors de l&#39;accès reçoit la réponse du socle. <strong>Nom</strong> : 1 à 120 caractères ; refusé (<code>NAME_INVALID</code>) s&#39;il contient un caractère <strong>invisible</strong> (catégorie Unicode <code>Cf</code>, hors marques de direction) ou des <strong>guillemets</strong> (<code>«</code>, <code>»</code>, <code>“</code>, <code>”</code>, <code>&quot;</code>, <code>‹</code>, <code>›</code>, <code>„</code>, <code>‚</code>, <code>＂</code> ; les apostrophes restent permises), qui fabriqueraient une fausse phrase dans la case et le résumé <em>(liste étendue aux guillemets simples, bas et pleine chasse au lot 4a, 19/11/2026)</em>. <strong>Nom déjà pris</strong> : refusé (<code>PRODUCT_EXISTS</code>, produit en candidat, actif ou retiré de la vente) ; le conflit est jugé sur <strong>la portée de la proposition</strong> — proposition d&#39;un magasin : produits de l&#39;entreprise et produits propres à ce magasin ; proposition de l&#39;entreprise : tout le commerce —, par l&#39;unique fonction de normalisation de la clé de cible, les caractères invisibles des noms déjà en base étant ignorés ; même règle à la création et à la péremption. <strong>Catégorie</strong> et <strong>code-barres</strong> : mêmes règles que RG-MCP-135 (candidats sans choix au hasard ; codes en 20 à 29 refusés ; code déjà porté refusé). <strong>Taux</strong> : RG-MCP-125 et 141 ; référentiel sans taux actif → <code>VAT_RATES_EMPTY</code>, prioritaire ; 0 % nommé → <code>VAT_RATE_ZERO_NOT_ALLOWED</code> ; taux nommé absent ou inactif → <code>VAT_RATE_NOT_FOUND</code>, taux actifs en candidats. <strong>Avertissement</strong> : si un taux <strong>nommé</strong> diffère du taux porté par <strong>plus de la moitié</strong> des produits actifs, hors variantes, de la catégorie, l&#39;écran le dit (« Les autres produits de « … » sont majoritairement à … ») ; jamais pour un taux à choisir. <strong>Identité</strong> : rien d&#39;aléatoire dans le contenu ; l&#39;identifiant du produit créé est <strong>celui de la proposition</strong> ; clé de cible <code>PRODUCT_CREATE:&lt;magasin ou *&gt;:&lt;nom normalisé&gt;</code> calculée par le service, <code>target_id</code> = identifiant de la proposition (RG-MCP-117) ; même nom, autre contenu : remplacement ; contenu identique : demande dédoublonnée (RG-MCP-119). Un type peut <strong>lire</strong> en SQL ; seules les écritures, les dépôts de données et les classes exclues lui sont refusés (RG-MCP-123, 138). <strong>Périmée</strong>, dans cet ordre : magasin d&#39;origine archivé, taux nommé désactivé, catégorie supprimée, code-barres pris, nom pris, produit déjà créé. <strong>Application</strong> : un seul appel de <code>CatalogService.createProduct</code> au nom du validateur, un argument par champ, l&#39;identifiant de la proposition, la devise du contenu, le taux du contenu sinon celui du validateur — jamais la limite de produits levée ni un champ fermé. La <strong>limite de produits</strong> (409 <code>LIMIT_REACHED</code>), un <strong>taux absent du référentiel</strong> (422, reconnu en relisant le référentiel) et un <strong>refus de rôle</strong> laissent la proposition <strong>en attente</strong>, rien d&#39;écrit ; un conflit de code-barres ou d&#39;identifiant et tout autre 422 la rendent <strong>périmée</strong>. <code>ProductCreated</code>, ses magasins destinataires et l&#39;audit <code>CREATED</code> sont ceux de l&#39;action humaine ; le produit arrive sur les caisses par la synchronisation habituelle. L&#39;écran montre la portée (magasin ou « Tous les magasins ») et la devise au-dessus du choix, et dit honnêtement : prix TTC, taux non modifiable ensuite par l&#39;assistant, place prise dans la limite de produits, taux nommé à vérifier ; quand 0 % figure parmi les options, qu&#39;il ne convient qu&#39;aux produits exonérés par la loi (et, pour un magasin tunisien, qu&#39;une vente en suspension de taxes se déclare sur la vente, pas sur le produit).</li><li><strong>RG-MCP-141</strong> — <strong>Taux de TVA d&#39;une création : affichage, choix du validateur, trace</strong> (précise RG-MCP-114 et 125) : partout où un taux est affiché — options, ligne TVA, case de confirmation, phrase de péremption, candidats d&#39;un refus —, il s&#39;écrit <strong>« nom du référentiel au moment de l&#39;affichage — pourcentage »</strong>. <strong>Le pourcentage affiché est toujours calculé depuis la valeur du taux ; le nom du taux n&#39;est qu&#39;un libellé.</strong> Un taux <strong>nommé</strong> par l&#39;assistant est affiché et couvert par la case ; il n&#39;est <strong>pas remplaçable</strong> à la validation (une saisie reçue est ignorée) : pour en changer, le responsable refuse. Sans taux nommé, la ligne TVA dit « À choisir par le responsable au back-office » et la décision porte une saisie <strong>choix</strong> obligatoire : options = taux actifs au moment de l&#39;affichage, ordre du référentiel, <strong>aucune présélection, aucune mention du taux par défaut</strong>, valeur = taux en pour mille ; le serveur recalcule les options à la validation (option devenue inactive → 422 <code>VALIDATOR_INPUT_REQUIRED</code>, proposition en attente). Jamais de repli sur le taux par défaut, jamais 0 % nommé par l&#39;assistant (le validateur peut le choisir). La saisie n&#39;est rendue que tant que la proposition est en attente. <strong>Trace</strong> : l&#39;origine du taux se lit dans le contenu immuable (taux présent : nommé par l&#39;assistant ; absent : choisi par le responsable), la valeur appliquée dans l&#39;audit <code>CREATED</code> du produit, qui porte l&#39;identifiant de la proposition ; après application, l&#39;écran dit « Taux choisi par le responsable » ou « Taux nommé par l&#39;assistant, confirmé par le responsable ». La case d&#39;un taux à choisir garde un texte fixe (« … au taux de TVA que j&#39;ai choisi ci-dessus ») ; citer l&#39;option choisie demande un lot d&#39;écran à part.</li></ul><h3 id="acces-limite-et-renommage-ven-49-lot-4a-du-19-11-2026" tabindex="-1">Accès limité et renommage (VEN-49, lot 4a du 19/11/2026) <a class="header-anchor" href="#acces-limite-et-renommage-ven-49-lot-4a-du-19-11-2026" aria-label="Permalink to &quot;Accès limité et renommage (VEN-49, lot 4a du 19/11/2026)&quot;">​</a></h3><p>Fiche <a href="./../lots/MCP-LECTURE-ACCES-LIMITE">lots/MCP-LECTURE-ACCES-LIMITE.md</a>, <strong>validée par Ahmed le 19/11/2026</strong> (sept recommandations retenues), livrée le 19/11/2026 (<code>c6099fff</code>). Correctif d&#39;un défaut <strong>en ligne sur le staging depuis le 11/11/2026</strong> (lot M0, V99) : un accès limité à des magasins lisait les produits propres aux autres magasins. <em>RG-MCP-142 : lot 4b, section suivante.</em></p><ul><li><strong>RG-MCP-143</strong> — <strong>Portée de magasins d&#39;un accès limité : produits propres à un magasin</strong> (portée par RG-MCP-03 et spec 14 RG-MSTORE-03) : pour une clé d&#39;API ou une connexion OAuth limitée à des magasins, un produit propre à un magasin hors de l&#39;accès — avec ses variantes, ses images, sa formule, sa recette, ses prix fournisseurs et son historique de prix d&#39;achat — <strong>n&#39;existe pas</strong> : absent des listes et de l&#39;export, et toute route qui le désigne répond le <strong>même 404</strong> qu&#39;un identifiant inexistant ; aucun nom de magasin caché n&#39;apparaît. <strong>Deux barrières</strong> : (1) en base, politique <code>store_scope</code> sur <code>products</code> (<code>origin_store_id</code> vide ou dans la portée), et sur chaque table qui suit un produit (<code>product_images</code>, <code>combos</code>, <code>recipes</code>, <code>supplier_products</code>, <code>purchase_price_history</code> : visibles si le produit l&#39;est) ; même règle pour <code>customers.created_store_id</code> (défense en profondeur) ; (2) dans le service, le dépôt du catalogue écarte ces produits (liste, fiche). Sans restriction de magasins (session humaine, clé complète, appareil, console) : rien ne change. <strong>Test de schéma</strong> : toute table sous RLS dont une colonne finit par <code>_store_id</code>, ou qui désigne un produit, porte une politique <code>store_scope</code> (citant cette colonne), sinon la construction échoue. <strong>Seule exception, bornée</strong> : le contrôle d&#39;existence d&#39;un code-barres (unique <strong>par commerce</strong>) — fonction <code>app_barcode_exists</code>, qui ne rend qu&#39;un booléen, lit le commerce dans le contexte et ne lève que la restriction de magasins pour sa propre durée — afin qu&#39;une proposition d&#39;un accès limité qui reprendrait le code d&#39;un produit caché soit refusée (<code>BARCODE_TAKEN</code>, <strong>sans nom</strong>) au lieu de n&#39;être jamais validable. <strong>Contextes de requête</strong> : chaque filtre d&#39;authentification (clé et connexion, session, appareil, console) vide le commerce, la clé et la portée de magasins du fil à l&#39;entrée et à la sortie de la requête, quoi qu&#39;il arrive : un fil réutilisé ne porte jamais le contexte d&#39;une requête précédente.</li><li><strong>RG-MCP-144</strong> — <strong>Nom proposé par un renommage</strong> (précise RG-MCP-135, reprend les refus de RG-MCP-140) : le nom proposé par <code>PRODUCT_UPDATE</code> est <strong>nettoyé</strong> (marques de direction et caractères de contrôle retirés, espaces Unicode repliés) <strong>avant</strong> la comparaison avec la fiche, le contenu et l&#39;appel du service : le nom stocké est exactement le nom affiché. Refus <code>NAME_INVALID</code> : nom vide après nettoyage, plus de 120 caractères, caractère <strong>invisible</strong> (catégorie <code>Cf</code> hors marques de direction), <strong>guillemets</strong> (liste de RG-MCP-140). Refus <code>PRODUCT_EXISTS</code> (candidats : <code>ref</code>, nom, actif ou non) si le nouveau nom est <strong>déjà pris</strong> par un autre produit, actif ou retiré, avec <strong>la même portée que la création</strong> (produit propre à un magasin : produits de l&#39;entreprise et propres à ce magasin ; produit de l&#39;entreprise : tout le commerce), le produit renommé exclu (changer la casse de son propre nom reste possible). <strong>Septième cause de péremption</strong>, après la version : nom pris entre la proposition et la validation (« Un produit « {nom} » existe désormais. »). Le serveur MCP refuse avant l&#39;appel les invisibles et les guillemets pour <code>update</code> comme pour <code>create</code>.</li></ul><h3 id="lectures-de-l-assistant-avant-de-proposer-ven-49-lot-4b-du-19-11-2026" tabindex="-1">Lectures de l&#39;assistant avant de proposer (VEN-49, lot 4b du 19/11/2026) <a class="header-anchor" href="#lectures-de-l-assistant-avant-de-proposer-ven-49-lot-4b-du-19-11-2026" aria-label="Permalink to &quot;Lectures de l&#39;assistant avant de proposer (VEN-49, lot 4b du 19/11/2026)&quot;">​</a></h3><p>Fiche <a href="./../lots/MCP-ECRITURE-PRODUIT-LIRE">lots/MCP-ECRITURE-PRODUIT-LIRE.md</a>, <strong>validée par Ahmed le 19/11/2026</strong>, livrée le 19/11/2026 (<code>a9d51e76</code>), module <code>mcp/</code> seul : aucune route ni champ nouveau du serveur.</p><ul><li><strong>RG-MCP-142</strong> — <strong>Ce que l&#39;assistant lit avant de proposer</strong> (précise RG-MCP-13, 14, 16 ; s&#39;appuie sur RG-MCP-143) : <ol><li><strong>Fiche d&#39;un produit</strong> (<code>find_product</code>) : en plus des champs existants, la <strong>catégorie</strong> (nom et <code>ref</code> <code>cat_…</code>), la <strong>portée</strong> — « entreprise », ou propre à un magasin, nommé <strong>seulement s&#39;il est dans l&#39;accès</strong> (le nom vient de la liste des magasins de l&#39;accès, jamais du nom d&#39;origine envoyé par le serveur) —, les <strong>variantes</strong> (produit à variantes, variante de tel parent avec son libellé), l&#39;éligibilité aux <strong>titres-restaurant</strong>, et, par magasin de l&#39;accès, les <strong>ruptures</strong> et les <strong>prix modifiés</strong> (surcharges en vigueur). Ces faits par magasin exigent la lecture des magasins et ne sont lus que pour <strong>6 magasins au plus</strong> ; la lecture s&#39;<strong>arrête au premier échec</strong> (dont un refus de débit) et un <strong>échec partiel ne rend aucun fait par magasin</strong> (jamais une liste incomplète présentée comme complète) : un avertissement le dit dans chacun de ces cas. Un produit retiré de la vente reste rendu (inactif).</li><li><strong>Outil <code>catalog_reference</code></strong> (« Catégories et taux de TVA », portée <code>catalog:read</code>, sans paramètre, lecture seule — la lecture des taux par un assistant n&#39;écrit jamais, RG-MCP-01) : catégories (nom, <code>ref</code>, parent, nombre de produits ; 100 au plus, avertissement au-delà) et <strong>taux actifs seulement</strong>, chacun écrit « nom — pourcentage », le pourcentage <strong>calculé depuis la valeur</strong> (règle de RG-MCP-141), le nom cité <strong>entre guillemets</strong> comme une donnée ; <strong>jamais</strong> un taux inactif ni la marque « par défaut » (RG-MCP-125) ; une note fixe rappelle que le taux d&#39;un nouveau produit n&#39;est donné que si l&#39;utilisateur l&#39;a dit. <strong>Liste de taux vide</strong> (commerce ancien jamais ouvert au back-office) : « Le référentiel des taux n&#39;est pas encore ouvert : il sera créé à la première ouverture du back-office. Cela ne veut pas dire que les produits sont sans TVA. » (FR, EN, AR).</li><li><strong>Date du jour</strong> : <code>list_stores</code> rend, pour chaque magasin, la <strong>date et l&#39;heure du jour dans son fuseau</strong> (<code>today</code>, <code>localTime</code>, et la ligne de texte) ; le refus d&#39;une <strong>période future</strong> ajoute « (aujourd&#39;hui : {date}) ».</li><li><strong>Inventaire des outils de lecture (14)</strong> : <code>list_stores</code>, <code>sales_summary</code>, <code>top_products</code>, <code>margin_analysis</code>, <code>stock_status</code>, <code>reorder_suggestions</code>, <code>cash_control</code>, <code>voided_sales</code>, <code>purchasing_status</code>, <code>devices_health</code>, <code>compare_stores</code>, <code>find_product</code>, <code>catalog_reference</code>, <code>fraud_alerts</code> — plus l&#39;aide <code>vendora_help</code> (sans portée) et les outils de proposition (RG-MCP-128). Les consignes du serveur ne changent pas ; deux descriptions orientent le modèle (date du jour dans <code>list_stores</code> ; le paramètre <code>category</code> de <code>propose_product</code> renvoie à <code>catalog_reference</code>). Sous un accès limité, tout ce qui est lu suit RG-MCP-143 : rien d&#39;un produit propre à un magasin hors de l&#39;accès.</li></ol></li></ul><h3 id="etendre-un-produit-a-tous-les-magasins-ven-49-lot-5-du-20-11-2026" tabindex="-1">Étendre un produit à tous les magasins (VEN-49, lot 5 du 20/11/2026) <a class="header-anchor" href="#etendre-un-produit-a-tous-les-magasins-ven-49-lot-5-du-20-11-2026" aria-label="Permalink to &quot;Étendre un produit à tous les magasins (VEN-49, lot 5 du 20/11/2026)&quot;">​</a></h3><p>Fiche <a href="./../lots/MCP-ECRITURE-PRODUIT-ETENDRE">lots/MCP-ECRITURE-PRODUIT-ETENDRE.md</a>, <strong>validée par Ahmed le 19/11/2026</strong>, livrée <strong>éteinte</strong> le 20/11/2026 (<code>93a23d61</code>) ; règle du geste humain : spec 14 RG-MSTORE-19.</p><ul><li><strong>RG-MCP-145</strong> — <strong>Étendre un produit à tous les magasins</strong> (<code>PRODUCT_PROMOTE</code>, famille <code>CATALOG</code>, lecture <code>catalog:read</code>, aucun module ; <strong>déroge à RG-MCP-91</strong>) : l&#39;assistant propose de rendre un produit <strong>propre à un magasin</strong> disponible dans <strong>tous</strong> les magasins — choix <strong>définitif</strong>. Forme : <code>content {product}</code> seulement (<code>ref</code>, UUID, code-barres ou nom) ; tout autre champ fermé. <strong>Accès complet seulement</strong> : un accès limité est refusé (403 <code>API_KEY_STORE_RESTRICTED</code>) avant toute lecture, même pour un produit de son magasin. Magasin de la proposition = magasin d&#39;origine ; clé de cible <code>PRODUCT_PROMOTE:&lt;magasin d&#39;origine&gt;:&lt;produit&gt;</code>. <strong>Refus à la création</strong> : produit déjà de l&#39;entreprise (<code>PRODUCT_ALREADY_SHARED</code>), retiré de la vente (<code>PRODUCT_ARCHIVED</code>, renvoi à la remise en vente), à variantes ou variante (<code>PRODUCT_VARIANT_NOT_SUPPORTED</code>), magasin actif d&#39;une autre devise (<code>PROMOTE_CURRENCY_MISMATCH</code>) ou d&#39;un autre pays fiscal (<code>PROMOTE_COUNTRY_MISMATCH</code>) — mêmes règles que le geste humain (RG-MSTORE-19), violations portant les champs structurés <code>stores</code> (5 noms au plus), <code>storeCount</code> et, pour le pays, <code>originStore</code> —, nom déjà porté par un <strong>produit de l&#39;entreprise</strong> (<code>PRODUCT_EXISTS</code>, candidats). Un homonyme <strong>propre à d&#39;autres magasins</strong> n&#39;est qu&#39;un <strong>avertissement</strong> qui nomme ces magasins. <strong>Décision</strong> au back-office seulement, <strong>case de confirmation imposée par le serveur</strong> (« … ; ce choix est définitif »). <strong>Validation réservée au propriétaire ou à un administrateur</strong>, imposée par le service : un gérant reçoit 403, rien n&#39;est écrit, aucun événement de décision, la proposition reste en attente (RG-MCP-89). <strong>Péremption</strong>, dans cet ordre : produit absent ; déjà de l&#39;entreprise ; retiré de la vente ; devenu à variantes ; devise ou pays fiscal d&#39;un magasin actif ; nom pris par un produit de l&#39;entreprise ; version changée. La promotion change la version : toute proposition en attente sur le même produit devient <strong>périmée</strong> à sa validation. <strong>Application</strong> : un appel de <code>CatalogService.promoteProduct</code> au nom du validateur avec la <strong>version relevée</strong> ; refus de conflit, d&#39;absence ou 422 → périmée. <strong>Écran</strong> : prix et taux de TVA <strong>de la fiche</strong> (ceux que reçoivent les autres magasins) ; si le magasin d&#39;origine a un taux propre, une note le dit ; notes permanentes : choix définitif, produit au prix et au taux de la fiche dans tous les magasins, stock resté au magasin d&#39;origine, <strong>ventes déjà enregistrées inchangées</strong>, validation réservée ; note du menu en ligne si le produit y est publié. <strong>Garde</strong> (complément de RG-MCP-138) : le corps des <strong>objets connus</strong> appelés par un type (<code>PromotionRules</code>…) est relu avec les mêmes règles (appels exclus, écritures, contextes, réflexion) ; seuls des appels purs nommés vers un paquet exclu y sont admis (<code>FiscalCountries.ofCurrency</code>).</li></ul><h3 id="changer-le-prix-de-plusieurs-produits-ven-51-livre-eteint-le-20-11-2026" tabindex="-1">Changer le prix de plusieurs produits (VEN-51, livré éteint le 20/11/2026) <a class="header-anchor" href="#changer-le-prix-de-plusieurs-produits-ven-51-livre-eteint-le-20-11-2026" aria-label="Permalink to &quot;Changer le prix de plusieurs produits (VEN-51, livré éteint le 20/11/2026)&quot;">​</a></h3><p>Fiche <a href="./../lots/MCP-ECRITURE-PRIX-GROUPE">lots/MCP-ECRITURE-PRIX-GROUPE.md</a>, <strong>validée par délégation d&#39;Ahmed le 19/11/2026</strong>, livrée <strong>éteinte</strong> le 20/11/2026 (<code>8c45a025</code>) ; avis <code>expert-fiscal</code> : conforme sous réserves (revente à perte : avis d&#39;un juriste avant toute production, France et Tunisie).</p><ul><li><strong>RG-MCP-146</strong> — <strong>Prix groupé : forme groupée de <code>PRICE_CHANGE</code></strong> (famille <code>CATALOG</code>, lecture <code>catalog:read</code> ; précise RG-MCP-93, 110, 116, 117 et 119) : <ol><li><strong>Allumage par jeton de forme</strong> : la forme groupée s&#39;allume par le jeton <code>PRICE_CHANGE_GROUP</code> de <code>POS_AGENT_PROPOSALS_TYPES</code>, <strong>seulement avec</strong> <code>PRICE_CHANGE</code> (le jeton seul n&#39;allume rien) ; absent du défaut. Forme éteinte : la création d&#39;un groupe répond <strong>404</strong> (rien d&#39;écrit) alors que le prix simple reste accepté ; <code>proposalTypes</code> cite le jeton après les codes de types, seulement s&#39;il est allumé.</li><li><strong>Forme</strong> : un corps est groupé s&#39;il porte <code>lines</code> <strong>sans</strong> <code>product</code> ni <code>newPriceMinor</code> à la racine ; un corps qui porte l&#39;un d&#39;eux reste un <strong>prix simple</strong>, inchangé, qui refuse <code>lines</code> et <code>content</code> (<code>FIELD_NOT_ALLOWED</code>). <strong>1 à 100 lignes</strong> (<code>NO_LINES</code>, <code>TOO_MANY_LINES</code>). Trois modes, jamais mêlés : <strong>absolu</strong> (<code>lines [{product, newPriceMinor}]</code>), <strong>montant commun</strong> (<code>content.changeMinor</code>, entier signé non nul, |valeur| ≤ <code>MAX_PRICE_MINOR</code>) ou <strong>pourcentage commun</strong> (<code>content.changePercentTenths</code>, entier non nul de −900 à +1 000 dixièmes, −90 % à +100 %), avec <code>lines [{product}]</code>. Le serveur ne reçoit <strong>jamais</strong> une catégorie : l&#39;assistant envoie un produit par ligne. Champs fermés et nommés aux trois emplacements (racine, <code>content</code>, ligne) : <code>scope</code>, <code>version</code>, <code>productVersion</code>, <code>overrideVersion</code>, <code>available</code>, <code>currencyCode</code>, <code>rounding</code>, <code>category</code>, <code>categoryId</code>, tout champ de TVA (<code>VAT_NOT_ALLOWED</code>).</li><li><strong>Calcul</strong> (relatif) : sur le prix <strong>en vigueur</strong> de chaque ligne (surcharge du magasin comprise), en <strong>entiers</strong> exacts, jamais de flottant : montant = <code>prix + changement</code> ; pourcentage = <code>prix × (1 000 + dixièmes) / 1 000</code>, arrondi à l&#39;unité mineure <strong>au plus proche, la moitié s&#39;éloignant de zéro</strong> (−5 % sur 2,10 € = 1,995 → 2,00 € ; 2,0475 € → 2,05 €), sans arrondi commercial ; un dépassement d&#39;entier vaut <code>PRICE_TOO_LARGE</code>.</li><li><strong>Refus, tout ou rien</strong> : 422 <code>PROPOSAL_INVALID</code>, rien d&#39;écrit, chaque refus de ligne porté par son rang (<code>field</code> = <code>lines[i].product</code>) : <code>PRICE_LINES_INVALID</code> (produit absent ou non chaîne, prix absent en absolu ou présent en relatif, deux changements communs), <code>PRICE_CHANGE_INVALID</code> (changement commun nul, non entier ou hors borne), <code>PRODUCT_NOT_FOUND</code>, <code>PRODUCT_AMBIGUOUS</code> (candidats), <code>DUPLICATE_PRODUCT</code>, <code>PRODUCT_HAS_VARIANTS</code> (produit à variantes <strong>ou variante d&#39;un produit</strong>, texte propre — le prix simple, lui, accepte la variante), <code>PRODUCT_STORE_SCOPED</code>, <code>PRICE_NOT_POSITIVE</code>, <code>PRICE_TOO_LARGE</code>, <code>PRICE_UNCHANGED</code> (prix donné ou calculé), <code>PRICE_CURRENCY_MIXED</code>, <code>PRICE_CURRENCY_MISMATCH</code> (champs <code>stores</code>, 5 noms au plus, et <code>storeCount</code>).</li><li><strong>Portée, une par proposition</strong> : <code>storeId</code> → surcharges de ce magasin (produits de l&#39;entreprise et produits propres à ce magasin), dans la devise du magasin ; sans <code>storeId</code> → prix de la fiche, <strong>une seule devise</strong> pour les lignes (<code>PRICE_CURRENCY_MIXED</code>) et aucun magasin non archivé d&#39;une autre devise (<code>PRICE_CURRENCY_MISMATCH</code>, esprit de RG-MSTORE-19) ; un produit propre à un magasin y est refusé (<code>PRODUCT_STORE_SCOPED</code>). <strong>Accès limité</strong> : sans <code>storeId</code> → 403 <code>API_KEY_STORE_RESTRICTED</code> ; un produit propre à un autre magasin → introuvable, sans nom (RG-MCP-143).</li><li><strong>Clé, remplacement, quotas</strong> : une ligne seule suit la clé du prix simple ; deux ou plus → clé <code>GROUP</code>, remplacement des prix simples en attente sur ces produits (RG-MCP-117) ; une groupée compte pour une (RG-MCP-118) ; une demande identique remplace (comportement de VEN-34 gardé, RG-MCP-119). Notification des caisses : <code>targetName</code> « N produits », <code>lineCount</code> N, <code>amountMinor</code> nul — jamais un faux « X → Y ».</li><li><strong>Décision</strong> : la <strong>case de confirmation est imposée par le serveur dès 2 lignes</strong> (<code>beforeApprove</code>, 422 <code>CONFIRMATION_REQUIRED</code>, au back-office comme sur la caisse) ; une ligne seule et le prix simple n&#39;ont aucune case imposée (l&#39;écran l&#39;affiche au-delà de 30 %). Groupe d&#39;un magasin : back-office et caisse / téléphone de salle du magasin sous PIN ; groupe de l&#39;entreprise : <strong>back-office seul</strong> (403 <code>PROPOSAL_BACK_OFFICE_ONLY</code> ailleurs).</li><li><strong>Péremption, toute la proposition</strong>, dans cet ordre : (1) magasin archivé ; (2) produit retiré ou absent ; (3) devenu à variantes ou variante ; (4) prix ou surcharge modifié (version du produit, version de la surcharge, son absence comprise) ; (5) groupe de l&#39;entreprise : un magasin non archivé d&#39;une autre devise est apparu. Phrase sur la première ligne en cause, « … (et N autres produits) » ; une simple validée entre-temps périme le groupe.</li><li><strong>Application</strong>, une transaction, lignes triées par identifiant : <strong>magasin</strong> — verrous des surcharges de toutes les lignes (<code>lockOverrides</code>, ordre trié) puis verrous de ligne des produits <code>FOR SHARE</code> (triés), <strong>avant toute écriture</strong>, puis <code>setPriceOnly</code> par ligne (prix seul, TVA et disponibilité brutes recopiées ; relit le produit sous verrou) ; <strong>entreprise</strong> — verrous des produits <code>FOR NO KEY UPDATE</code> (triés, jamais <code>FOR UPDATE</code>, qui bloquait les insertions des tables filles d&#39;un push de vente), puis <code>patchProduct</code> (<code>salePriceMinor</code> et <code>version</code> seulement) au nom du validateur. Produit retiré ou à variantes sous verrou, version changée → périmée, aucune ligne appliquée. <strong>La TVA n&#39;est jamais écrite.</strong> Chaque ligne laisse son audit, identique à l&#39;action humaine et portant l&#39;identifiant de la proposition (<code>agent_proposal_id</code>).</li><li><strong>Taux de marque</strong> (jamais « marge ») : (prix HT − coût) / prix HT, prix HT = TTC − TVA incluse, en points de base arrondis au plus proche ; non calculé si le coût manque, si le prix HT est nul ou en cas de dépassement. Magasin : prix et taux de TVA <strong>effectifs</strong> du magasin, coût = coût moyen du magasin, sinon coût d&#39;achat de la fiche ; entreprise : prix, taux et coût de la fiche, avec une note qui dit que le taux peut différer dans un magasin. Ligne signalée (icône et motif écrit, jamais la couleur seule) : « <strong>Sous le coût</strong> » (prix HT après &lt; coût) d&#39;abord, puis « Écart fort (±N %) » au-delà de 30 % ; <strong>jamais un refus</strong>. <strong>Note de revente à perte</strong> seulement s&#39;il y a une ligne sous le coût. Un <strong>prix actuel à 0</strong> est accepté : écart en pourcent vide, ligne hors de l&#39;écart moyen et des écarts forts.</li><li><strong>Écran</strong> : bloc <code>LINES</code> (Produit, Avant, Après, Écart, Marque avant, Marque après) et total « Écart cumulé des prix unitaires », signé ; notes permanentes (TVA inchangée, ventes enregistrées inchangées, commandes et paniers, tout ou rien) et conditionnelles (étiquettes en commerce de détail, arrondi au centime / millime en relatif, notes de l&#39;entreprise, coût manquant, revente à perte) ; libellé du bouton « Appliquer les N prix ».</li></ol></li><li><strong>RG-MCP-147</strong> — <strong>Prix groupé : outil de l&#39;assistant et présentation sur les caisses</strong> (précise RG-MCP-100, 120, 142) : <ol><li><strong>Outil <code>propose_price_changes</code></strong> (<code>proposals:write</code> + <code>catalog:read</code>, magasins lus), listé seulement si <code>PRICE_CHANGE_GROUP</code> est dans <code>proposalTypes</code> ; corps de type <code>PRICE_CHANGE</code> en forme groupée. Paramètres : <code>store</code> facultatif ; <strong>soit</strong> <code>lines</code> (1 à 100 <code>{product, new_price}</code>), <strong>soit</strong> <code>products</code> (1 à 100) avec <code>change</code> (montant signé) <strong>ou</strong> <code>change_percent</code> (une décimale) ; modes mêlés, 101 lignes, trop de décimales ou doublon de texte → refus avant l&#39;appel. Montants par <code>Amounts</code> dans la devise du magasin, sinon l&#39;unique devise de l&#39;accès. <code>store</code> absent ou « tous » : entreprise ; accès limité à <strong>un</strong> magasin : ce magasin, avec la note « Cet accès est limité à un magasin : les prix sont proposés pour « … », pas pour tous les magasins. » ; limité à plusieurs : refus avant l&#39;appel. Refus de ligne traduits avec le rang et le produit donné par l&#39;assistant. <code>propose_price_change</code> et ses réponses restent inchangés octet pour octet.</li><li><strong><code>find_product</code> avec <code>in_category</code></strong> (nom, même approximatif, ou <code>ref</code> <code>cat_…</code>) : produits <strong>en vente</strong> de la catégorie et de ses sous-catégories, 100 au plus, <code>query</code> devient facultatif ; catégorie ambiguë ou inconnue refusée, jamais choisie ; catégorie trouvée par rapprochement → note « Catégorie retenue pour « … » : « … ». ». Le paramètre ne s&#39;appelle pas <code>category</code> (même nom que celui de <code>propose_product</code>, il y faisait passer un nom de catégorie).</li><li><strong>Présentation sur les caisses</strong> (<code>shared</code>, iOS et Android) : un montant garde le <strong>signe du serveur</strong> (total « +0,60 € » / « −1,32 € », moins typographique) ; un <code>PRICE_CHANGE</code> de <strong>2 lignes ou plus</strong> prend le <strong>libellé du bouton du serveur</strong> (« Appliquer les N prix »), jamais celui du prix simple ; <strong>pour tous les types</strong>, dès que l&#39;aperçu de 5 lignes tronque la liste, les <strong>lignes signalées viennent d&#39;abord</strong>. Groupe de l&#39;entreprise : en lecture seule sur la caisse.</li></ol></li></ul><h3 id="creer-et-modifier-une-categorie-ven-50-lot-1-livre-eteint-le-20-11-2026" tabindex="-1">Créer et modifier une catégorie (VEN-50, lot 1, livré éteint le 20/11/2026) <a class="header-anchor" href="#creer-et-modifier-une-categorie-ven-50-lot-1-livre-eteint-le-20-11-2026" aria-label="Permalink to &quot;Créer et modifier une catégorie (VEN-50, lot 1, livré éteint le 20/11/2026)&quot;">​</a></h3><p>Fiche <a href="./../lots/MCP-ECRITURE-CATEGORIES">lots/MCP-ECRITURE-CATEGORIES.md</a>, <strong>validée par délégation d&#39;Ahmed le 19/11/2026</strong>, livrée <strong>éteinte</strong> le 20/11/2026 (<code>95c3d89f</code>) ; règles du catalogue : spec 02 RG-CAT-93 (ordre unique), RG-CAT-94 (verrou d&#39;arbre).</p><ul><li><strong>RG-MCP-148</strong> — <strong>Créer une catégorie</strong> (<code>CATEGORY_CREATE</code>, famille <code>CATALOG</code>, lecture <code>catalog:read</code>, aucun module, risque faible, réversible) <strong>et règles communes aux catégories</strong> (valent aussi pour RG-MCP-149) : <ol><li><strong>Contenu</strong> : <code>content {name, parent?, sortOrder? | place?}</code> (<code>sortOrder</code> entier de −9 999 à 9 999 ; <code>place</code><code>FIRST</code> | <code>LAST</code> ; exclusifs) ; parent : <code>ref</code> <code>cat_…</code>, UUID ou nom ; absent : premier niveau. <strong>Ni magasin ni devise</strong> (proposition de l&#39;entreprise). Fermés et nommés aux deux emplacements (racine et <code>content</code>) : <code>color</code>, <code>icon</code>, <code>id</code>, <code>parentId</code>, <code>storeId</code>, <code>products</code>, <code>lines</code>, <code>version</code>, <code>toRoot</code>, <code>category</code> → <code>FIELD_NOT_ALLOWED</code> ; <strong>champs fiscaux</strong> : tout nom qui évoque la TVA (<code>taxCode</code> compris) → <code>VAT_NOT_ALLOWED</code>, code famille, code NACEF, timbre, code fiscal (<code>familyCode</code>, <code>nacefFamily</code>, <code>stampDuty</code>, <code>fiscalCode</code>) → <code>FIELD_NOT_ALLOWED</code>. <strong>Garde de préfixe</strong> : la <code>ref</code> d&#39;un autre objet (<code>prd_…</code>, <code>sup_…</code>, <code>alr_…</code>) vaut <code>CATEGORY_NOT_FOUND</code> <strong>sans requête</strong>.</li><li><strong>Accès complet seulement</strong> : un accès limité à des magasins → 403 <code>API_KEY_STORE_RESTRICTED</code> avant toute lecture du catalogue (une catégorie vaut pour tous les magasins, comme RG-MCP-145).</li><li><strong>Validation par tout responsable</strong> (MANAGER, OWNER ou ADMIN) — <strong>parité exacte avec le geste humain</strong> (<code>requireManager</code> du service) —, <strong>au back-office seulement</strong> (aucun magasin, RG-MCP-113 ; lecture seule sur les caisses), <strong>sans case de confirmation</strong>.</li><li><strong>Un seul contrôle</strong> (<code>CategoryProposals.check</code>) à la création, à la péremption et dans l&#39;applicateur <strong>sous le verrou d&#39;arbre</strong> (spec 02 RG-CAT-94) : parent existant, <strong>trois niveaux</strong> au plus (<code>CATEGORY_DEPTH</code>), nom (<code>NAME_INVALID</code> : vide, plus de 120 caractères, caractère invisible, guillemets dont « › » ; <code>CATEGORY_EXISTS</code> : une <strong>autre</strong> catégorie porte le même nom normalisé, où qu&#39;elle soit — plus strict que le back-office). Autres codes : <code>CATEGORY_CONTENT_INVALID</code>, <code>CATEGORY_AMBIGUOUS</code> (candidats).</li><li><strong>Clé</strong> <code>CATEGORY_CREATE:*:&lt;nom normalisé&gt;</code> ; l&#39;identifiant de la catégorie créée est celui de la proposition (RG-MCP-140) ; contenu identique → dédoublonné (RG-MCP-119).</li><li><strong><code>place</code></strong> est traduit <strong>sous le verrou, à l&#39;application</strong> : <code>FIRST</code> = plus petit ordre des sœurs − 1, <code>LAST</code> = plus grand + 1, 0 sans sœur ; hors borne → périmée.</li><li><strong>Péremption</strong> (409 <code>PROPOSAL_STALE</code>), dans cet ordre : parent supprimé, parent devenu trop profond, nom pris, <code>place</code> hors borne.</li><li><strong>Application = action humaine</strong> : <code>CatalogService.lockCategoryTree</code> puis <code>createCategory</code> au nom du validateur (jamais couleur ni icône) ; même ligne, même événement <code>CategoryCreated</code> (tous les magasins), même audit <code>CREATED</code>, avec <code>agent_proposal_id</code>.</li><li><strong>Affichage</strong> (commun) : chemins « Carte › Desserts » dont <strong>chaque segment est isolé</strong> ; positions « 1 sur 5 » (jamais d&#39;ordinal), « En premier · 1 sur 5 » pour une <code>place</code> ; une <strong>création n&#39;a pas de valeur « avant »</strong> dans le bloc <code>CHANGES</code> ; <strong>toutes les notes en ton <code>INFO</code></strong> ; la note d&#39;ordre dit « Cet ordre vaut pour la borne, le menu en ligne et le back-office, pas pour les boutons de la caisse. ».</li></ol></li><li><strong>RG-MCP-149</strong> — <strong>Modifier une catégorie</strong> (<code>CATEGORY_UPDATE</code> : renommer, déplacer, réordonner ; règles communes de RG-MCP-148) : <ol><li><strong>Contenu</strong> : <code>content {category, name?, parent? | toRoot?, sortOrder? | place?}</code>, au moins un changement (<code>CATEGORY_MISSING</code> sans <code>category</code>) ; <code>toRoot</code> booléen strict ; mêmes champs fermés que la création, sauf <code>category</code> et <code>toRoot</code>, ouverts.</li><li><strong>Nom contrôlé seulement s&#39;il est proposé</strong> et diffère du nom actuel (<code>NAME_INVALID</code>, <code>CATEGORY_EXISTS</code>) : changer la casse passe ; déplacer ou réordonner l&#39;un de deux homonymes désigné par sa <code>ref</code> passe. <strong>Cycle</strong> refusé (<code>CATEGORY_CYCLE</code>), trois niveaux sous-catégories comprises (<code>CATEGORY_DEPTH</code>). <code>NOTHING_TO_CHANGE</code> (aucun champ, valeurs identiques, <code>place</code> déjà atteinte) est contrôlé <strong>avant</strong> tout remplacement.</li><li><strong>Clé</strong> <code>CATEGORY_UPDATE:*:&lt;catégorie&gt;</code> ; une seconde proposition avec changement remplace la première.</li><li><strong>Ordre</strong> : <code>sortOrder</code> ou <code>place</code> (traduit sous le verrou comme à la création).</li><li><strong>Péremption</strong>, dans cet ordre : catégorie supprimée, valeur relevée changée (nom, parent, ordre — pas de version), nouveau parent supprimé, cycle ou profondeur, nom pris (si <code>name</code> est proposé), <code>place</code> hors borne.</li><li><strong>Application</strong> : <code>lockCategoryTree</code> puis <code>patchCategory</code> au nom du validateur (jamais couleur, icône ni suppression) ; même ligne, événements <code>CategoryUpdated</code> et audit <code>UPDATED</code> que le geste humain, avec <code>agent_proposal_id</code>.</li><li><strong>Affichage</strong> : une ligne <code>CHANGES</code> par champ changé (avant → après) ; valeur forte avant → après, ou « 3 changements ». <strong>Limite écrite</strong> : la position affichée est <strong>figée à la création</strong> (instantané) ; si les sœurs changent avant la validation, la position réelle peut différer (l&#39;ordre relevé, lui, est contrôlé par la péremption).</li></ol></li><li><strong>RG-MCP-150</strong> — <strong>Catégories : outil de l&#39;assistant</strong> (précise RG-MCP-142) : <ol><li><strong><code>propose_category</code></strong> (<code>proposals:write</code> + <code>catalog:read</code>), <code>action</code> <code>create</code> | <code>update</code>, listé selon <code>proposalTypes</code> ; paramètres <code>name</code>, <code>parent</code>, <code>category</code>, <code>top_level</code> (→ <code>toRoot</code>), <code>sort_order</code> ou <code>place</code> (<code>first</code> | <code>last</code>) ; paramètres d&#39;un autre geste, paires exclusives, accès limité et <code>ref</code> d&#39;un autre objet refusés avant l&#39;appel. Forme <code>per_type</code> des évaluations : <code>propose_category_create</code>, <code>propose_category_update</code>.</li><li><strong><code>catalog_reference</code></strong> rend en plus <code>sortOrder</code> et <code>position</code> (« 2 sur 5 » parmi les sœurs) <strong>dans l&#39;ordre de la réponse du serveur</strong> (spec 02 RG-CAT-93), calculée sur la liste complète avant la troncature ; le MCP <strong>ne trie jamais</strong> lui-même (aucune copie de la règle).</li><li><strong>Consigne</strong> : l&#39;ordre vaut pour la borne, le menu en ligne et le back-office ; « en premier sur la caisse » relève de l&#39;<strong>écran de vente</strong> (lot 3 de VEN-50), pas de cet outil.</li></ol></li></ul><h2 id="_4-parcours-ecrans" tabindex="-1">4. Parcours &amp; écrans <a class="header-anchor" href="#_4-parcours-ecrans" aria-label="Permalink to &quot;4. Parcours &amp; écrans&quot;">​</a></h2><p><strong>Back-office web seulement.</strong></p><ol><li><p>Dans l&#39;assistant, l&#39;utilisateur ajoute l&#39;adresse du serveur MCP Vendora.</p></li><li><p>L&#39;assistant ouvre le navigateur sur Vendora ; l&#39;utilisateur se connecte s&#39;il ne l&#39;est pas (retour à la page).</p></li><li><p><strong>Connecter un assistant</strong> (<code>/connecter-assistant</code>) : carte de l&#39;assistant (nom, domaine, « Vérifié » / « Non vérifié »), magasins, familles de données, rappel lecture seule, <strong>Autoriser</strong> / <strong>Refuser</strong>. États : demande expirée ou déjà traitée, client ou redirection non reconnus, demande non valide (sans renvoi vers l&#39;assistant), demande ouverte dans un autre navigateur, trop de demandes, rôle insuffisant, accès coupé, formule sans le droit.</p></li><li><p>Retour dans l&#39;assistant, qui peut poser sa première question.</p></li><li><p><strong>Réglages › Assistant IA</strong> (lot M2, RG-MCP-49 → 54) : adresse du connecteur à copier et QR (bureau), étapes « Connecter Claude » et « Connecter ChatGPT » (bêta), <strong>Tester la connexion</strong>, questions pour bien commencer, <strong>Assistants connectés</strong> et <strong>Retirer l&#39;accès</strong>, activité lisible, clés pour intégrateurs, arrêt d&#39;urgence. La page <strong>Clés d&#39;API</strong> garde les clés classiques et un renvoi vers cette page.</p></li><li><p><strong>Propositions</strong> (lot VEN-34, RG-MCP-83 → 104) :</p><ul><li>dans l&#39;assistant : « Prépare ma commande chez … » → l&#39;outil répond « Proposition créée, en attente de votre validation » avec le lien ; la carte « Quoi commander » propose « Préparer le bon de commande » (RG-MCP-102) ;</li><li><strong>back-office › Propositions</strong> (<code>/propositions</code>, compteur dans le menu) : liste (en attente par défaut ; filtres statut, magasin, type), détail (RG-MCP-103), <strong>Valider</strong> / <strong>Refuser</strong> (motif) ; états : appliquée (lien vers le brouillon ou le produit), refusée, expirée, périmée (« les données ont changé : rien n&#39;a été appliqué ») ;</li><li><strong>Bons de commande</strong> : mention « Préparé par l&#39;assistant · validé par … » ;</li><li><strong>caisse et téléphone de salle iOS / Android</strong> (responsable connecté ; maquette M5 de la fiche) : alerte « Proposition de l&#39;assistant à valider » dans <strong>Alertes</strong>, entrée <strong>Propositions</strong> (en ligne seulement), détail, <strong>Valider</strong> (PIN, OWNER et ADMIN compris) / <strong>Refuser</strong> (motif, sans PIN) ; hors ligne : « Connexion nécessaire pour consulter et valider » ;</li><li><strong>Connecter un assistant</strong> : bloc « Préparer des propositions », décoché ; <strong>Réglages › Assistant IA</strong> : case <code>proposals:write</code> décochée à la création d&#39;une clé.</li></ul></li><li><p><strong>Écriture étendue</strong> (projet P-VEN-7, jalon 1 ; maquettes dans la fiche du socle, à compléter par <code>design-ux</code>) :</p><ul><li><strong>back-office › Propositions</strong> : un seul rendu pour tous les types (RG-MCP-120) — en-tête (qui, pour quel magasin, jusqu&#39;à quand), bloc « Ce qui va changer » (avant → après, ou lignes et total), avertissements, bloc « Rédigé par l&#39;assistant », saisie du validateur et case de confirmation si le type les demande, mention « Cette action ne s&#39;annule pas » pour un type non réversible ; filtre par <strong>famille</strong>, tri par risque, <strong>validation en lot</strong> non livrée (RG-MCP-121) ; bandeau de succès avec le lien vers l&#39;objet ;</li><li><strong>caisse et téléphone de salle iOS / Android</strong> : même rendu ; une proposition « back-office seulement » s&#39;affiche en lecture, badge « Back-office », avec « Ouvrez le back-office pour décider » et sans bouton ; un bloc que l&#39;app ne sait pas rendre, de même ; la case de confirmation s&#39;affiche aussi sur la caisse, avant le PIN ;</li><li><strong>Réglages › Assistant IA</strong> : bloc « Ce que l&#39;assistant peut préparer », une ligne par famille (éteinte par défaut), liste des actions de chaque famille ; familles accordées à la création d&#39;une clé ;</li><li><strong>Connecter un assistant</strong> : bloc « Préparer des propositions » détaillé <strong>par famille</strong>, rien de coché ; la famille « Clients » porte la mention des données envoyées à l&#39;assistant ;</li><li>dans l&#39;assistant : <code>list_proposals</code> (« 3 propositions attendent votre validation »).</li></ul></li></ol><p>Captures : <a href="/VendoraSystem-docs/captures/2026-11-11-mcp-m3/README"><code>docs/captures/2026-11-11-mcp-m3/</code></a>, <a href="/VendoraSystem-docs/captures/2026-11-12-mcp-m2/README"><code>docs/captures/2026-11-12-mcp-m2/</code></a>. Fiche de lot : <a href="./../lots/M2">lots/M2.md</a>.</p><h2 id="_5-modele-de-donnees" tabindex="-1">5. Modèle de données <a class="header-anchor" href="#_5-modele-de-donnees" aria-label="Permalink to &quot;5. Modèle de données&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Table</th><th>Rôle</th><th>Isolation</th></tr></thead><tbody><tr><td><code>api_keys</code> (<code>kind</code>, <code>store_ids</code>)</td><td>Clés, dont « Assistant IA »</td><td>RLS par commerce</td></tr><tr><td><code>agent_activity</code> (<code>source</code> : <code>API_KEY</code> / <code>OAUTH</code>)</td><td>Journal des assistants</td><td>RLS par commerce</td></tr><tr><td><code>oauth_clients</code></td><td>Clients connus (<code>CIMD</code> en cache, <code>DCR</code>) et leurs redirections</td><td>Globale, connexion admin seulement</td></tr><tr><td><code>oauth_requests</code></td><td>Demandes d&#39;autorisation (identifiant, code et cookie du navigateur hachés, décision)</td><td>Globale, connexion admin seulement</td></tr><tr><td><code>oauth_grants</code></td><td>Connexions : utilisateur, client, magasins, portées, expiration, retrait (<code>USER</code>, <code>CLIENT</code>, <code>REPLAY</code>)</td><td>RLS par commerce ; <code>pos_app</code> en lecture seule</td></tr><tr><td><code>oauth_tokens</code></td><td>Jetons hachés (<code>ACCESS</code>, <code>REFRESH</code>), rattachés à une connexion</td><td>Connexion admin seulement</td></tr></tbody></table><p>| <code>agent_proposals</code> (lot VEN-34) | Propositions : type, magasin, cible, contenu validé, instantané, <code>data_fresh_at</code>, justification, chiffres cités, accès d&#39;origine (<code>api_key_id</code> / <code>oauth_grant_id</code>), au nom de qui, expiration, statut courant ; contenu immuable (déclencheur) | RLS par commerce + <code>store_scope</code> | | <code>agent_proposal_events</code> (lot VEN-34) | Historique append-only des statuts (qui, quand, appareil, motif) | RLS par commerce ; <code>pos_app</code> : SELECT, INSERT | | <code>audit_log.actor</code>, <code>audit_log.agent_proposal_id</code>, <code>audit_log.device_id</code> ; <code>purchase_orders.agent_proposal_id</code> (lot VEN-34) | Acteur <code>USER</code> / <code>AGENT</code>, écritures nées d&#39;une proposition, appareil d&#39;une décision prise sur caisse (spec 01, spec 07) | — | | <code>tenant_entitlement_overrides.kind</code> (lot VEN-34, vague C) | Type de dérogation <code>EXTRA_AGENT_PROPOSALS</code> ajouté au CHECK de <code>V46</code> | Connexion de la console | | <code>agent_proposals</code> (jalon 1 de P-VEN-7, aucune colonne ajoutée) | Demande répétée (RG-MCP-119) : comparaison du contenu en <code>jsonb</code> parmi les propositions en attente de la même cible, sans colonne d&#39;empreinte. <strong>Pas de colonne de famille</strong> : la famille se calcule depuis le type, par le registre — le déclencheur d&#39;immutabilité de <code>V121</code> refuse tout <code>UPDATE</code> qui change autre chose que le statut, le motif d&#39;expiration et <code>superseded_by</code>, donc toute reprise | RLS par commerce + <code>store_scope</code> | | <code>tenant_agent_proposal_families</code> (jalon 1) | Familles que le commerce autorise (RG-MCP-111) : famille, autorisée, par qui, quand | RLS par commerce | | <code>api_keys.proposal_families</code>, <code>oauth_grants.proposal_families</code> (jalon 1) | Familles accordées à un accès ; reprise : <code>CATALOG</code>, <code>PURCHASES</code>, <code>FRAUD</code> pour les accès qui ont déjà <code>proposals:write</code> | celles de la table |</p><p>Migrations : <code>V99__agent_access.sql</code> (M0), <code>V103__oauth.sql</code> (M3), <code>V110__oauth_plafonds_par_reseau.sql</code> (colonnes ajoutées seulement : réseau d&#39;origine, confirmation, sel de rotation) ; lot VEN-34 : <code>V121</code> (livrée). Côté caisse, aucune table nouvelle : les alertes de propositions vont dans <code>local_manager_alert</code>. Vague C : migration <code>V122</code> (CHECK des dérogations). Jalon 1 de P-VEN-7 : <code>V123</code> (livrée : CHECK de forme sur <code>type</code>) puis <code>V124</code> (prévue : table ci-dessus, familles des accès existants, RLS ; aucune mise à jour des lignes de <code>agent_proposals</code>) ; côté caisse, <strong>aucune migration SQLDelight prévue</strong> (aucune copie locale des propositions ; le modèle d&#39;affichage voyage dans la réponse en ligne) — à confirmer par <code>dev-shared</code>.</p><p>Le registre de types lui-même n&#39;est <strong>pas</strong> une table : il vit dans le code (RG-MCP-106).</p><h2 id="_6-api" tabindex="-1">6. API <a class="header-anchor" href="#_6-api" aria-label="Permalink to &quot;6. API&quot;">​</a></h2><p>Détail dans <a href="/VendoraSystem-docs/architecture/api-publique">API-PUBLIQUE.md</a> § 1 à § 6.</p><ul><li>Clés et accès : <code>POST /api/v1/api-keys</code> (<code>kind</code>, <code>storeIds</code>), <code>GET /api/v1/api-keys/me</code>, <code>GET</code> / <code>PUT /api/v1/tenant/agent-access</code>, <code>GET /api/v1/agent-activity</code>.</li><li>Agrégations pour les assistants : <code>GET /api/v1/inventory/reorder-suggestions</code>, <code>GET /api/v1/reports/margin-analysis</code>.</li><li>OAuth (hors <code>/api/v1</code>) : <code>GET /.well-known/oauth-authorization-server</code>, <code>POST /oauth/token</code>, <code>POST /oauth/revoke</code>, <code>POST /oauth/register</code>.</li><li>Autorisation (par l&#39;origine du back-office) : <code>GET /api/v1/oauth/authorize</code>.</li><li>Consentement et connexions : <code>GET /api/v1/oauth/requests/{demande}</code>, <code>POST …/approve</code>, <code>POST …/deny</code>, <code>GET /api/v1/oauth/connections</code>, <code>DELETE /api/v1/oauth/connections/{id}</code>.</li><li>Page « Assistant IA » (routes <strong>internes</strong> au back-office, session d&#39;un propriétaire ou d&#39;un administrateur, fermées aux clés et aux jetons d&#39;assistant, absentes de l&#39;OpenAPI publique) : <code>GET /api/v1/assistant/status</code>, <code>POST /api/v1/assistant/test</code>.</li><li>Service <code>mcp/</code> : <code>POST /mcp</code>, <code>GET /healthz</code>, <code>GET /.well-known/oauth-protected-resource</code> (et <code>…/mcp</code>).</li><li>Propositions (lot VEN-34) : <code>POST /api/v1/agent-proposals</code> (accès d&#39;assistant avec <code>proposals:write</code>, publique) ; <code>GET /api/v1/agent-proposals</code> (<code>storeId</code>, <code>status</code>, <code>type</code>) et <code>GET /api/v1/agent-proposals/{id}</code> (sessions et clés READ / WRITE, publique) ; <code>POST /api/v1/agent-proposals/{id}/approve</code> et <code>…/reject</code> (session utilisateur seulement, fermées à toute clé, hors OpenAPI publique) ; caisse : <code>GET /api/v1/pos/agent-proposals[/{id}]</code>, <code>POST /api/v1/pos/agent-proposals/{id}/approve|reject</code> (jeton d&#39;appareil <code>REGISTER</code> ou <code>WAITER_TERMINAL</code>, <code>userId</code> et, pour valider, <code>managerPin</code> dans le corps). Le détail porte <code>supersededBy</code>. Codes : <code>PROPOSAL_EXPIRED</code>, <code>PROPOSAL_STALE</code>, <code>PROPOSAL_ALREADY_DECIDED</code> (409), <code>LIMIT_REACHED</code> (<code>AGENT_PROPOSALS</code>, <code>AGENT_PROPOSALS_PENDING</code>).</li><li>Écriture étendue (jalon 1 de P-VEN-7 ; ajouts seulement, rien de retiré) : <ul><li><code>POST /api/v1/agent-proposals</code> : champs des types nouveaux dans l&#39;objet <code>content</code> (liste fermée par type) et <code>lines</code> pour un type groupé ; réponse 200 avec <code>deduplicated: true</code> pour une demande répétée (RG-MCP-119) ;</li><li>détail et liste : <code>proposalFamily</code>, et l&#39;objet <strong><code>display</code></strong> (RG-MCP-120 : <code>v</code>, <code>typeLabel</code>, <code>familyLabel</code>, <code>icon</code>, <code>title</code>, <code>summary</code>, <code>keyFigure</code>, <code>scope</code>, <code>risk</code>, <code>reversible</code>, <code>warnings</code>, <code>blocks</code> — <code>CHANGES</code>, <code>LINES</code>, <code>OPERATIONS</code>, <code>TARGET</code>, <code>NOTES</code> —, <code>snapshot</code>, <code>decision</code> — <code>places</code>, <code>viewer</code>, <code>approveLabel</code>, <code>approveLabelShort</code>, <code>input</code>, <code>confirmation</code>, <code>confirmDialog</code> —, <code>success</code> — <code>text</code>, <code>link</code>, <code>deviceText</code>) ; filtres <code>proposalFamily</code> et <code>type</code> sur la liste ; la réponse de validation réserve <code>result</code> (RG-MCP-131) ;</li><li><strong>vue pour les accès d&#39;assistant</strong> : <code>GET /api/v1/agent-proposals/mine</code> (clé AGENT ou jeton avec <code>proposals:write</code>, classée par méthode comme la création ; publique) — magasins et familles de l&#39;accès, champs de RG-MCP-127 seulement ; <code>GET /api/v1/agent-proposals[/{id}]</code> reste réservée aux sessions et aux clés <code>READ</code> / <code>WRITE</code> ;</li><li>validation (back-office et caisse) : <code>validatorInput</code> (la saisie ; <code>alertReason</code> reste accepté pour <code>FRAUD_ALERT_HANDLING</code>), <code>confirmed</code>, et <code>managerPin</code> au back-office pour un type qui l&#39;exige ; <strong>aucune route de validation en lot</strong> (non livrée, RG-MCP-121) ;</li><li><code>GET /api/v1/api-keys/me</code> : <code>proposalTypes</code> (types que l&#39;accès peut créer maintenant), <code>proposalFamilies</code> ; <code>proposalsEnabled</code> conservé ;</li><li><code>GET</code> / <code>PUT /api/v1/tenant/agent-proposal-families</code> (session d&#39;un propriétaire ou d&#39;un administrateur ; <strong>toute clé — AGENT, <code>READ</code>, <code>WRITE</code> — et tout jeton : 403</strong>, en lecture comme en écriture ; délégation : <code>GET</code> permis, <code>PUT</code> 403 <code>DELEGATION_SCOPE</code> ; hors OpenAPI publique) ; <code>POST /api/v1/api-keys</code> et le consentement OAuth acceptent <code>proposalFamilies</code> ;</li><li>codes d&#39;erreur nouveaux : <code>PROPOSAL_FAMILY_DISABLED</code> (403), <code>PROPOSAL_BACK_OFFICE_ONLY</code> (403), et, à la <strong>décision</strong>, <code>CONFIRMATION_REQUIRED</code> et <code>VALIDATOR_INPUT_REQUIRED</code> (422, à la racine de la réponse). <code>TYPE_UNKNOWN</code>, <code>FIELD_NOT_ALLOWED</code> et <code>VAT_NOT_ALLOWED</code> ne sont pas des codes d&#39;erreur : ce sont des <strong>violations</strong> du 422 <code>PROPOSAL_INVALID</code> de la création, qui existent déjà.</li></ul></li></ul><h2 id="_7-evenements-de-sync" tabindex="-1">7. Événements de sync <a class="header-anchor" href="#_7-evenements-de-sync" aria-label="Permalink to &quot;7. Événements de sync&quot;">​</a></h2><p>Lecture : aucun. Un assistant lit ce que le serveur a reçu ; la fraîcheur annoncée (RG-MCP-14) vient de la dernière synchronisation des caisses.</p><p>Propositions (lot VEN-34) : <code>AgentProposalRaised</code> et <code>AgentProposalDecided</code>, émis par le serveur (appareil virtuel du magasin) vers les appareils du magasin, canal des alertes des responsables (<code>ManagerAlertEvents</code>, spec 12 § 4.2), sans texte de l&#39;assistant. L&#39;application d&#39;une proposition émet les événements habituels de l&#39;action appliquée (<code>ProductUpdated</code>, <code>StoreProductOverrideSet</code>, <code>FraudAlertResolved</code>) ; un bon brouillon n&#39;en émet aucun, comme aujourd&#39;hui.</p><p>Écriture étendue : aucun événement nouveau. <code>AgentProposalRaised</code> / <code>AgentProposalDecided</code> portent le nom du type en texte ; un appareil qui ne le connaît pas garde l&#39;alerte et son résumé (RG-MCP-132). Chaque type appliqué émet les événements <strong>de son service humain</strong>, sans exception ni raccourci (un type de stock : <code>StockMovementRecorded</code>).</p><h2 id="_8-permissions-securite" tabindex="-1">8. Permissions &amp; sécurité <a class="header-anchor" href="#_8-permissions-securite" aria-label="Permalink to &quot;8. Permissions &amp; sécurité&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Qui</th></tr></thead><tbody><tr><td>Créer une clé « Assistant IA », autoriser un assistant, retirer un accès</td><td>Propriétaire, administrateur</td></tr><tr><td>Arrêt d&#39;urgence du commerce</td><td>Propriétaire</td></tr><tr><td>Arrêt global</td><td>Équipe Vendora (console, administrateur de la plateforme)</td></tr><tr><td>Appeler <code>/api/v1/oauth/**</code></td><td>Utilisateur du back-office seulement — fermé aux clés et aux jetons</td></tr><tr><td>Créer une proposition</td><td>Accès d&#39;assistant avec <code>proposals:write</code> + lecture du type (RG-MCP-95)</td></tr><tr><td>Valider / refuser une proposition</td><td>Responsable selon le type (RG-MCP-91) ; jamais une clé ni un jeton</td></tr><tr><td>Valider sur une caisse ou un téléphone de salle</td><td>Responsable connecté, <strong>sous PIN manager</strong> vérifié par le serveur (OWNER et ADMIN compris), en ligne</td></tr><tr><td>Refuser sur un appareil</td><td>Responsable connecté, sans PIN (question 3), en ligne</td></tr><tr><td><code>/api/v1/agent-proposals/**</code> sous délégation Vendora</td><td>Toujours interdit (403 <code>DELEGATION_SCOPE</code>)</td></tr><tr><td>Créer une proposition d&#39;un type donné</td><td>En plus : type allumé, famille autorisée par le commerce et accordée à l&#39;accès (RG-MCP-110, 111)</td></tr><tr><td>Autoriser une famille de propositions pour le commerce, accorder une famille à un accès</td><td>Propriétaire, administrateur — <strong>jamais</strong> une clé, un jeton ni une session déléguée</td></tr><tr><td>Lire les familles autorisées</td><td>Session d&#39;un propriétaire ou d&#39;un administrateur ; session déléguée en lecture seule ; aucune clé, aucun jeton</td></tr><tr><td>Lire ses propres propositions (<code>list_proposals</code>)</td><td>Accès d&#39;assistant avec <code>proposals:write</code> : vue dédiée, sans justification ni commentaire (RG-MCP-127)</td></tr><tr><td>Allumer un type</td><td>Équipe Vendora (exploitation), après la revue de sécurité de la famille (ou la tranche du type dans une famille revue, RG-MCP-139)</td></tr><tr><td>Éteindre un type allumé sur le staging (défaut bloquant)</td><td>Chef de lot, qui prévient Ahmed (RG-MCP-139)</td></tr><tr><td>Valider un type qui exige le PIN au back-office</td><td>Responsable selon le type, <strong>sous PIN manager</strong> (RG-MCP-114)</td></tr><tr><td>Valider en lot</td><td>Non livré (décision du 16/11/2026, RG-MCP-121)</td></tr></tbody></table><p>Lecture et connexion : aucune action sous PIN manager. Propositions : la décision sur une caisse se fait sous PIN (RG-MCP-91). Écriture étendue : un assistant ne peut <strong>jamais élargir ses propres droits</strong> — aucun type ne touche utilisateurs, rôles, PIN, clés, accès de l&#39;assistant, familles, délégations ni webhooks (RG-MCP-107, test de garde), et les réglages par famille sont fermés à tout accès d&#39;assistant (RG-MCP-111) ; la garde juge les appels déclarés de chaque type sur le code compilé et un applicateur n&#39;agit au nom du validateur que par <code>ApplyContext.asValidator</code> (RG-MCP-138). Points de vigilance tenus par les règles : RG-MCP-08 (secrets), 31 (SSRF, délai ferme), 32 (redirections, pas de redirection ouverte), 33 (PKCE, code), 36 (noms d&#39;assistants), 40 (rejeu), 42 (accès recalculé), 45 à 47 (débit, liaison au navigateur, stockage borné), 48 (interrupteur). <code>pos_app</code> n&#39;a que la <strong>lecture</strong> de <code>oauth_grants</code> ; toute écriture OAuth passe par la connexion admin.</p><p><strong>Limites connues, assumées</strong> : (a) la liaison au navigateur protège le lien de <strong>consentement</strong> ; un lien d&#39;<strong>autorisation</strong> forgé et envoyé à un commerçant ouvre encore une demande dans son navigateur — les parades sont alors l&#39;étiquette « Non vérifié », le domaine de retour affiché, le nom remplacé (RG-MCP-36) et l&#39;accès en lecture seule ; (b) le paramètre <code>resource</code> est vérifié à l&#39;émission du jeton, pas relu à chaque usage (une seule ressource existe aujourd&#39;hui) ; (c) le rejeu d&#39;un jeton de renouvellement est strict <strong>au-delà de la fenêtre de grâce de 30 secondes</strong> (RG-MCP-77).</p><h2 id="_9-cas-limites-erreurs" tabindex="-1">9. Cas limites &amp; erreurs <a class="header-anchor" href="#_9-cas-limites-erreurs" aria-label="Permalink to &quot;9. Cas limites &amp; erreurs&quot;">​</a></h2><ul><li>Demande expirée (10 minutes) ou déjà décidée : 410, l&#39;écran invite à relancer la connexion depuis l&#39;assistant.</li><li>Document client injoignable, trop gros, redirigé, ou qui ne se désigne pas lui-même : écran « assistant non reconnu », aucune redirection. Serveur du document trop lent, ou trop de lectures en cours : écran « trop de demandes », à réessayer.</li><li>Lien de consentement ouvert ailleurs que dans le navigateur qui a lancé la connexion : 403, écran « ouverte dans un autre navigateur ».</li><li>Plafond de demandes en attente ou de clients enregistrés atteint : refus (écran « trop de demandes », ou 503 <code>temporarily_unavailable</code> à l&#39;enregistrement) ; rien n&#39;est stocké.</li><li>Serveur d&#39;autorisation éteint (RG-MCP-48) : 404 partout ; le serveur MCP continue d&#39;accepter les clés.</li><li>L&#39;utilisateur perd un magasin accordé : l&#39;assistant ne le voit plus ; il les perd tous, ou est désactivé : 401.</li><li>Réponse d&#39;un renouvellement perdue par le client : s&#39;il rejoue le même jeton dans les 30 secondes, il reçoit la même paire (RG-MCP-77) ; au-delà, ou si la paire a servi, c&#39;est un rejeu → connexion révoquée, il faut reconnecter.</li><li>Service MCP sans adresse publique configurée : la connexion OAuth n&#39;est pas annoncée, seules les clés servent.</li><li>Démonstration publique saturée (huit réseaux distincts suffisent à tenir le plafond global) : 429 pour tous les visiteurs tant que cela dure — risque accepté d&#39;une démo en lecture seule sur données fictives ; coupure par <code>VENDORA_MCP_DEMO_ENABLED=false</code>. Clé de démo expirée, arrêt d&#39;urgence du commerce de démo ou formule sans assistant : 503 « momentanément indisponible », cause lisible dans le journal (<code>apiError</code>).</li><li>Hébergement qui dort (plan gratuit) : le réveil dépasse les 10 secondes laissées par les assistants — réveiller le service avant de connecter.</li><li>Proposition validée alors que le produit, la surcharge, le fournisseur ou l&#39;alerte ont changé : 409 <code>PROPOSAL_STALE</code>, rien n&#39;est appliqué, <code>EXPIRED</code> (<code>STALE</code>) ; l&#39;écran le dit et propose de demander une nouvelle proposition.</li><li>Caisse hors ligne : l&#39;alerte reste visible, la décision attend le réseau ; l&#39;expiration court quand même.</li><li>Connexion d&#39;assistant retirée, utilisateur désactivé ou arrêt d&#39;urgence après la création : la proposition reste décidable (elle n&#39;agit qu&#39;au geste d&#39;un responsable) et dit d&#39;où elle vient.</li><li>Module « Fournisseurs » retiré entre la création et la validation : la validation est refusée (409 <code>LIMIT_REACHED</code>, <code>kind: MODULE</code>), la proposition reste <code>PROPOSED</code> jusqu&#39;à son expiration.</li><li>Assistant qui répète la même demande : la dernière proposition remplace la précédente (RG-MCP-88) ; si le contenu est strictement identique, l&#39;existante est renvoyée sans rien écrire ni consommer de quota (RG-MCP-119).</li><li>Type éteint par l&#39;exploitation ou famille retirée par le commerce après la création : la proposition reste décidable ; plus aucune création pour ce type.</li><li>Une ligne d&#39;une proposition groupée périmée : toute la proposition passe <code>STALE</code>, rien n&#39;est appliqué.</li><li>Proposition groupée et propositions simples sur les mêmes cibles : la groupée remplace les simples à sa création ; l&#39;inverse se règle à la validation par le contrôle de péremption (RG-MCP-117).</li><li>App caisse d&#39;ancienne version devant un type nouveau : résumé et renvoi vers le back-office, aucun bouton de décision (RG-MCP-121).</li><li>Validation sans la saisie ou la confirmation attendue : 422, rien d&#39;appliqué, la proposition reste en attente.</li><li>Validation en lot : non livrée (RG-MCP-121) ; chaque proposition se valide une à une, une proposition groupée valant pour toutes ses lignes.</li><li>Champ de TVA dans un type qui ne l&#39;admet pas, ou ligne de mise à jour d&#39;un import qui change le taux : 422 <code>PROPOSAL_INVALID</code>, violation <code>VAT_NOT_ALLOWED</code> ; taux de TVA désactivé entre la création et la validation d&#39;un <code>PRODUCT_CREATE</code> : <code>PROPOSAL_STALE</code> ; produit créé sans taux nommé : le validateur choisit le taux, rien n&#39;est présélectionné.</li><li>Assistant connecté par OAuth sans la famille de lecture « Réglages » : les types qui exigent <code>settings:read</code> ne sont pas listés ; la réponse dit quelle lecture manque et où l&#39;accorder (RG-MCP-09).</li><li>Service humain qui accepte un résultat partiel (stock initial) : l&#39;applicateur annule tout si une ligne est refusée.</li></ul><h2 id="_10-criteres-d-acceptation" tabindex="-1">10. Critères d&#39;acceptation <a class="header-anchor" href="#_10-criteres-d-acceptation" aria-label="Permalink to &quot;10. Critères d&#39;acceptation&quot;">​</a></h2><ol><li><strong>Étant donné</strong> un serveur MCP appelé sans accès, <strong>quand</strong> un client lit le 401, <strong>alors</strong> il trouve le document de ressource, puis les métadonnées du serveur d&#39;autorisation (S256 seul, client public, document client annoncé).</li><li><strong>Étant donné</strong> une demande dont la redirection n&#39;est pas déclarée, <strong>quand</strong> elle arrive au point d&#39;autorisation, <strong>alors</strong> l&#39;utilisateur voit un écran d&#39;erreur de Vendora et aucune redirection vers cette adresse n&#39;a lieu.</li><li><strong>Étant donné</strong> une demande avec PKCE <code>plain</code> ou sans méthode, <strong>quand</strong> elle arrive, <strong>alors</strong> elle est refusée (<code>invalid_request</code>).</li><li><strong>Étant donné</strong> un propriétaire connecté, <strong>quand</strong> il autorise un magasin et la famille « ventes et rapports », <strong>alors</strong> l&#39;assistant reçoit un jeton qui lit les ventes de ce magasin, pas le stock, pas un autre magasin.</li><li><strong>Étant donné</strong> un code déjà échangé, <strong>quand</strong> il est présenté de nouveau, <strong>alors</strong> il est refusé et les jetons nés de ce code sont révoqués.</li><li><strong>Étant donné</strong> un jeton de renouvellement déjà utilisé, <strong>quand</strong> il est rejoué <strong>en dehors de la fenêtre de grâce</strong> (après 30 secondes, ou par un autre client, ou après usage de la paire rendue — RG-MCP-77), <strong>alors</strong> toute la connexion est révoquée.</li><li><strong>Étant donné</strong> une connexion active, <strong>quand</strong> le propriétaire clique « Retirer l&#39;accès », <strong>alors</strong> la requête suivante de l&#39;assistant reçoit 401.</li><li><strong>Étant donné</strong> l&#39;arrêt d&#39;urgence actif ou une formule sans <code>MCP_ACCESS</code>, <strong>quand</strong> l&#39;assistant appelle, <strong>alors</strong> il reçoit les mêmes refus qu&#39;une clé « Assistant IA ».</li><li><strong>Étant donné</strong> un document client dont le nom de domaine pointe vers une adresse privée, <strong>quand</strong> le serveur veut le lire, <strong>alors</strong> il refuse avant toute connexion.</li><li><strong>Étant donné</strong> un jeton d&#39;un commerce, <strong>quand</strong> il sert à lire un autre commerce, <strong>alors</strong> rien n&#39;est visible.</li><li><strong>Étant donné</strong> un client enregistré lui-même, <strong>quand</strong> il envoie une demande incorrecte (par exemple <code>response_type=token</code>), <strong>alors</strong> aucune redirection vers son adresse n&#39;a lieu : écran d&#39;erreur de Vendora.</li><li><strong>Étant donné</strong> une demande ouverte dans un navigateur, <strong>quand</strong> un autre navigateur présente son identifiant, <strong>alors</strong> il ne peut ni la lire, ni l&#39;autoriser, ni la refuser (403).</li><li><strong>Étant donné</strong> un serveur de document client qui ne répond pas (ou très lentement), <strong>quand</strong> le serveur veut le lire, <strong>alors</strong> il abandonne en 5 secondes au plus, et la neuvième lecture simultanée est refusée tout de suite.</li><li><strong>Étant donné</strong> le plafond de demandes en attente ou de clients enregistrés atteint, <strong>quand</strong> une demande de plus arrive, <strong>alors</strong> elle est refusée et rien n&#39;est stocké.</li><li><strong>Étant donné</strong> un même code présenté deux fois en même temps, <strong>quand</strong> les deux échanges se croisent, <strong>alors</strong> un seul reçoit des jetons et la connexion finit révoquée.</li><li><strong>Étant donné</strong> l&#39;interrupteur éteint, <strong>quand</strong> on appelle un point OAuth, <strong>alors</strong> 404 ; allumé sans émetteur ni ressources hors développement, le serveur ne démarre pas.</li><li><strong>Étant donné</strong> un refus de consentement, une révocation par l&#39;assistant ou un rejeu, <strong>quand</strong> on lit le journal d&#39;audit, <strong>alors</strong> chacun y figure avec son motif.</li></ol><p>Lot VEN-34 (détail et vagues : <a href="./../lots/VEN-34">fiche</a>, critères 1 → 33 ; « fiche c. N » = critère N de la fiche) :</p><ol start="18"><li><em>(Vague A — fiche c. 1, 12)</em> <strong>Étant donné</strong> un accès avec <code>proposals:write</code>, <strong>quand</strong> l&#39;assistant propose un bon de commande, <strong>alors</strong> une proposition <code>PROPOSED</code> existe, aucun bon n&#39;est créé, la réponse dit « en attente de votre validation » avec le lien.</li><li><em>(Vague A — fiche c. 2, 3)</em> <strong>Étant donné</strong> un accès sans <code>proposals:write</code>, <strong>alors</strong> les outils de proposition sont absents et la création est refusée (403) ; <strong>étant donné</strong> n&#39;importe quelle clé ou jeton, ou une session déléguée, <strong>alors</strong> valider ou refuser est refusé (403).</li><li><em>(Vague A — fiche c. 4 ; vague C — c. 25, 28)</em> <strong>Étant donné</strong> une proposition validée par un responsable, <strong>alors</strong> l&#39;effet (brouillon, prix, alerte) et les statuts <code>APPROVED</code> puis <code>APPLIED</code> naissent dans la même transaction, au nom du validateur, rattachés à la proposition, et l&#39;audit porte la création d&#39;acteur <code>AGENT</code>.</li><li><em>(Vague A — fiche c. 6 ; vague C — c. 27)</em> <strong>Étant donné</strong> des données changées depuis la proposition, <strong>quand</strong> on la valide, <strong>alors</strong> 409 <code>PROPOSAL_STALE</code>, rien n&#39;est appliqué, elle passe <code>EXPIRED</code> ; au-delà de 72 h, 409 <code>PROPOSAL_EXPIRED</code>.</li><li><em>(Vague A — fiche c. 8)</em> <strong>Étant donné</strong> l&#39;historique d&#39;une proposition, <strong>quand</strong> l&#39;application tente de le modifier ou d&#39;en changer le contenu, <strong>alors</strong> la base refuse.</li><li><em>(Vague B — fiche c. 19, 20)</em> <strong>Étant donné</strong> un responsable sur une caisse en ligne, <strong>quand</strong> il valide, <strong>alors</strong> son PIN est vérifié par le serveur et l&#39;écriture appliquée porte son <code>user_id</code> et l&#39;appareil ; hors ligne, aucune décision n&#39;est possible et l&#39;alerte reste visible.</li><li><em>(Vague C — fiche c. 25, 26)</em> <strong>Étant donné</strong> une proposition de prix, <strong>alors</strong> seule la valeur du prix change (TVA et disponibilité de la surcharge conservées, TVA du produit inchangée), la version est vérifiée, et les ventes déjà scellées ne changent pas.</li><li><em>(Vague A — fiche c. 9 ; vague C — c. 29)</em> <strong>Étant donné</strong> le quota en attente ou mensuel atteint, <strong>quand</strong> l&#39;assistant propose, <strong>alors</strong> 409 <code>LIMIT_REACHED</code> relayable, sans effet sur les propositions existantes.</li></ol><p>Écriture étendue, jalon 1 du projet P-VEN-7 (détail, vagues et tickets : <a href="./../lots/MCP-ECRITURE-SOCLE">fiche du socle</a>, critères 1 → 40 ; « socle c. N » = critère N de cette fiche) :</p><ol start="26"><li><em>(socle c. 1, 2)</em> <strong>Étant donné</strong> les trois types du lot VEN-34 migrés sur le registre, <strong>quand</strong> on relance leurs tests, <strong>alors</strong> ils passent sans changer leurs attentes ; <strong>étant donné</strong> un type absent du registre, <strong>alors</strong> 422 <code>TYPE_UNKNOWN</code> et rien n&#39;est écrit.</li><li><em>(socle c. 3)</em> <strong>Étant donné</strong> un type quelconque du registre, <strong>quand</strong> la suite générique s&#39;exécute, <strong>alors</strong> elle prouve contenu immuable, péremption sans effet, application au nom du validateur, audit <code>AGENT</code>, décision fermée aux clés et à la délégation, isolation entre commerces et magasins (RG-MCP-130).</li><li><em>(socle c. 4)</em> <strong>Étant donné</strong> un type inscrit mais non allumé, ou une famille que le commerce n&#39;autorise pas, ou que l&#39;accès n&#39;a pas reçue, <strong>quand</strong> l&#39;assistant liste ses outils et tente de créer, <strong>alors</strong> l&#39;outil est absent et la création refusée ; les propositions existantes restent décidables.</li><li><em>(socle c. 6)</em> <strong>Étant donné</strong> une proposition groupée dont une ligne est périmée, <strong>quand</strong> on la valide, <strong>alors</strong> 409 <code>PROPOSAL_STALE</code>, aucune ligne n&#39;est appliquée.</li><li><em>(socle c. 7)</em> <strong>Étant donné</strong> une demande identique à une proposition en attente du même accès, <strong>quand</strong> elle est répétée, <strong>alors</strong> la même proposition est renvoyée, rien n&#39;est écrit, le quota ne bouge pas.</li><li><em>(socle c. 9)</em> <strong>Étant donné</strong> un applicateur qui viserait un domaine exclu (RG-MCP-107), <strong>quand</strong> la suite s&#39;exécute, <strong>alors</strong> le test de garde échoue.</li><li><em>(socle c. 24, 27)</em> <strong>Étant donné</strong> un type nouveau fourni par le serveur, <strong>quand</strong> le back-office et les apps iOS et Android l&#39;affichent, <strong>alors</strong> le rendu « avant → après » est complet sans code propre au type ; une app qui ne sait pas le rendre affiche le renvoi vers le back-office.</li><li><em>(socle c. 10, 11, 25, 26)</em> <strong>Étant donné</strong> un type qui exige une saisie ou une confirmation, <strong>quand</strong> elle manque, <strong>alors</strong> le bouton reste inactif et le serveur refuse (422) ; <strong>étant donné</strong> un type « back-office seulement », <strong>quand</strong> une caisse tente de le décider, <strong>alors</strong> 403 <code>PROPOSAL_BACK_OFFICE_ONLY</code>.</li><li><em>(socle c. 14)</em> <strong>Étant donné</strong> une clé, un jeton ou une session déléguée, <strong>quand</strong> il tente de changer les familles autorisées, <strong>alors</strong> 403 ; le changement fait par un propriétaire est inscrit au journal d&#39;audit.</li><li><em>(socle c. 35, 36, 37, 39)</em> <strong>Étant donné</strong> une route du back-office qui écrit et qui manque à la matrice, <strong>alors</strong> le test de complétude échoue ; <strong>étant donné</strong> <code>proposals:write</code> sans la portée de lecture d&#39;un type, <strong>alors</strong> 403 <code>API_KEY_SCOPE</code> nomme la portée ; <strong>étant donné</strong> une clé AGENT, <strong>quand</strong> elle lit ses propositions, <strong>alors</strong> la vue dédiée ne rend ni justification ni commentaire libre ; <strong>étant donné</strong> un <code>ref</code> d&#39;un autre commerce ou d&#39;un type inattendu, <strong>alors</strong> « introuvable ».</li><li><em>(disponibilité c. 3, 4, 9)</em> <strong>Étant donné</strong> une proposition <code>PRODUCT_AVAILABILITY</code> validée, <strong>alors</strong> seule la disponibilité de la surcharge du magasin change (prix et TVA recopiés, même sous écriture concurrente), l&#39;événement <code>StoreProductOverrideSet</code> part vers les caisses du magasin et le produit disparaît de la vente, du scan et du menu en ligne de ce magasin seulement ; <strong>étant donné</strong> un type inscrit au registre, <strong>alors</strong> les écrans de réglage l&#39;affichent par son libellé, jamais par son code (RG-MCP-133 ; RG-MCP-134 puis 137 : le libellé est déclaré par le type et rendu par le serveur dans les trois langues).</li><li><em>(produit c. 5, 6, 7)</em> <strong>Étant donné</strong> une proposition <code>PRODUCT_UPDATE</code> ou <code>PRODUCT_ARCHIVE</code> validée, <strong>alors</strong> seuls les champs proposés de la fiche changent (prix de vente, TVA, surcharges des magasins et tout autre champ identiques avant et après), par <code>patchProduct</code> avec la version relevée, et <code>ProductUpdated</code> part vers les mêmes magasins que pour l&#39;action humaine ; <strong>étant donné</strong> une fiche modifiée entre-temps, <strong>alors</strong> 409 <code>PROPOSAL_STALE</code> sans effet ; <strong>étant donné</strong> une remise en vente au-delà de la limite de la formule, <strong>alors</strong> 409 <code>LIMIT_REACHED</code> et la proposition reste en attente (RG-MCP-135, 136).</li><li><em>(sécurité V1 c. 1, 2, 9)</em> <strong>Étant donné</strong> un type qui appelle une méthode non déclarée ou exclue, pose un contexte, fabrique un utilisateur ou écrit en SQL, <strong>quand</strong> la suite s&#39;exécute, <strong>alors</strong> la garde échoue en nommant le type et l&#39;appel ; <strong>étant donné</strong> une justification et des chiffres cités hostiles, <strong>quand</strong> la proposition est validée, <strong>alors</strong> l&#39;effet est exactement le contenu validé et aucun fragment du texte de l&#39;assistant n&#39;apparaît hors de sa zone (RG-MCP-138).</li><li><em>(sécurité V1 c. 12)</em> <strong>Étant donné</strong> une famille à allumer sur le staging, <strong>alors</strong> son rapport existe dans <code>docs/securite/</code> avec chaque attaque, sa preuve et son résultat, un avis <code>expert-fiscal</code> et une relecture <code>revue-code</code> sans bloquant ouvert ; un type ajouté à une famille revue a sa ligne au rapport (RG-MCP-139).</li><li><em>(création c. 1, 2, 5, 6, 7)</em> <strong>Étant donné</strong> une proposition <code>PRODUCT_CREATE</code> sans taux nommé, <strong>quand</strong> elle est affichée, <strong>alors</strong> les taux actifs sont proposés « nom — pourcentage calculé » sans présélection ; <strong>quand</strong> elle est validée sans choix ou sans la case, <strong>alors</strong> 422 et rien n&#39;est écrit ; <strong>quand</strong> elle est validée avec un taux et la case, <strong>alors</strong> le produit créé est identique à une création humaine aux mêmes valeurs (devise comprise), son identifiant est celui de la proposition, <code>ProductCreated</code> part vers les mêmes magasins ; <strong>étant donné</strong> la limite de produits atteinte, <strong>alors</strong> la proposition reste en attente ; <strong>étant donné</strong> un nom ou un code-barres pris entre-temps, <strong>alors</strong> 409 <code>PROPOSAL_STALE</code> sans effet ; la même demande répétée est dédoublonnée (RG-MCP-140, 141).</li><li><em>(création c. 12)</em> <strong>Étant donné</strong> un produit créé par une proposition, <strong>quand</strong> il est vendu sur une caisse, <strong>alors</strong> la vente se scelle au taux appliqué, chaîne et signature valides, en euro comme en dinar (0,900 DT à 7 % = 59 millimes de TVA) (RG-MCP-140).</li><li><em>(accès limité c. 1, 2, 5)</em> <strong>Étant donné</strong> une clé d&#39;API puis une connexion OAuth limitées au magasin A, <strong>quand</strong> elles lisent la liste, la fiche, l&#39;export, les variantes, les images, la formule, la recette d&#39;un produit propre au magasin B, ou appellent <code>find_product</code>, <strong>alors</strong> rien de B n&#39;est rendu, la fiche répond le même 404 qu&#39;un identifiant inexistant et aucun nom de B n&#39;apparaît ; <strong>quand</strong> une requête SQL lit <code>products</code> ou une table qui suit un produit sous la portée de A, <strong>alors</strong> les lignes de B sont absentes ; une session humaine, une clé complète et un appareil voient tout comme avant (RG-MCP-143).</li><li><em>(accès limité c. 4, et corrections)</em> <strong>Étant donné</strong> une table sous RLS avec une colonne <code>*_store_id</code> ou qui désigne un produit, sans politique <code>store_scope</code>, <strong>alors</strong> le test de schéma échoue en la nommant ; <strong>étant donné</strong> un fil de requête réutilisé, <strong>alors</strong> il ne porte ni le commerce, ni la clé, ni la portée de la requête précédente, même après une erreur (RG-MCP-143).</li><li><em>(accès limité c. 6, 7)</em> <strong>Étant donné</strong> un commerce sans taux, <strong>quand</strong> une clé ou une connexion OAuth lit <code>GET /catalog/tax-rates</code>, <strong>alors</strong> la liste est vide et rien n&#39;est écrit ; une session humaine et les écritures (clé <code>WRITE</code> qui crée un produit, surcharge de magasin, import CSV, proposition validée) ensemencent comme avant (RG-MCP-01, spec 02 RG-CAT-92).</li><li><em>(accès limité c. 9)</em> <strong>Étant donné</strong> <code>PRODUCT_UPDATE</code>, <strong>quand</strong> l&#39;assistant propose un nom à caractère invisible ou à guillemets, <strong>alors</strong> <code>NAME_INVALID</code> ; <strong>quand</strong> il propose le nom d&#39;un autre produit de la portée, actif ou retiré, <strong>alors</strong> <code>PRODUCT_EXISTS</code> avec le candidat ; un nom à marques de direction est enregistré nettoyé, tel qu&#39;affiché ; un nom pris entre-temps rend la proposition périmée (RG-MCP-144).</li><li><em>(lire c. 1, 2)</em> <strong>Étant donné</strong> un accès complet, <strong>quand</strong> <code>find_product</code> trouve un produit de l&#39;entreprise, un produit propre au magasin A, un parent à variantes et une variante, <strong>alors</strong> chaque entrée porte catégorie et <code>ref</code>, portée et magasin d&#39;origine (s&#39;il est dans l&#39;accès), variantes et titres-restaurant ; <strong>étant donné</strong> un produit en rupture et à prix modifié dans A, <strong>alors</strong> la rupture et le prix de A sont rendus ; sans lecture des magasins, au-delà de 6 magasins ou après un échec de lecture (même un seul), <strong>alors</strong> aucun fait par magasin n&#39;est rendu et un avertissement le dit (RG-MCP-142).</li><li><em>(lire c. 3)</em> <strong>Étant donné</strong> un taux inactif et un taux de 200 ‰ nommé « TVA réduite 5,5 % », <strong>quand</strong> l&#39;assistant appelle <code>catalog_reference</code>, <strong>alors</strong> il reçoit les catégories avec leur <code>ref</code> et les seuls taux actifs, dont « TVA réduite 5,5 % — 20 % », sans marque « par défaut », avec la note ; <strong>étant donné</strong> un commerce sans taux, <strong>alors</strong> la liste est vide, la phrase du référentiel non ouvert est rendue et rien n&#39;est écrit (RG-MCP-142, RG-MCP-01).</li><li><em>(lire c. 4)</em> <strong>Étant donné</strong> l&#39;horloge figée au 15/07/2026 22:30 UTC, un magasin à Paris et un à Tunis, <strong>quand</strong> l&#39;assistant appelle <code>list_stores</code>, <strong>alors</strong> Paris porte le 16/07 à 00:30 et Tunis le 15/07 à 23:30 ; une période future est refusée avec la date du jour du magasin (RG-MCP-142).</li><li><em>(étendre c. 1, 2, 3)</em> <strong>Étant donné</strong> un accès complet et un produit propre au magasin A, <strong>quand</strong> l&#39;assistant propose de l&#39;étendre, <strong>alors</strong> 201, magasin de la proposition A, clé <code>PRODUCT_PROMOTE:&lt;A&gt;:&lt;produit&gt;</code>, case présente ; <strong>alors</strong> refus pour un produit de l&#39;entreprise, retiré, à variantes, un magasin actif d&#39;une autre devise ou d&#39;un autre pays fiscal (<code>stores</code>, <code>storeCount</code>, <code>originStore</code>), un nom porté par un produit de l&#39;entreprise ; un accès limité → 403 ; un homonyme propre à un autre magasin → avertissement seulement ; une surcharge de TVA au magasin d&#39;origine → note, prix et taux de la fiche affichés (RG-MCP-145).</li><li><em>(étendre c. 4, 5, 7)</em> <strong>Étant donné</strong> la proposition en attente, <strong>quand</strong> un gérant valide avec la case, <strong>alors</strong> 403, rien d&#39;écrit, aucun événement, proposition en attente ; <strong>quand</strong> le propriétaire valide sans la case, <strong>alors</strong> 422 ; avec la case, <strong>alors</strong> la ligne <code>products</code> et les événements sont identiques à une promotion humaine ; chaque cause de péremption → 409 ; une proposition <code>PRODUCT_UPDATE</code> en attente sur le produit est périmée après la promotion (RG-MCP-145).</li><li><em>(étendre c. 6)</em> <strong>Étant donné</strong> un commerce à un magasin en euro et un en dinar, <strong>quand</strong> le propriétaire étend par la route humaine un produit en dinar, <strong>alors</strong> 422 <code>PROMOTE_CURRENCY_MISMATCH</code>, rien d&#39;écrit ; même devise et autre pays fiscal → <code>PROMOTE_COUNTRY_MISMATCH</code> ; parent à variantes → <code>PRODUCT_VARIANT_NOT_SUPPORTED</code> ; version attendue périmée → 409 (spec 14 RG-MSTORE-19).</li><li><em>(prix groupé c. 1, 2, 4)</em> <strong>Étant donné</strong> <code>POS_AGENT_PROPOSALS_TYPES</code> avec <code>PRICE_CHANGE</code> seul, <strong>quand</strong> un accès crée un groupe, <strong>alors</strong> 404 et le prix simple reste accepté ; <strong>avec</strong> <code>PRICE_CHANGE_GROUP</code>, <strong>alors</strong> 201, clé <code>GROUP</code> dès 2 lignes, notification « N produits » sans montant ; chaque code du contrat, chaque champ fermé aux trois emplacements et un accès limité sans <code>storeId</code> (403) sont refusés, rien d&#39;écrit ; un corps avec <code>product</code> à la racine et <code>lines</code> reste un prix simple (<code>FIELD_NOT_ALLOWED</code>) (RG-MCP-146).</li><li><em>(prix groupé c. 3, 5)</em> <strong>Étant donné</strong> des prix de 1,95 €, 2,40 € et une surcharge à 2,10 €, <strong>quand</strong> l&#39;assistant propose +0,10 €, +5 % puis −5 %, <strong>alors</strong> 2,05 / 2,50 / 2,20, 2,05 / 2,52 / 2,21 et 2,10 € → 2,00 €, calculés en entiers ; le taux de marque suit le taux de TVA effectif ; une ligne sous le coût porte « Sous le coût » et la note de revente à perte ; un prix actuel à 0 ne lève pas d&#39;erreur (RG-MCP-146).</li><li><em>(prix groupé c. 6 à 9)</em> <strong>Étant donné</strong> un groupe de 2 lignes ou plus, <strong>quand</strong> il est validé sans case, <strong>alors</strong> 422 <code>CONFIRMATION_REQUIRED</code> ; groupe de l&#39;entreprise sur une caisse → 403 ; une ligne changée (cinq causes) → 409, aucune ligne appliquée ; deux groupes aux lignes communes en ordre inverse, ou un groupe et un push de vente, ne s&#39;interbloquent pas ; la TVA reste intacte ; chaque ligne appliquée laisse un audit portant l&#39;identifiant de la proposition ; le prix simple d&#39;un magasin sur une variante reste appliqué (RG-MCP-146).</li><li><em>(prix groupé c. 11, 12)</em> <strong>Étant donné</strong> le jeton allumé, <strong>quand</strong> l&#39;assistant reçoit « augmente tous les cafés de 0,10 € », <strong>alors</strong> il lit <code>find_product</code> avec <code>in_category</code> puis appelle une fois <code>propose_price_changes</code> en <code>change</code> ; sans le jeton l&#39;outil est absent ; <strong>alors</strong> les caisses montrent le total signé du serveur, « Appliquer les N prix » et, dès que l&#39;aperçu tronque, les lignes signalées d&#39;abord (tous types) (RG-MCP-147).</li><li><em>(catégories c. 1 à 4)</em> <strong>Étant donné</strong> un accès complet et les types allumés, <strong>quand</strong> il propose « Glaces » dans « Desserts » ou de renommer, déplacer, réordonner une catégorie, <strong>alors</strong> 201, sans magasin ni devise ; chaque champ fermé (fiscaux compris), <code>prd_…</code> sans requête, quatrième niveau, cycle, nom pris par une autre catégorie sont refusés ; un accès limité → 403 ; déplacer l&#39;un de deux homonymes désigné par sa <code>ref</code> passe (RG-MCP-148, 149).</li><li><em>(catégories c. 5 à 8)</em> <strong>Étant donné</strong> une proposition en attente, <strong>quand</strong> un gérant la valide au back-office, <strong>alors</strong> la ligne, les événements et l&#39;audit sont ceux du geste humain ; sur une caisse → 403 ; chaque cause de péremption → 409 ; <code>place: FIRST</code> donne le plus petit ordre des sœurs − 1 lu sous le verrou ; l&#39;affichage montre des chemins isolés, « 1 sur 5 », aucune valeur « avant » à la création, des notes <code>INFO</code> (RG-MCP-148, 149).</li><li><em>(catégories c. 9)</em> <strong>Étant donné</strong> deux déplacements croisés, ou une création et un renommage vers le même nom, validés en même temps, <strong>alors</strong> aucun cycle, une seule appliquée ; un import et une proposition de catégorie ne s&#39;interbloquent pas (RG-MCP-148, 149, spec 02 RG-CAT-94).</li><li><em>(catégories c. 10)</em> <strong>Étant donné</strong> les types créables, <strong>quand</strong> l&#39;assistant reçoit « mets les desserts en premier sur la borne », <strong>alors</strong> il appelle <code>propose_category</code> avec <code>place: first</code> (ou un <code>sort_order</code> après <code>catalog_reference</code>, dont la position suit l&#39;ordre du serveur) ; sans les types, l&#39;outil est absent (RG-MCP-150).</li></ol><h2 id="_11-dependances" tabindex="-1">11. Dépendances <a class="header-anchor" href="#_11-dependances" aria-label="Permalink to &quot;11. Dépendances&quot;">​</a></h2><ul><li>Spec 01 § 6 (clés d&#39;API, portées), spec 17 RG-PLAT-13 / 58 / 59 (formules, droit <code>MCP_ACCESS</code>, arrêt global), spec 13 (page Réglages › Clés d&#39;API), spec 12 (rapports lus par les outils).</li><li>Lot VEN-34 : spec 07 RG-SUP-04 → 08 (bons de commande), spec 02 / 14 (prix, surcharges), spec 12 CA-RPT-09 et § 4.2 (alertes anti-fraude, alertes des responsables), RG-RPT-03 (fraîcheur), spec 01 (PIN manager), spec 17 RG-PLAT-15 (limites non rétroactives, dérogations).</li><li>Lots suivants : M2 (page « Assistant IA », hébergement sans mise en veille) ; après VEN-34 : GaaS A1 (agents planifiés, <code>EXECUTE_WITH_APPROVAL</code>), A7 (quotas réglables par formule, facturation).</li><li>Projet P-VEN-7 (écriture étendue) : jalon 1 = VEN-45, 46, 47, 48 ; jalons 2 à 6 = VEN-49 → 56 et VEN-60, chacun s&#39;appuyant sur le service humain de sa spec (02 catalogue, 05 stock, 07 achats, 08 restaurant, 06 fidélité, 01 / 11 / 13 / 14 / 16 réglages et appareils) ; jalon 7 = VEN-57, 58, 59. Avis <code>expert-fiscal</code> requis sur RG-MCP-107, 122, 125 et sur chaque famille avant son allumage.</li></ul></div>',1)])])}const m=o(r,[["render",a]]);export{g as __pageData,m as default};
